INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。"}, {"text": "直属", "is_correct": false, "explanation": "直属（zhí shǔ）第二个音节的声调不同：shǔ 为第三声，shù 为第四声，意思是直接隶属。"}, {"text": "植物", "is_correct": false, "explanation": "植物（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是生物的一类。"}, {"text": "指数", "is_correct": false, "explanation": "指数（zhǐ shù）第一个音节的声调不同：zhǐ 为第三声，zhí 为第二声，意思是表示变化程度的数值。"}], "explanations": {"植树": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。", "直属": "直属（zhí shǔ）第二个音节的声调不同：shǔ 为第三声，shù 为第四声，意思是直接隶属。", "植物": "植物（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是生物的一类。", "指数": "指数（zhǐ shù）第一个音节的声调不同：zhǐ 为第三声，zhí 为第二声，意思是表示变化程度的数值。"}, "sentence_index": null, "correct_answer": "植树"}, "level_3": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树：把树苗栽种到土里，与“季节性任务”和“树苗存活率”的语境一致。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是人的本能，不能被视为季节性任务，与后文记录树苗存活率的语境冲突。"}, {"text": "尊重", "is_correct": false, "explanation": "搭配：“尊重”指对人或规则的态度，与“季节性任务”的常规搭配不符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是可以安排的任务，与句中“持续性的本地行动”的语义相反。"}], "explanations": {"植树": "植树：把树苗栽种到土里，与“季节性任务”和“树苗存活率”的语境一致。", "呼吸": "语义：呼吸是人的本能，不能被视为季节性任务，与后文记录树苗存活率的语境冲突。", "尊重": "搭配：“尊重”指对人或规则的态度，与“季节性任务”的常规搭配不符。", "生病": "语义：生病不是可以安排的任务，与句中“持续性的本地行动”的语义相反。"}, "sentence_index": 0, "correct_answer": "植树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁把修剪下来的枝条拿去植树。", "explanation": "这里应该用〈扦插〉。扦插是把枝条插入土中繁殖，植树指栽种树苗，不用于枝条。"}, {"text": "这些花，我打算在院子里植树。", "explanation": "这里应该用〈栽〉。植树指栽种树木，这些是花卉，应该说栽花，不能用植树。"}, {"text": "妈妈每天在厨房里植树。", "explanation": "植树需要在土地上栽种树苗，厨房里不能植树，这里应该用〈做饭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。"}, {"text": "职务", "is_correct": false, "explanation": "职务（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是工作中的职位和责任。"}, {"text": "执事", "is_correct": false, "explanation": "执事（zhí shì）第二个音节的韵母不同：shì 为 i 韵，shù 为 u 韵，意思是负责办事的人。"}, {"text": "志书", "is_correct": false, "explanation": "志书（zhì shū）两个音节的声调都不同：zhì 为第四声，zhí 为第二声；shū 为第一声，shù 为第四声，意思是地方志。"}], "explanations": {"植树": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。", "职务": "职务（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是工作中的职位和责任。", "执事": "执事（zhí shì）第二个音节的韵母不同：shì 为 i 韵，shù 为 u 韵，意思是负责办事的人。", "志书": "志书（zhì shū）两个音节的声调都不同：zhì 为第四声，zhí 为第二声；shū 为第一声，shù 为第四声，意思是地方志。"}, "sentence_index": null, "correct_answer": "植树"}, "level_3": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树：栽树使地方变得更干净，与“可以让空气变得更干净”的语境一致。"}, {"text": "吸烟", "is_correct": false, "explanation": "语义：吸烟会污染空气，与“更干净”的结果相反。"}, {"text": "烧纸", "is_correct": false, "explanation": "语义：烧纸会产生烟尘，与“让空气变得更干净”的语境冲突。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买是买东西的行为，“购买可以让空气变得更干净”说不通，与语境无关。"}], "explanations": {"植树": "植树：栽树使地方变得更干净，与“可以让空气变得更干净”的语境一致。", "吸烟": "语义：吸烟会污染空气，与“更干净”的结果相反。", "烧纸": "语义：烧纸会产生烟尘，与“让空气变得更干净”的语境冲突。", "购买": "语义：购买是买东西的行为，“购买可以让空气变得更干净”说不通，与语境无关。"}, "sentence_index": 6, "correct_answer": "植树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小麦在田里植树。", "explanation": "这里应该用〈生长〉。植树的施动者是人，指人栽种树木；小麦是农作物，不能植树，应该说小麦在生长。"}, {"text": "他的心脏每天都在植树。", "explanation": "这里应该用〈跳动〉。植树是人在土地上栽种树木的动作，心脏只能跳动，不能植树。"}, {"text": "这张桌子每天都在植树。", "explanation": "这里应该用〈放〉或〈摆〉。植树的施动者是人，桌子是家具，不能植树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，我们把山坡上植树。", "corrected_sentence": "春天到了，我们在山坡上植树。", "error_description": "误用“把”字句。“把”后的宾语应是被处置的事物，这里却接了地点“山坡上”；地点应改用介词“在”引出，应为“在山坡上植树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年秋天，我们了植树。", "corrected_sentence": "去年秋天，我们植了树。", "error_description": "完成标记“了”应紧跟动词之后。错误形式把“了”放在“植树”之前，应为“植了树”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指风和被风吹起的沙土，常形容天气恶劣，也比喻艰难的环境。", "primary_collocate": null, "pronunciation": "fēng shā", "ipa": "fɤŋ˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "风沙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "春天北方常有风沙，出门要戴口罩。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在风沙里走了一整天。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的风沙很大，树都长不高。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了挡住风沙，村民在村外种了很多树。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这些年在外经历过不少风沙，什么苦都吃过。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠边的小城常有风沙，人们都很习惯。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风沙过后，街上的车都变黄了。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，再大的风沙，也挡不住回家的路。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在治理风沙，希望天空变得更蓝。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场风沙", "label": "量词"}, {"form": "一阵风沙", "label": "量词"}, {"form": "風沙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风与被风吹起的沙土；恶劣天气，也比喻艰难处境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc47638d-8454-4a74-8064-965a8426d1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风沙", "is_correct": true, "explanation": "风沙指被风吹起的沙土，“饱受风沙侵袭”说村落长期遭受风沙危害，句意通顺。"}, {"text": "掌声", "is_correct": false, "explanation": "语义：掌声是赞扬的声音，不是能侵袭村落的东西，“饱受掌声侵袭”说不通。"}, {"text": "嘴皮子", "is_correct": false, "explanation": "语域：“嘴皮子”是口语说法，与这段书面描述的语体不合，而且不能用来“侵袭”村落。"}, {"text": "收成", "is_correct": false, "explanation": "搭配：“侵袭”的施事多是风沙、洪水之类的灾害，“收成”是结果，不能充当施事，“饱受收成侵袭”说不通。"}], "explanations": {"风沙": "风沙指被风吹起的沙土，“饱受风沙侵袭”说村落长期遭受风沙危害，句意通顺。", "掌声": "语义：掌声是赞扬的声音，不是能侵袭村落的东西，“饱受掌声侵袭”说不通。", "嘴皮子": "语域：“嘴皮子”是口语说法，与这段书面描述的语体不合，而且不能用来“侵袭”村落。", "收成": "搭配：“侵袭”的施事多是风沙、洪水之类的灾害，“收成”是结果，不能充当施事，“饱受收成侵袭”说不通。"}, "sentence_index": 0, "correct_answer": "风沙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一只风沙吹进了屋里，桌上全是沙子。", "explanation": "这里量词用错。〈只〉多用于动物或成对物品中的一个，风沙是成片吹来的天气现象，应该用〈阵〉或〈场〉。"}, {"text": "一颗风沙打在脸上，很疼。", "explanation": "这里量词用错。〈颗〉用于颗粒状的小东西，风沙应该用〈阵〉或〈股〉。"}, {"text": "他把鞋里的风沙倒了出来。", "explanation": "这里应该用〈沙子〉。风沙是风和被风吹起的沙土，是一种天气，不能像沙子那样从鞋里倒出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风沙", "is_correct": true, "explanation": "风沙指被风吹起的沙土，“沙漠边的小城常有风沙，人们都很习惯”符合常识，句意通顺。"}, {"text": "海浪", "is_correct": false, "explanation": "搭配：“常有”后接的自然现象要和沙漠环境相配，沙漠边的小城不会常有海浪。"}, {"text": "荷花", "is_correct": false, "explanation": "语义：荷花生长在水中，沙漠边的小城不可能常有荷花，句意说不通。"}, {"text": "雪崩", "is_correct": false, "explanation": "语义：雪崩出现在雪山地区，与沙漠环境完全不符，句子不成立。"}], "explanations": {"风沙": "风沙指被风吹起的沙土，“沙漠边的小城常有风沙，人们都很习惯”符合常识，句意通顺。", "海浪": "搭配：“常有”后接的自然现象要和沙漠环境相配，沙漠边的小城不会常有海浪。", "荷花": "语义：荷花生长在水中，沙漠边的小城不可能常有荷花，句意说不通。", "雪崩": "语义：雪崩出现在雪山地区，与沙漠环境完全不符，句子不成立。"}, "sentence_index": 6, "correct_answer": "风沙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的风沙很凉快，大家都在院子里乘凉。", "explanation": "这里应该用〈海风〉。海风带来凉爽，风沙裹着沙土，只会让人觉得干燥和呛人，不能说凉快。"}, {"text": "这场风沙来得正好，庄稼都绿了。", "explanation": "这里应该用〈春雨〉。庄稼变绿是春雨滋润的结果，风沙只带沙土，只会伤害庄稼。"}, {"text": "远处刮来一根风沙，打在脸上很疼。", "explanation": "这里量词用错。〈根〉用于细长的东西，风沙应该用〈阵〉或〈股〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天刮了一个风沙，学校的操场上全是沙子。", "corrected_sentence": "昨天刮了一场风沙，学校的操场上全是沙子。", "error_description": "量词错误：“风沙”的正确说法是“一场风沙”或“一阵风沙”，说成“一个风沙”是错的。“个”不能用来计量风沙这类天气现象，应该用“场”或“阵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚起了一扇风沙，我们只好待在屋里。", "corrected_sentence": "傍晚起了一阵风沙，我们只好待在屋里。", "error_description": "量词错误：“风沙”应说“一阵风沙”，说成“一扇风沙”是错的。“扇”用于门窗之类的东西，不能计量风沙，正确的量词是“阵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
