INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "突然进攻或危害，让人或事物受到破坏或影响。", "primary_collocate": null, "pronunciation": "qīn xí", "ipa": "tɕʰin˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "侵袭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "台风侵袭了南方沿海的小城。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "寒流侵袭北方，气温一下子降了十度。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨侵袭这座城市，街上全是水。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病毒侵袭身体时，人会发烧。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的房子常年受到海风侵袭。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水侵袭村子的那天晚上，大家都没睡。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止虫子侵袭，农民在田里喷了药。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪侵袭山区，路上的车都停下来了。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙尘暴侵袭这个地区时，天空一片黄色。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵袭了", "label": "体标"}, {"form": "侵袭着", "label": "体标"}, {"form": "侵袭过", "label": "体标"}, {"form": "侵襲", "label": "繁体"}], "register": "书面", "sense_fingerprint": "灾害、寒潮、病毒等突然来犯并造成破坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc47638d-8454-4a74-8064-965a8426d1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵袭", "is_correct": true, "explanation": "侵袭指突然来犯并造成破坏，“饱受风沙侵袭的村落”说村落长期遭受风沙危害，句意通顺。"}, {"text": "滋润", "is_correct": false, "explanation": "语义：“饱受”后接的应是负面遭遇，“滋润”是正面的好处，与句意矛盾。"}, {"text": "庇护", "is_correct": false, "explanation": "语义：风沙是危害，村落不会被风沙“庇护”，这个说法与句子的意思相反。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是器物或环境，风沙不能被“装饰”，与“饱受”搭配不当。"}], "explanations": {"侵袭": "侵袭指突然来犯并造成破坏，“饱受风沙侵袭的村落”说村落长期遭受风沙危害，句意通顺。", "滋润": "语义：“饱受”后接的应是负面遭遇，“滋润”是正面的好处，与句意矛盾。", "庇护": "语义：风沙是危害，村落不会被风沙“庇护”，这个说法与句子的意思相反。", "装饰": "搭配：“装饰”的对象是器物或环境，风沙不能被“装饰”，与“饱受”搭配不当。"}, "sentence_index": 0, "correct_answer": "侵袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有人侵袭了他的隐私，他很生气。", "explanation": "这里应该用〈侵犯〉。侵袭多指灾害、病菌突然来袭造成损害，隐私是个人权利，要说“侵犯”。"}, {"text": "这篇文章侵袭了他的观点，大家都不同意。", "explanation": "这里应该用〈攻击〉。侵袭不用于言论和观点，批驳别人的观点要说“攻击”。"}, {"text": "他侵袭了桌上的蛋糕，很快就吃光了。", "explanation": "这里应该用〈吃〉。侵袭指突然进攻或危害，让事物受到破坏，吃东西不是侵害，不能说侵袭蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵袭", "is_correct": true, "explanation": "侵袭指突然来犯并造成破坏，“洪水侵袭村子的那天晚上”说洪水来袭村子，句意通顺。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：照顾的对象是需要关照的人，洪水不会照顾村子，句意说不通。"}, {"text": "关心", "is_correct": false, "explanation": "语义：关心需要有感情的主体，洪水没有感情，不能关心村子。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”要求有意愿的人做主语，洪水不能欢迎村子。"}], "explanations": {"侵袭": "侵袭指突然来犯并造成破坏，“洪水侵袭村子的那天晚上”说洪水来袭村子，句意通顺。", "照顾": "语义：照顾的对象是需要关照的人，洪水不会照顾村子，句意说不通。", "关心": "语义：关心需要有感情的主体，洪水没有感情，不能关心村子。", "欢迎": "配价：“欢迎”要求有意愿的人做主语，洪水不能欢迎村子。"}, "sentence_index": 6, "correct_answer": "侵袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他侵袭了朋友的感情，朋友很伤心。", "explanation": "这里应该用〈欺骗〉。侵袭不用于人对人的感情伤害，欺骗别人的感情要说“欺骗”。"}, {"text": "他侵袭了别人的作品，被大家批评了。", "explanation": "这里应该用〈抄袭〉。侵袭不用于窃取他人作品，把别人的作品当成自己的要说“抄袭”。"}, {"text": "同学们侵袭了他的口音，他很难过。", "explanation": "这里应该用〈嘲笑〉。侵袭不用于言语上的取笑，拿别人的口音开玩笑要说“嘲笑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年夏天，台风侵袭的我们的小区。", "corrected_sentence": "去年夏天，台风侵袭了我们的小区。", "error_description": "助词误用：动态助词“了”误作结构助词“的”，应说“台风侵袭了我们的小区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场大雨侵袭得城北的村子。", "corrected_sentence": "一场大雨侵袭了城北的村子。", "error_description": "结构错误：“侵袭”带宾语时，完成的动作应用动词后的“了”，不能用“得”直接接宾语，应说“一场大雨侵袭了城北的村子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
