INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13493, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指长期居住在农村的人。", "primary_collocate": null, "pronunciation": "cūn mín", "ipa": "tsʰuən˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "村民们每天天亮就下地干活。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位村民养了二十头羊。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们都很欢迎新来的医生。", "target_word": "村民", "complexity_tier": "T3", "furigana": "cūn mín men dōu hěn huān yíng xīn lái de yī shēng。", "sentence_source": "generated"}, {"text": "下雨以后，村民们去河边修路。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位老村民给我们讲了村子的故事。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县里的干部来村里和村民开会。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们把自己种的菜拿到集市上卖。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村的村民大多数都种玉米。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了修水渠，全体村民一起出钱出力。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "村民委员会", "label": "复合"}], "register": "通用", "sense_fingerprint": "长期居住在农村的人，强调当地居民身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc47638d-8454-4a74-8064-965a8426d1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村民", "is_correct": true, "explanation": "“村民”指长期住在农村的人，能够自发组织运动，与“生态复兴运动”的语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有组织能力，不能自发组织运动，与句意矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作为“组织”的主体，搭配不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能作为组织运动的主体。"}], "explanations": {"村民": "“村民”指长期住在农村的人，能够自发组织运动，与“生态复兴运动”的语境相合。", "石头": "语义：石头没有组织能力，不能自发组织运动，与句意矛盾。", "天气": "搭配：“天气”不能作为“组织”的主体，搭配不通。", "身高": "体貌：“身高”是人的外形特征，不能作为组织运动的主体。"}, "sentence_index": 0, "correct_answer": "村民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是城里的村民，从来不住在农村。", "explanation": "此处应该用〈居民〉。“村民”指长期住在农村的人，与“城里”“从来不住在农村”矛盾。"}, {"text": "公司里的村民全都是穿西装的白领。", "explanation": "此处应该用〈职员〉。“村民”指长期住在农村的人，与“穿西装的白领”的身份不符。"}, {"text": "县里的干部都是村民，每天下乡调研。", "explanation": "此处应该用〈干部〉。“村民”指农村居民，与“县里的干部”“下乡调研”的身份矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村民", "is_correct": true, "explanation": "“村民”指长期住在农村的人，是与县里干部开会的对象，符合句中语境。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物无法参与开会，与“和……开会”的人类参与者不符。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”是书籍，不能作为“开会”的对象，搭配不通。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“开会”的参与者须是人，“窗户”不能作为“和……开会”的对象。"}], "explanations": {"村民": "“村民”指长期住在农村的人，是与县里干部开会的对象，符合句中语境。", "植物": "语义：植物无法参与开会，与“和……开会”的人类参与者不符。", "课本": "搭配：“课本”是书籍，不能作为“开会”的对象，搭配不通。", "窗户": "配价：“开会”的参与者须是人，“窗户”不能作为“和……开会”的对象。"}, "sentence_index": 6, "correct_answer": "村民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来村里旅游的村民很多，他们每天都住在酒店。", "explanation": "此处应该用〈游客〉。“村民”指长期住在农村的人，与“旅游”“住在酒店”的身份不符。"}, {"text": "我的邻居是个村民，他每天在省城的大学里教书。", "explanation": "此处应该用〈教师〉。“村民”指长期住在农村的人，与“在省城大学里教书”的身份不符。"}, {"text": "这几位村民刚下飞机，是第一次来中国的外国游客。", "explanation": "此处应该用〈游客〉。“村民”指长期住在农村的人，与“第一次来中国的外国游客”的身份矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三位村民们都很热心。", "corrected_sentence": "三位村民都很热心。", "error_description": "“们”多余：“们”不能加在带数量词的名词后面，应去掉“们”，说“三位村民都很热心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只村民很热心。", "corrected_sentence": "一位村民很热心。", "error_description": "量词错误：“村民”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物）。说成“一只村民”是错的，正确说法是“一位村民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
