INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13494, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生态环境或社区生活重新变得有活力", "primary_collocate": null, "pronunciation": "fù xīng", "ipa": "fu˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "经过治理，这片森林又复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人回来以后，小村子慢慢复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里开了新市场，老街又复兴起来。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府希望这条老街能够复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种树以后，山区的生态开始复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家努力让社区生活复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水干净了，岸边的小镇也复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地复兴以后，很多鸟飞回来了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要让老城区复兴，先要修好路。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复兴了", "label": "体标"}, {"form": "復興", "label": "繁体"}, {"form": "复兴运动", "label": "复合"}], "register": "书面", "sense_fingerprint": "生态环境或社区生活恢复活力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc47638d-8454-4a74-8064-965a8426d1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复兴", "is_correct": true, "explanation": "复兴（fù xīng）指生态环境或社区生活重新恢复活力，是正确答案。"}, {"text": "福星", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。"}, {"text": "复醒", "is_correct": false, "explanation": "xǐng（第三声）与 xīng（第一声）声调不同，复醒意思是再次醒来。"}, {"text": "复新", "is_correct": false, "explanation": "xīn 与 xīng 的韵母不同（in/ing），复新意思是再次变新。"}, {"text": "赋性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，赋性意思是天生的性情。"}], "explanations": {"复兴": "复兴（fù xīng）指生态环境或社区生活重新恢复活力，是正确答案。", "福星": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。", "复醒": "xǐng（第三声）与 xīng（第一声）声调不同，复醒意思是再次醒来。", "复新": "xīn 与 xīng 的韵母不同（in/ing），复新意思是再次变新。", "赋性": "xìng（第四声）与 xīng（第一声）声调不同，赋性意思是天生的性情。"}, "sentence_index": null, "correct_answer": "复兴"}, "level_3": {"options": [{"text": "复兴", "is_correct": true, "explanation": "“生态复兴运动”指生态环境重新获得活力的运动，符合前文“重塑人与土地的关系”的积极语境。"}, {"text": "衰退", "is_correct": false, "explanation": "语义：衰退指衰落、减弱，与“重塑人与土地的关系”的建设性语境相反。"}, {"text": "退化", "is_correct": false, "explanation": "语义：退化指变坏，村民自发组织的运动不可能是导致生态变坏的运动。"}, {"text": "破坏", "is_correct": false, "explanation": "搭配：“破坏运动”指以破坏为目的的运动，与“生态”及“自发组织”修复生态的语境冲突。"}], "explanations": {"复兴": "“生态复兴运动”指生态环境重新获得活力的运动，符合前文“重塑人与土地的关系”的积极语境。", "衰退": "语义：衰退指衰落、减弱，与“重塑人与土地的关系”的建设性语境相反。", "退化": "语义：退化指变坏，村民自发组织的运动不可能是导致生态变坏的运动。", "破坏": "搭配：“破坏运动”指以破坏为目的的运动，与“生态”及“自发组织”修复生态的语境冲突。"}, "sentence_index": 0, "correct_answer": "复兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经过治疗，他的视力复兴了。", "explanation": "这里应该用〈恢复〉。复兴指衰落的事业、地区或文化重新兴盛，视力下降后的好转要用恢复。"}, {"text": "他的病情慢慢复兴了。", "explanation": "这里应该用〈好转〉。复兴多用于社会、文化、地区等，病情的变化要用好转。"}, {"text": "那幅被烧坏的古画已经复兴了。", "explanation": "这里应该用〈复原〉。复原指恢复原样，多用于文物和画作，复兴不用于修复器物或艺术品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13494, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "复兴", "is_correct": true, "explanation": "复兴（fù xīng）指生态环境或社区生活重新恢复活力，是正确答案。"}, {"text": "复行", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，复行意思是再次行走或重新施行。"}, {"text": "复性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，复性意思是恢复本性。"}, {"text": "复醒", "is_correct": false, "explanation": "xǐng（第三声）与 xīng（第一声）声调不同，复醒意思是再次醒来。"}], "explanations": {"复兴": "复兴（fù xīng）指生态环境或社区生活重新恢复活力，是正确答案。", "复行": "xíng（第二声）与 xīng（第一声）声调不同，复行意思是再次行走或重新施行。", "复性": "xìng（第四声）与 xīng（第一声）声调不同，复性意思是恢复本性。", "复醒": "xǐng（第三声）与 xīng（第一声）声调不同，复醒意思是再次醒来。"}, "sentence_index": null, "correct_answer": "复兴"}, "level_3": {"options": [{"text": "复兴", "is_correct": true, "explanation": "“让社区生活复兴”指使社区生活重新恢复活力，与“努力”的积极目标一致。"}, {"text": "萎缩", "is_correct": false, "explanation": "语义：萎缩指缩小、衰弱，与“努力”追求的目标相反。"}, {"text": "凋零", "is_correct": false, "explanation": "语义：凋零指衰败、消逝，与“努力”追求的目标相反。"}, {"text": "扰乱", "is_correct": false, "explanation": "配价：“扰乱”是及物动词，需要受事宾语，“让社区生活扰乱”缺少宾语，应说“扰乱社区生活”。"}], "explanations": {"复兴": "“让社区生活复兴”指使社区生活重新恢复活力，与“努力”的积极目标一致。", "萎缩": "语义：萎缩指缩小、衰弱，与“努力”追求的目标相反。", "凋零": "语义：凋零指衰败、消逝，与“努力”追求的目标相反。", "扰乱": "配价：“扰乱”是及物动词，需要受事宾语，“让社区生活扰乱”缺少宾语，应说“扰乱社区生活”。"}, "sentence_index": 6, "correct_answer": "复兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队输了比赛，教练努力让队员的伤腿复兴。", "explanation": "这里应该用〈痊愈〉。复兴指事业、地区等衰落后重新兴盛，伤病的康复要用痊愈。"}, {"text": "这台老机器经过维修，终于复兴了。", "explanation": "这里应该用〈修复〉。修复指把损坏的机器或设施修好，复兴不用于机器的修理。"}, {"text": "公司亏了很多钱，他努力复兴了损失。", "explanation": "这里应该用〈挽回〉。挽回指收回失去的东西，如损失、面子，复兴不能与损失搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子的生态慢慢复兴下来了。", "corrected_sentence": "这个村子的生态慢慢复兴起来了。", "error_description": "补语错误：“复兴”后应接“起来”，表示由弱变强；“下来”表示向下，与“复兴”的向上之意相反，应说“复兴起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小镇在十年后很复兴了。", "corrected_sentence": "这座小镇在十年后终于复兴了。", "error_description": "副词错误：“复兴”是变化类动词，一般不受程度副词“很”修饰；应把“很”换成“终于”，说“终于复兴了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
