INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13499, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13499, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示最初、开始的时候。", "primary_collocate": null, "pronunciation": "qǐ chū", "ipa": "tɕʰi²¹⁴ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "起初", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "起初我不会说汉语，现在可以聊天了。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初他不喜欢这个城市，后来慢慢习惯了。", "target_word": "起初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店起初很小，后来越开越大。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初大家都不同意，最后还是答应了。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我起初以为他是老师，其实他是医生。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初天气很好，后来突然下雨了。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他起初很紧张，后来说话的声音越来越大。", "target_word": "起初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起初没有人相信我，现在大家都明白了。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园起初没有树，现在到处都是花草。", "target_word": "起初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "起初：副词，表示最初、开始的时候，常与后来、现在对照", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3577d48b-24c3-4d33-8220-9ae01fac4ab5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起初", "is_correct": true, "explanation": "正确：“起初”表示最初的情况，与后面“如今已演变为”的变化形成对照。"}, {"text": "如今", "is_correct": false, "explanation": "语义：“如今”指现在，与后文的“如今”重复，而且句子要说的是最初的情况。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”说始终如此，与后文“已演变为”的变化相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”强调已完成的状态，与“只是”及表示最初的语境搭配不当。"}], "explanations": {"起初": "正确：“起初”表示最初的情况，与后面“如今已演变为”的变化形成对照。", "如今": "语义：“如今”指现在，与后文的“如今”重复，而且句子要说的是最初的情况。", "一直": "语义：“一直”说始终如此，与后文“已演变为”的变化相矛盾。", "已经": "搭配：“已经”强调已完成的状态，与“只是”及表示最初的语境搭配不当。"}, "sentence_index": 0, "correct_answer": "起初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议起初就已经结束了。", "explanation": "这里应该用〈最后〉。起初指开始的阶段，不能与“已经结束”搭配，表示结束的先后应说最后。"}, {"text": "明年起初我们要搬到北京。", "explanation": "这里应该用〈开始〉。起初强调一个过程的最初阶段，不能用来限定“搬到北京”这样的一次性安排；应说“明年开始我们要搬到北京。”"}, {"text": "我现在起初会说汉语了。", "explanation": "这里应该删去〈起初〉。起初表示过去的开始阶段，单独与“现在”连用缺少对照，不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起初", "is_correct": true, "explanation": "正确：“起初”表示开始的阶段，与后面“后来突然下雨了”的变化相连。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”说一直如此，与后句“后来突然下雨了”的变化相矛盾。"}, {"text": "最后", "is_correct": false, "explanation": "语义：“最后”指结束的时候，与“后来”的先后顺序冲突，句子不通。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用，不说“从来天气很好”。"}], "explanations": {"起初": "正确：“起初”表示开始的阶段，与后面“后来突然下雨了”的变化相连。", "总是": "语义：“总是”说一直如此，与后句“后来突然下雨了”的变化相矛盾。", "最后": "语义：“最后”指结束的时候，与“后来”的先后顺序冲突，句子不通。", "从来": "搭配：“从来”通常与否定词连用，不说“从来天气很好”。"}, "sentence_index": 6, "correct_answer": "起初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们起初已经学习了三年汉语。", "explanation": "这里应该用〈以前〉。起初指最开始的阶段，不能用来描述已经持续三年的学习，较早的一段时间应说以前。"}, {"text": "起初，他终于找到了工作。", "explanation": "这里应该用〈最后〉。“终于”表示最后的结果，与“起初”（开始）相矛盾。"}, {"text": "起初，我们才知道真相。", "explanation": "这里应该用〈后来〉。“才”表示较晚发生，与“起初”（最开始）相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我起初的住在城里，后来搬到了农村。", "corrected_sentence": "我起初住在城里，后来搬到了农村。", "error_description": "错误在于“起初”后多加了“的”。“起初”是副词，不能带“的”，应说“我起初住在城里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我起初了很担心，后来就放心了。", "corrected_sentence": "我起初很担心，后来就放心了。", "error_description": "错误在于“起初”后多加了“了”。“起初”是表示开始阶段的副词，后面不带“了”，应说“我起初很担心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
