INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "退出工作岗位，不再从事职业活动。", "primary_collocate": null, "pronunciation": "tuì xiū", "ipa": "tʰweɪ̯⁵¹ ɕjoʊ̯⁵⁵", "syllable_count": 2, "sentences": [{"text": "我爸爸明年就要退休了。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶是老师，已经退休五年了。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他六十岁退休，现在每天在家养花。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人退休以后喜欢去旅行。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王经理退休那天，同事们送了他一束花。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给退休的老人发了一份礼物。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想早点退休，去海边生活。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国男人一般六十岁退休。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老张退休后没有闲着，还在学校帮忙。", "target_word": "退休", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还没退休，每天都要上班。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "退休了", "label": "体标"}, {"form": "退休金", "label": "复合"}, {"form": "退休年龄", "label": "复合"}], "register": "中性", "sense_fingerprint": "退休：到年龄后正式离开工作岗位，不再从事职业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3577d48b-24c3-4d33-8220-9ae01fac4ab5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": true, "explanation": "正确：“退休”表示离开工作岗位，与“我爸爸明年就要……了”的语境相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指结束学业，不能用于爸爸离开工作岗位。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与“我爸爸明年”的语境明显不符。"}, {"text": "辞退", "is_correct": false, "explanation": "配价：“辞退”是及物动词，需要带宾语或用“被”字，不能单独说“就要辞退了”。"}], "explanations": {"退休": "正确：“退休”表示离开工作岗位，与“我爸爸明年就要……了”的语境相符。", "毕业": "语义：“毕业”指结束学业，不能用于爸爸离开工作岗位。", "出生": "语义：“出生”指人降生，与“我爸爸明年”的语境明显不符。", "辞退": "配价：“辞退”是及物动词，需要带宾语或用“被”字，不能单独说“就要辞退了”。"}, "sentence_index": 0, "correct_answer": "退休"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为成绩不好，决定退休了。", "explanation": "这里应该用〈退学〉。退休指离开工作岗位，学生离开学校应说退学。"}, {"text": "我妹妹才工作两年，因为太累，今年就退休了。", "explanation": "这里应该用〈辞职〉。退休指到了年龄后离开工作岗位，年轻人因为太累而离开工作应说辞职。"}, {"text": "我每天五点退休。", "explanation": "这里应该用〈下班〉。退休指永久离开工作岗位，不能用于每天结束工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退休", "is_correct": true, "explanation": "正确：“退休”表示离开工作岗位，与后句“去海边生活”的退休后生活相衔接。"}, {"text": "生病", "is_correct": false, "explanation": "语义：没有人想早点生病去海边生活，与句子的意思不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与“去海边生活”的愿望没有关联，句子不通。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公到外地办事，与“想早点……去海边生活”的愿望不合。"}], "explanations": {"退休": "正确：“退休”表示离开工作岗位，与后句“去海边生活”的退休后生活相衔接。", "生病": "语义：没有人想早点生病去海边生活，与句子的意思不合。", "考试": "语义：“考试”与“去海边生活”的愿望没有关联，句子不通。", "出差": "语义：“出差”指因公到外地办事，与“想早点……去海边生活”的愿望不合。"}, "sentence_index": 6, "correct_answer": "退休"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下个月退休三天。", "explanation": "这里应该用〈休假〉。退休是永久离开工作岗位，不能用于短期休息。"}, {"text": "他明年要退休到北京工作。", "explanation": "这里应该用〈调到〉。退休后不再工作，不能说“退休到北京工作”。"}, {"text": "我明年要退休留学。", "explanation": "这里应该用〈出国〉。退休指离开工作岗位，不能用于学生去国外留学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叔叔明年就要把工作退休了。", "corrected_sentence": "我叔叔明年就要退休了。", "error_description": "错误在于“把”字句。“退休”是不及物动词，不能用“把”带宾语“工作”，应说“我叔叔明年就要退休了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她还没退休了，每天照常上班。", "corrected_sentence": "她还没退休，每天照常上班。", "error_description": "错误在于多加了“了”。“还没”表示尚未发生，与“了”不能同时用，应说“她还没退休，每天照常上班。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19f80253-4dfb-49c8-bec1-ad2a11530f92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
