INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13501, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学校里担任教学工作、向学生传授知识和技能的专业人员。", "primary_collocate": null, "pronunciation": "jiào shī", "ipa": "tɕjɑʊ˥˩ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "她是一位中学教师，每天都很忙。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教师在黑板上写了今天的作业。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的妈妈当了二十年教师。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校新来了两位英语教师。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教师讲课很清楚，大家都爱听。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想考大学，以后做一名教师。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，教师们都坐在前面。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学校有八十多名教师和一千个学生。", "target_word": "教师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好教师不但教知识，还教学生做人。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课后，学生围着教师问问题。", "target_word": "教师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教师们", "label": "复数"}, {"form": "教師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校里传授知识和技能的专业教学人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1945ebe5-6f1a-41cd-9a74-292bbe7ba560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教师", "is_correct": true, "explanation": "正确：“教师”指在中学教书的人，与“中学”和“每天都很忙”的语境相合。"}, {"text": "律师", "is_correct": false, "explanation": "语义：律师从事法律事务，不在中学教书，与“中学”的语境不合。"}, {"text": "飞行员", "is_correct": false, "explanation": "语义：飞行员驾驶飞机，不会在中学工作，句子说不通。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“中学司机”不是常见说法，与句中的学校语境不合。"}], "explanations": {"教师": "正确：“教师”指在中学教书的人，与“中学”和“每天都很忙”的语境相合。", "律师": "语义：律师从事法律事务，不在中学教书，与“中学”的语境不合。", "飞行员": "语义：飞行员驾驶飞机，不会在中学工作，句子说不通。", "司机": "搭配：“中学司机”不是常见说法，与句中的学校语境不合。"}, "sentence_index": 0, "correct_answer": "教师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位教师开车把乘客送到了机场。", "explanation": "这里应该用〈司机〉。开车送乘客的是司机，“教师”指在学校教书的人。"}, {"text": "新来的教师给孩子们看病。", "explanation": "这里应该用〈医生〉。看病的是医生，教师不做这件事。"}, {"text": "这位教师在饭店后厨炒了好几个菜。", "explanation": "这里应该用〈厨师〉。在后厨炒菜的是厨师，“教师”指在学校教书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教师们", "is_correct": true, "explanation": "正确：“教师们”是“教师”的复数形式，指开会的老师，可以坐在前面。"}, {"text": "小鸟们", "is_correct": false, "explanation": "语义：小鸟不参加会议，开会时不会“坐在前面”。"}, {"text": "桌椅们", "is_correct": false, "explanation": "语义：桌椅是物品，不能“坐”，也不能参加开会。"}, {"text": "石头们", "is_correct": false, "explanation": "配价：“坐”需要有生命的主语，石头不能坐在前面。"}], "explanations": {"教师们": "正确：“教师们”是“教师”的复数形式，指开会的老师，可以坐在前面。", "小鸟们": "语义：小鸟不参加会议，开会时不会“坐在前面”。", "桌椅们": "语义：桌椅是物品，不能“坐”，也不能参加开会。", "石头们": "配价：“坐”需要有生命的主语，石头不能坐在前面。"}, "sentence_index": 6, "correct_answer": "教师们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教师在法庭上为当事人辩护。", "explanation": "这里应该用〈律师〉。在法庭上为当事人辩护的是律师，“教师”指在学校教书的人。"}, {"text": "教师每天帮病人量体温。", "explanation": "这里应该用〈护士〉。量体温、照顾病人的是护士，教师不做这些工作。"}, {"text": "这位教师每个月负责给公司算账。", "explanation": "这里应该用〈会计〉。给公司算账的是会计，“教师”指在学校教书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅是一只大学教师。", "corrected_sentence": "我舅舅是一位大学教师。", "error_description": "量词错误：指人的“教师”应该用“位”或“名”，写成“一只”是错的，“只”用于动物等。正确说法是“一位大学教师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校请了三位教师们来讲课。", "corrected_sentence": "学校请了三位教师来讲课。", "error_description": "“们”的用法错误：数词后面不能加“们”，“三位教师”不能再说“三位教师们”。正确说法是去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
