INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13502, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指村庄的入口处或村子的边界位置。", "primary_collocate": null, "pronunciation": "cūn kǒu", "ipa": "tsʰwən˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "村口", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "村口有一棵很大的老树。", "target_word": "村口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在村口等你，别走远了。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶每天坐在村口看着来往的人。", "target_word": "村口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口新开了一家小商店。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车停在村口，没有开进村里。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在村口的大树下玩。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从村口走到我家要十分钟。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村口的路很窄，大车进不去。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时，村口挂满了红灯笼。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "村庄的入口处或边界位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1945ebe5-6f1a-41cd-9a74-292bbe7ba560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村口", "is_correct": true, "explanation": "正确：“村口荒坡”指村子入口附近的山坡，与“栽树”“植树造林”的语境相合。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内，不是荒坡，句子说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内的做饭地方，不可能在荒坡上。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁荒坡”不成搭配，荒坡指野外山坡。"}], "explanations": {"村口": "正确：“村口荒坡”指村子入口附近的山坡，与“栽树”“植树造林”的语境相合。", "教室": "语义：教室是室内，不是荒坡，句子说不通。", "厨房": "语义：厨房是室内的做饭地方，不可能在荒坡上。", "地铁": "搭配：“地铁荒坡”不成搭配，荒坡指野外山坡。"}, "sentence_index": 0, "correct_answer": "村口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大楼的村口很宽。", "explanation": "这里应该用〈入口〉。大楼、商场的出入处叫入口，“村口”只指村子的入口。"}, {"text": "这条路穿过大山的村口。", "explanation": "这里应该用〈山口〉。两山之间的通道叫山口，“村口”指村子的入口。"}, {"text": "地铁的村口在马路对面。", "explanation": "这里应该用〈出口〉。地铁的出入处叫出口，“村口”只指村子的入口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村口", "is_correct": true, "explanation": "正确：“村口的大树”指村子入口的大树，孩子们可以在那里玩。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是室内，没有“大树下”，句子说不通。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“书架的大树下”不成搭配，书架上没有大树。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是室内的设备，不能有“大树下”。"}], "explanations": {"村口": "正确：“村口的大树”指村子入口的大树，孩子们可以在那里玩。", "办公室": "语义：办公室是室内，没有“大树下”，句子说不通。", "书架": "搭配：“书架的大树下”不成搭配，书架上没有大树。", "电梯": "语义：电梯是室内的设备，不能有“大树下”。"}, "sentence_index": 6, "correct_answer": "村口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车站的村口排起了长队。", "explanation": "这里应该用〈进站口〉。火车站的出入处叫进站口，“村口”只指村子的入口。"}, {"text": "这座老院子的村口朝南开。", "explanation": "这里应该用〈院门〉。院子的出入口叫院门，“村口”指村子的入口。"}, {"text": "学校的村口每天七点开。", "explanation": "这里应该用〈大门〉。学校有大门，不说“村口”；“村口”只指村子的入口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在村口的站了很久。", "corrected_sentence": "他在村口站了很久。", "error_description": "多余的“的”：“在村口”后面直接接动词“站”，中间不能加“的”。正确说法是“他在村口站了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐车村口。", "corrected_sentence": "我们坐车到村口。", "error_description": "缺少介词：“坐车”后面要说“到村口”，漏掉“到”就不通。正确说法是“我们坐车到村口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
