INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13503, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指未经开垦、长满杂草的坡地。", "primary_collocate": null, "pronunciation": "huāng pō", "ipa": "xwɑŋ˥ pʰwo˥", "syllable_count": 2, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "荒坡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "荒坡上长满了高高的野草。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那片荒坡一直没有人种东西。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山羊在荒坡上吃草。", "target_word": "荒坡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们想把荒坡变成果园。", "target_word": "荒坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，荒坡上开满了野花。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村子后面有一块大荒坡。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去这里是荒坡，现在是一片绿地。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人开着车上了荒坡。", "target_word": "荒坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荒坡太陡，种不了庄稼。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "未经开垦、长满杂草的坡地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1945ebe5-6f1a-41cd-9a74-292bbe7ba560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荒坡", "is_correct": true, "explanation": "荒坡指未经开垦、长满杂草的坡地，正适合植树造林，与句意相符。"}, {"text": "柏油路", "is_correct": false, "explanation": "搭配：柏油路面不透土，在上面不能栽下树苗。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是水域，不能在水面上栽树。"}, {"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶上没有可供栽种的土壤，与“植树造林”的语境不符。"}], "explanations": {"荒坡": "荒坡指未经开垦、长满杂草的坡地，正适合植树造林，与句意相符。", "柏油路": "搭配：柏油路面不透土，在上面不能栽下树苗。", "水库": "语义：水库是水域，不能在水面上栽树。", "屋顶": "语义：屋顶上没有可供栽种的土壤，与“植树造林”的语境不符。"}, "sentence_index": 0, "correct_answer": "荒坡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片荒坡平坦得很，正好用来建停车场。", "explanation": "这里应该用〈荒地〉。荒坡指有坡度、未经开垦的地，平坦的地面不能说荒坡。"}, {"text": "这片荒坡上种满了玉米，今年收成很好。", "explanation": "这里应该用〈山坡〉。荒坡指没人开垦、不种庄稼的坡地，种满玉米就不能再叫荒坡。"}, {"text": "这座荒坡上种满了茶树，茶园修得整整齐齐。", "explanation": "这里应该用〈坡地〉或〈茶园〉。荒坡指未经开垦的坡地，已种上茶树、修成茶园的地方不能再说荒坡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒坡", "is_correct": true, "explanation": "荒坡是未经开垦的坡地，村子后面有一块大荒坡，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“块”不用于学校，学校应说“一所”，此处不合。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“块”一般不用于工厂，工厂应说“一座”，此处不合。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：村子后面不会有地铁站，与乡村的背景不符。"}], "explanations": {"荒坡": "荒坡是未经开垦的坡地，村子后面有一块大荒坡，符合句意。", "学校": "搭配：“块”不用于学校，学校应说“一所”，此处不合。", "工厂": "搭配：“块”一般不用于工厂，工厂应说“一座”，此处不合。", "地铁站": "语义：村子后面不会有地铁站，与乡村的背景不符。"}, "sentence_index": 6, "correct_answer": "荒坡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面荒坡上铺满了瓷砖，人们在上面跳舞。", "explanation": "这里应该用〈广场〉。铺满瓷砖供人活动的地面叫广场，荒坡指未经开垦、长满杂草的坡地。"}, {"text": "公园里的荒坡修剪得整整齐齐，游客可以在上面野餐。", "explanation": "这里应该用〈草坪〉。荒坡指未经开垦、长满杂草的坡地，修剪整齐的草地要说草坪。"}, {"text": "这块荒坡已经开垦成果园，果树排列得很整齐。", "explanation": "这里应该用〈果园〉。荒坡指未经开垦的坡地，已开垦并种满果树的地方不能再说荒坡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民在一只荒坡上种了一排松树。", "corrected_sentence": "村民在一块荒坡上种了一排松树。", "error_description": "错误：量词“只”用于动物或小件物品，荒坡是地面，应用“块”。正确：一块荒坡。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里那只荒坡今年种上了果树。", "corrected_sentence": "村里那块荒坡今年种上了果树。", "error_description": "错误：量词“只”用于动物或小件物品，荒坡是地面，应用“块”。正确：那块荒坡。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
