INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把植物的幼苗或种子埋入土中使其生长。", "primary_collocate": null, "pronunciation": "zāi xià", "ipa": "tsaɪ̯˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "栽下", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "春天，爷爷在院子里栽下了一棵苹果树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把小树栽下以后，马上浇了水。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年在山坡上栽下了二十棵松树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在花盆里栽下了三株花苗。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带着同学们在学校门口栽下一排柳树。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们在河边栽下了很多杨树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵桂花树是十年前奶奶亲手栽下的。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门前栽下了两棵梨树，现在已经开花了。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把这棵小树栽下以后，要记得每天浇水。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栽下了", "label": "体标"}, {"form": "栽下过", "label": "体标"}], "register": "中性", "sense_fingerprint": "栽下:把幼苗埋进土里使其生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1945ebe5-6f1a-41cd-9a74-292bbe7ba560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13504, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栽下", "is_correct": true, "explanation": "栽下（zāi xià）：把幼苗埋进土里使其生长，意思是种下。"}, {"text": "摘下", "is_correct": false, "explanation": "摘下（zhāi xià）与 zāi 声母不同（zh 与 z），意思是摘取、取下。"}, {"text": "砸下", "is_correct": false, "explanation": "砸下（zá xià）与 zāi 韵母和声调都不同，听感区分较明显，仅为边缘干扰项；意思是用力打下。"}, {"text": "在下", "is_correct": false, "explanation": "在下（zài xià）与 zāi 声调不同（第四声），是谦称“我”。"}], "explanations": {"栽下": "栽下（zāi xià）：把幼苗埋进土里使其生长，意思是种下。", "摘下": "摘下（zhāi xià）与 zāi 声母不同（zh 与 z），意思是摘取、取下。", "砸下": "砸下（zá xià）与 zāi 韵母和声调都不同，听感区分较明显，仅为边缘干扰项；意思是用力打下。", "在下": "在下（zài xià）与 zāi 声调不同（第四声），是谦称“我”。"}, "sentence_index": null, "correct_answer": "栽下"}, "level_3": {"options": [{"text": "栽下", "is_correct": true, "explanation": "栽下指把幼苗埋进土里，与“植树造林”的语境相符。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，杨树苗不能收割。"}, {"text": "采摘", "is_correct": false, "explanation": "搭配：“采摘”用于果实或花，不能用于杨树苗。"}, {"text": "砍下", "is_correct": false, "explanation": "语义：砍下是砍伐，与“植树造林”的行动正相反。"}], "explanations": {"栽下": "栽下指把幼苗埋进土里，与“植树造林”的语境相符。", "收割": "搭配：“收割”用于庄稼，杨树苗不能收割。", "采摘": "搭配：“采摘”用于果实或花，不能用于杨树苗。", "砍下": "语义：砍下是砍伐，与“植树造林”的行动正相反。"}, "sentence_index": 0, "correct_answer": "栽下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在树下栽下了一箱金子。", "explanation": "这里应该用〈埋下〉。栽下只用于把幼苗或种子埋入土中，埋藏金子这类物品要用“埋下”。"}, {"text": "他在墙上栽下了一根钉子。", "explanation": "这里应该用〈钉〉。栽下只用于植物的幼苗或种子，把钉子固定在墙上要用“钉”。"}, {"text": "妈妈在门上栽下了一把锁。", "explanation": "这里应该用〈装〉。栽下只用于植物，安装门锁要用“装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栽下", "is_correct": true, "explanation": "栽下指把杨树栽进土里，村民在河边栽树，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不能是树，与句意不合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于杨树。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是杨树，不能说吃杨树。"}], "explanations": {"栽下": "栽下指把杨树栽进土里，村民在河边栽树，符合句意。", "唱": "语义：“唱”的对象不能是树，与句意不合。", "煮": "搭配：“煮”的对象是食物，不能用于杨树。", "吃": "搭配：“吃”的对象不能是杨树，不能说吃杨树。"}, "sentence_index": 6, "correct_answer": "栽下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里栽下了一锅饭。", "explanation": "这里应该用〈煮〉。栽下只用于种植植物，做饭要用“煮”。"}, {"text": "他在河边栽下了一块石头。", "explanation": "这里应该用〈放〉。栽下只用于种植植物，石头要用“放”。"}, {"text": "学生们在教室里栽下了一本书。", "explanation": "这里应该用〈放〉。栽下只用于种植植物，书本要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在地里栽下了一只果树。", "corrected_sentence": "农民在地里栽下了一棵果树。", "error_description": "错误：量词“只”用于动物，果树应用“棵”。正确：一棵果树。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "园丁在路边栽下着一排松树。", "corrected_sentence": "园丁在路边栽下了一排松树。", "error_description": "错误：“栽下”后应接完成态“了”，说“栽下了”，不能接“着”。正确：栽下了一排松树。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f18c0613-e2c3-415c-ad8c-88cbc79348d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
