INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示超出、越过某个数量或标准。", "primary_collocate": null, "pronunciation": "chāo guò", "ipa": "tʂʰɑʊ˥ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "这辆车的速度超过了规定。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温超过了三十五度。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩超过了老师的要求。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，她的分数超过了及格线。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李的重量不能超过二十公斤。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机超过了限速，警察就拦住了他。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的花费超过了原来的计划。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的雨量超过了往年的平均水平。", "target_word": "超过", "complexity_tier": "T3", "furigana": "jīn nián de yǔ liàng chāo guò le wǎng nián de píng jūn shuǐ píng", "sentence_source": "generated"}, {"text": "水位超过了安全线，大家都离开了河边。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的顾客已经超过了店里能容纳的人数。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超过了", "label": "体标"}, {"form": "超過", "label": "繁体"}], "register": "中性", "sense_fingerprint": "超出、越过某个数量或标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 雨量 (Zipf 3.64), 往年 (Zipf 3.66), 平均水平 (Zipf 3.04)']::text[], '44bc9423-a209-484e-962c-15154973652d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超过", "is_correct": true, "explanation": "正确：“超过”表示超出规定，与“速度”和“规定”相合。"}, {"text": "遵守", "is_correct": false, "explanation": "搭配：“遵守”的主语应是人，速度不能遵守规定。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”指变少，不能用于规定，句子语义不通。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”不能与“规定”搭配，速度也不能打开规定。"}], "explanations": {"超过": "正确：“超过”表示超出规定，与“速度”和“规定”相合。", "遵守": "搭配：“遵守”的主语应是人，速度不能遵守规定。", "减少": "语义：“减少”指变少，不能用于规定，句子语义不通。", "打开": "搭配：“打开”不能与“规定”搭配，速度也不能打开规定。"}, "sentence_index": 0, "correct_answer": "超过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们超过了那座桥。", "explanation": "这里应该用〈经过〉。经过指从某处通过；超过指数量或标准超出，不能用于桥。"}, {"text": "我这次超过了英语考试。", "explanation": "这里应该用〈通过〉。考试合格说“通过”；超过用于数量或标准的超出，不用于考试。"}, {"text": "我们在海边超过了一个愉快的假期。", "explanation": "这里应该用〈度过〉。度过指一段时间在某处过完；超过表示超出数量或标准，不能用于时间段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f789621b-e191-4c05-8c07-16e46d863e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超过", "is_correct": true, "explanation": "正确：“超过”表示花费超出了原定计划，与句意相合。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”的主语须是有权决定的人或机构，花费不能批准计划。"}, {"text": "节省", "is_correct": false, "explanation": "搭配：“节省”接的是钱、时间等可节约的东西，不接“计划”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”要求有意志的主语，花费不能拒绝计划。"}], "explanations": {"超过": "正确：“超过”表示花费超出了原定计划，与句意相合。", "批准": "语义：“批准”的主语须是有权决定的人或机构，花费不能批准计划。", "节省": "搭配：“节省”接的是钱、时间等可节约的东西，不接“计划”。", "拒绝": "语义：“拒绝”要求有意志的主语，花费不能拒绝计划。"}, "sentence_index": 6, "correct_answer": "超过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去银行超过了手续。", "explanation": "这里应该用〈办理〉。办理手续是事务性动作；超过用于数量或标准的超出，不用于手续。"}, {"text": "他超过了比赛。", "explanation": "这里应该用〈参加〉。参加比赛指参与其中；超过不能表示参与比赛。"}, {"text": "他超过了一个秘密。", "explanation": "这里应该用〈发现〉。发现是看到或察觉到隐藏的事物；超过表示超出数量或标准，不能用于秘密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f789621b-e191-4c05-8c07-16e46d863e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车的油耗比超过了说明书上的数字。", "corrected_sentence": "这辆车的油耗超过了说明书上的数字。", "error_description": "多余成分：“超过”本身已表示超出，前面不能再加“比”。应说“这辆车的油耗超过了说明书上的数字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f789621b-e191-4c05-8c07-16e46d863e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路的车流量已经超过过了规定的数量。", "corrected_sentence": "这条路的车流量已经超过了规定的数量。", "error_description": "体标重复：“超过”后已用“了”，又加“过”，属于体标错误，应只说“超过了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f789621b-e191-4c05-8c07-16e46d863e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
