INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生长着树木的土地，通常指森林或树木覆盖的区域。", "primary_collocate": null, "pronunciation": "lín dì", "ipa": "lin˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "林地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片林地里有很多松树。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村子后面有一大片林地。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府决定保护这里的林地。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "林地里的空气特别新鲜。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块林地已经有五十年的历史了。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在林地边上搭了一个帐篷。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人把林地改成了农田，鸟都少了。", "target_word": "林地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，林地里开满了野花。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天走进林地，脚下全是落叶。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片林地", "label": "量词"}, {"form": "一块林地", "label": "量词"}, {"form": "林地面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "林地|长着树木的土地，森林或树木覆盖的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确答案：生长着树木的土地。"}, {"text": "领地", "is_correct": false, "explanation": "lǐng（第三声）与 lín（第二声）韵母与声调都不同，意思是领土、势力范围。"}, {"text": "林立", "is_correct": false, "explanation": "lì 与 dì 声母不同（l / d），意思是像树林一样密集地竖立，如高楼林立。"}, {"text": "灵地", "is_correct": false, "explanation": "声调相同，韵母不同（in / ing），灵地意思是风水或灵验的地方，如圣地。"}, {"text": "心地", "is_correct": false, "explanation": "xīn 与 lín 声母和声调都不同，dì 相同，意思是内心、心肠。"}], "explanations": {"林地": "正确答案：生长着树木的土地。", "领地": "lǐng（第三声）与 lín（第二声）韵母与声调都不同，意思是领土、势力范围。", "林立": "lì 与 dì 声母不同（l / d），意思是像树林一样密集地竖立，如高楼林立。", "灵地": "声调相同，韵母不同（in / ing），灵地意思是风水或灵验的地方，如圣地。", "心地": "xīn 与 lín 声母和声调都不同，dì 相同，意思是内心、心肠。"}, "sentence_index": null, "correct_answer": "林地"}, "level_3": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确：“每一片消失的林地”指成片的林地，与土壤退化、生物多样性下跌的生态语境相符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是生长树木的土地，放在这一语境中与土壤退化、生物多样性无关联。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“每一片”不能修饰城市，应说“每一座城市”；且城市消失不会直接关联土壤退化。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆与生态退化没有关系，“消失的图书馆”无法关联土壤退化等生态问题。"}], "explanations": {"林地": "正确：“每一片消失的林地”指成片的林地，与土壤退化、生物多样性下跌的生态语境相符。", "工厂": "语义：工厂不是生长树木的土地，放在这一语境中与土壤退化、生物多样性无关联。", "城市": "搭配：“每一片”不能修饰城市，应说“每一座城市”；且城市消失不会直接关联土壤退化。", "图书馆": "语义：图书馆与生态退化没有关系，“消失的图书馆”无法关联土壤退化等生态问题。"}, "sentence_index": 0, "correct_answer": "林地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山脚下买了一条林地。", "explanation": "这里应该用〈片〉或〈块〉。林地是成片的土地，“条”用于细长的东西，不能修饰林地。"}, {"text": "我家后面有一只林地，很安静。", "explanation": "这里应该用〈片〉。“只”用于动物等，不能用来计量土地。"}, {"text": "村子后面有一颗林地，大家都很喜欢。", "explanation": "这里应该用〈片〉。“颗”用于颗粒、星星等小而圆的东西，林地是大片土地，不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确：林边的空地适合搭帐篷，“在林地边上搭一个帐篷”语义合理。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内场所，不会在教室边上搭帐篷，句中语境是户外。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是室内家具，不能在它边上搭帐篷，与户外搭帐篷的语境不符。"}, {"text": "办公室", "is_correct": false, "explanation": "搭配：搭帐篷的地点应为空地，“办公室”不能与“边上搭一个帐篷”搭配。"}], "explanations": {"林地": "正确：林边的空地适合搭帐篷，“在林地边上搭一个帐篷”语义合理。", "教室": "语义：教室是室内场所，不会在教室边上搭帐篷，句中语境是户外。", "书架": "语义：书架是室内家具，不能在它边上搭帐篷，与户外搭帐篷的语境不符。", "办公室": "搭配：搭帐篷的地点应为空地，“办公室”不能与“边上搭一个帐篷”搭配。"}, "sentence_index": 6, "correct_answer": "林地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村口有一棵林地，夏天特别凉快。", "explanation": "这里应该用〈片〉。“棵”用于单株的树，林地是一大片土地，不能用“棵”计量。"}, {"text": "他家后院有一扇林地。", "explanation": "这里应该用〈片〉。“扇”用于门窗等，林地不能用“扇”计量。"}, {"text": "院子旁边有一盏林地，孩子们常来玩。", "explanation": "这里应该用〈片〉。“盏”用于灯，林地是大片土地，不能用“盏”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上有一条林地。", "corrected_sentence": "山坡上有一片林地。", "error_description": "量词错误：“林地”是成片的土地，应说“一片林地”，不能说“一条林地”。“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们喜欢林地里采蘑菇。", "corrected_sentence": "孩子们喜欢在林地里采蘑菇。", "error_description": "介词缺失：表示地点的状语“林地里”前应加介词“在”，说“在林地里采蘑菇”，不能省去“在”直接说“林地里采蘑菇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "土壤退化是指土壤质量下降，导致其生产能力降低或生态功能减弱的过程。", "primary_collocate": null, "pronunciation": "tǔ rǎng tuì huà", "ipa": "tʰu˨˩˦ ɻɑŋ˨˩˦ tʰweɪ˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "土壤退化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "土壤退化会让粮食减产。", "target_word": "土壤退化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过度使用化肥会造成土壤退化。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家正在研究土壤退化的原因。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的土壤退化越来越严重。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种树可以减缓土壤退化。", "target_word": "土壤退化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "土壤退化使农民的收入减少了。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了防止土壤退化，农民开始轮流种不同的作物。", "target_word": "土壤退化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱和大风也会加重土壤退化。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一篇关于土壤退化的文章。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤退化问题", "label": "复合"}], "register": "书面", "sense_fingerprint": "土壤退化|土壤质量下降、生产能力和生态功能减弱的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土壤退化", "is_correct": true, "explanation": "正确：“关联着土壤退化”与“水源枯竭”“生物多样性下跌”同属生态退化问题，语境相符。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日与土壤、水源和生物多样性无关，不能与“水源枯竭”并列为生态退化的后果。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言不属于生态要素，无法与“水源枯竭”“生物多样性”并列为生态退化的后果。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：“断崖式下跌”说数量或价值，“演唱会”本身不能下跌，也与生态语境不符。"}], "explanations": {"土壤退化": "正确：“关联着土壤退化”与“水源枯竭”“生物多样性下跌”同属生态退化问题，语境相符。", "节日": "语义：节日与土壤、水源和生物多样性无关，不能与“水源枯竭”并列为生态退化的后果。", "方言": "语义：方言不属于生态要素，无法与“水源枯竭”“生物多样性”并列为生态退化的后果。", "演唱会": "搭配：“断崖式下跌”说数量或价值，“演唱会”本身不能下跌，也与生态语境不符。"}, "sentence_index": 0, "correct_answer": "土壤退化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地经过多年的土壤退化，庄稼长得特别好。", "explanation": "这里应该用〈土壤改良〉。“土壤退化”指土壤质量下降，经过它庄稼长不好，不能说长得特别好。"}, {"text": "这口井的土壤退化了，村民只好去山下挑水。", "explanation": "这里应该用〈水源枯竭〉。井里没有水，说的是水源，“土壤退化”只用于土壤质量下降的情况。"}, {"text": "这条河的土壤退化很严重，鱼都死光了。", "explanation": "这里应该用〈水污染〉。河水受污染是水的问题，“土壤退化”只说土壤质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土壤退化", "is_correct": true, "explanation": "正确：“土壤退化”作主语，导致农民收入减少，与句意相符。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌与农民收入减少没有因果关系，句子不成立。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，与农民收入减少没有因果关系，句子不成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与农民收入减少没有因果关系，句子不成立。"}], "explanations": {"土壤退化": "正确：“土壤退化”作主语，导致农民收入减少，与句意相符。", "诗歌": "语义：诗歌与农民收入减少没有因果关系，句子不成立。", "童话": "语义：童话是虚构的故事，与农民收入减少没有因果关系，句子不成立。", "钢琴": "语义：钢琴与农民收入减少没有因果关系，句子不成立。"}, "sentence_index": 6, "correct_answer": "土壤退化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民正在努力打开土壤退化的问题。", "explanation": "这里应该用〈解决〉或〈治理〉。“打开”用于门、窗、局面等，不能用来处理问题。"}, {"text": "他写了一篇关于这座土壤退化的文章。", "explanation": "这里应该用〈种〉。“座”用于山、桥等大型固定的东西，不用于土壤退化这类现象。"}, {"text": "这块地的土壤退化很好，庄稼长得很壮。", "explanation": "这里应该用〈土壤肥力〉。“土壤退化”指土壤变差，不能用“很好”来说它的好坏；说土壤好应用〈土壤肥力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一片很常见的土壤退化。", "corrected_sentence": "这是一种很常见的土壤退化。", "error_description": "量词错误：“土壤退化”指一种过程，应说“一种”，不能说“一片”。“片”用于面积。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民每年都要面对一座新的土壤退化。", "corrected_sentence": "农民每年都要面对一种新的土壤退化。", "error_description": "量词错误：“土壤退化”指一种过程，应说“一种”，不能说“一座”。“座”用于山、楼等大型固定的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水源指水流发源的地方，或水供应的来源。", "primary_collocate": null, "pronunciation": "shuǐ yuán", "ipa": "ʂweɪ˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "水源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河是城市的主要水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里有一处干净的水源。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们要保护好村子的水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天很热，附近的水源变少了。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们沿着小河找到了水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这口井是全村的水源。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂把垃圾倒进河里，会影响水源。", "target_word": "水源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里找不到水源，人很难活下去。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的水源在高山上。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "水源地", "label": "复合词"}], "register": "中性", "sense_fingerprint": "河流的发源地，或供水的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "与“枯竭”搭配，指供水的来源，前文说“土壤退化、水源枯竭”。"}, {"text": "水质", "is_correct": false, "explanation": "搭配：“枯竭”用于水源或资源，不说水质枯竭，水质是变差。"}, {"text": "水灾", "is_correct": false, "explanation": "语义：水灾指洪涝灾害，是水过多而非供水减少，不能说“水灾枯竭”。"}, {"text": "水位", "is_correct": false, "explanation": "搭配：水位是下降，不说枯竭，与“枯竭”搭配不当。"}], "explanations": {"水源": "与“枯竭”搭配，指供水的来源，前文说“土壤退化、水源枯竭”。", "水质": "搭配：“枯竭”用于水源或资源，不说水质枯竭，水质是变差。", "水灾": "语义：水灾指洪涝灾害，是水过多而非供水减少，不能说“水灾枯竭”。", "水位": "搭配：水位是下降，不说枯竭，与“枯竭”搭配不当。"}, "sentence_index": 0, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要疏通村子的水源。", "explanation": "这里应该用〈河道〉。疏通说的是河道、水沟，水源是水的来源，不能疏通。"}, {"text": "山脚下有一条水源，村民每天都去取水。", "explanation": "这里应该用〈处〉。水源是地点，计量地点用〈处〉；用来计量河流、道路的量词，不能用在水源上。"}, {"text": "他们把水源装进瓶子里带回家。", "explanation": "这里应该用〈饮用水〉。水源指地方或来源，不能装进瓶子；装进瓶子带回家的是饮用水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "与“全村的”搭配，指全村依赖的供水来源，符合句意。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是供水的来源，“这口井是全村的水果”不成立。"}, {"text": "水利", "is_correct": false, "explanation": "语义：“水利”指水利工程，不指供水来源，句中说的是一口井。"}, {"text": "水管", "is_correct": false, "explanation": "语义：水管是输水的管道，不是水的来源，“这口井是全村的水管”不成立。"}], "explanations": {"水源": "与“全村的”搭配，指全村依赖的供水来源，符合句意。", "水果": "语义：水果不是供水的来源，“这口井是全村的水果”不成立。", "水利": "语义：“水利”指水利工程，不指供水来源，句中说的是一口井。", "水管": "语义：水管是输水的管道，不是水的来源，“这口井是全村的水管”不成立。"}, "sentence_index": 6, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水源在大海里。", "explanation": "这里应该用〈河口〉。河口是河流入海的地方，水源是水开始流出的地方。"}, {"text": "这条河的水源很重，一个人搬不动。", "explanation": "这里应该用〈远〉或〈高〉来说水源的位置。水源是地点，不讲重量；〈重量〉只用于物体。"}, {"text": "这条河的水源跑得很快，比河水还快。", "explanation": "这里应该用〈流速〉。水源是地方，没有快慢；说水流的快慢要用〈流速〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子后面有一条水源，水很清。", "corrected_sentence": "村子后面有一处水源，水很清。", "error_description": "量词错误：“水源”作地点，量词应用“处”，说“一处水源”；“条”多用于河流、道路，不用于水源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那口老井是整个村子水源。", "corrected_sentence": "那口老井是整个村子的水源。", "error_description": "省略错误：定语“整个村子”与“水源”之间要加“的”，说“整个村子的水源”；省略后“是整个村子水源”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容水源断流或资源用尽。", "primary_collocate": null, "pronunciation": "kū jié", "ipa": "kʰu˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "枯竭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的水已经枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱太久，村里的井都枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油资源总有一天会枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多矿山的资源已经枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水枯竭后，鱼都死了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下水用得太多，水源会枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的煤炭快要枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了很多年，灵感却没有枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林被砍光后，小溪也枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枯竭了", "label": "体标"}, {"form": "枯竭过", "label": "体标"}], "register": "中性", "sense_fingerprint": "水源断流或资源用尽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd4cdd9-db04-4902-a117-8e52e4bb86e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "枯竭", "is_correct": true, "explanation": "正确：“枯竭”指水源断流，与前文的“土壤退化”“断崖式下跌”构成负面并列。"}, {"text": "充沛", "is_correct": false, "explanation": "语义：“水源充沛”与前文的“土壤退化”和“断崖式下跌”的负面趋势相反，句意矛盾。"}, {"text": "回升", "is_correct": false, "explanation": "语义：“回升”是好转，无法与“土壤退化”“断崖式下跌”并列成同一类负面现象。"}, {"text": "增殖", "is_correct": false, "explanation": "搭配：“增殖”多用于生物或细胞，不说“水源增殖”。"}], "explanations": {"枯竭": "正确：“枯竭”指水源断流，与前文的“土壤退化”“断崖式下跌”构成负面并列。", "充沛": "语义：“水源充沛”与前文的“土壤退化”和“断崖式下跌”的负面趋势相反，句意矛盾。", "回升": "语义：“回升”是好转，无法与“土壤退化”“断崖式下跌”并列成同一类负面现象。", "增殖": "搭配：“增殖”多用于生物或细胞，不说“水源增殖”。"}, "sentence_index": 0, "correct_answer": "枯竭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款饮料已经枯竭了。", "explanation": "这里应该用〈售罄〉。枯竭指水源或自然资源用尽，饮料卖完应说售罄。"}, {"text": "这种动物已经枯竭了。", "explanation": "这里应该用〈灭绝〉。枯竭多用于水源、矿产等资源，物种消失应说灭绝。"}, {"text": "这盆花因为缺水已经枯竭了。", "explanation": "这里应该用〈枯萎〉。枯竭指水源或资源用尽，植物失水凋谢应说枯萎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "枯竭", "is_correct": true, "explanation": "正确：“用得太多”的结果是水源“枯竭”，与句中的因果关系一致。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“用得太多”之后水源“增加”，因果关系说不通。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“用得太多”之后水源不会“恢复”，恢复需要先有损失且停止消耗，句中没有这样的条件。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”多用于果实、精神等，不说“水源饱满”。"}], "explanations": {"枯竭": "正确：“用得太多”的结果是水源“枯竭”，与句中的因果关系一致。", "增加": "语义：“用得太多”之后水源“增加”，因果关系说不通。", "恢复": "语义：“用得太多”之后水源不会“恢复”，恢复需要先有损失且停止消耗，句中没有这样的条件。", "饱满": "搭配：“饱满”多用于果实、精神等，不说“水源饱满”。"}, "sentence_index": 6, "correct_answer": "枯竭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这堆火已经枯竭了。", "explanation": "这里应该用〈熄灭〉。枯竭指水源或资源用尽，火焰熄灭应说熄灭。"}, {"text": "这块冰已经枯竭了。", "explanation": "这里应该用〈融化〉。枯竭不用于固体受热变成液体，冰化开应说融化。"}, {"text": "这片雾已经枯竭了。", "explanation": "这里应该用〈散去〉。枯竭指水源或资源用尽，雾气消散应说散去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湖的水已经被枯竭了。", "corrected_sentence": "这片湖的水已经枯竭了。", "error_description": "错误在于多加了“被”。“枯竭”是不及物动词，不能构成被动句，应说“湖水已经枯竭了”，不说“被枯竭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井的水慢慢枯竭着了。", "corrected_sentence": "这口井的水慢慢枯竭了。", "error_description": "体标错误：“着”和“了”不能同时用在“枯竭”上，表示动作完成只用“了”，应说“慢慢枯竭了”，不说“枯竭着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陡峭的山崖；也比喻急剧下降或突然中断，如“断崖式下跌”。", "primary_collocate": null, "pronunciation": "duàn yá", "ipa": "tuan˥˩ ja˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "断崖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "前面有一处断崖，我们不能再走了。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路的尽头是一道很高的断崖。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在断崖边，不敢往下看。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价像断崖一样往下掉。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车差点开下断崖。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "断崖下面是一条深深的河。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，那边的断崖很危险。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，断崖上的石头掉下来了。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的断崖上有很多鸟窝。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处断崖", "label": "量词"}, {"form": "断崖式", "label": "复合"}, {"form": "斷崖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "陡峭山崖，比喻急剧下降", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd4cdd9-db04-4902-a117-8e52e4bb86e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断崖", "is_correct": true, "explanation": "正确：“断崖式下跌”指急剧下降，与句中的负面趋势相合。"}, {"text": "缓坡", "is_correct": false, "explanation": "语义：“缓坡”说坡度平缓，与“急剧下跌”的语义相反。"}, {"text": "平原", "is_correct": false, "explanation": "语义：“平原”说地势平坦，不能用来形容急剧下降。"}, {"text": "草坪", "is_correct": false, "explanation": "搭配：“草坪式”没有“下跌”的常用说法，应说“断崖式下跌”。"}], "explanations": {"断崖": "正确：“断崖式下跌”指急剧下降，与句中的负面趋势相合。", "缓坡": "语义：“缓坡”说坡度平缓，与“急剧下跌”的语义相反。", "平原": "语义：“平原”说地势平坦，不能用来形容急剧下降。", "草坪": "搭配：“草坪式”没有“下跌”的常用说法，应说“断崖式下跌”。"}, "sentence_index": 0, "correct_answer": "断崖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在断崖勒马，及时改正了错误。", "explanation": "这里应该用〈悬崖〉。“悬崖勒马”是固定说法，“断崖”不能用于此固定搭配。"}, {"text": "他在书店里买了一道断崖。", "explanation": "这里应该用〈书〉。断崖是山崖，不能买；买的东西要说书。"}, {"text": "妈妈把断崖放进了冰箱。", "explanation": "这里应该用〈牛奶〉。断崖是地形，不能放进冰箱；要放进冰箱的食物说牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断崖", "is_correct": true, "explanation": "正确：“断崖下面是一条深深的河”，断崖位于河的上方，空间关系成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会位于一条深河之上，句意不通。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是室内器具，不能位于一条深河的上方。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“树叶下面”与“河”不构成可以这样描述的空间关系。"}], "explanations": {"断崖": "正确：“断崖下面是一条深深的河”，断崖位于河的上方，空间关系成立。", "书包": "语义：书包不会位于一条深河之上，句意不通。", "台灯": "语义：台灯是室内器具，不能位于一条深河的上方。", "树叶": "搭配：“树叶下面”与“河”不构成可以这样描述的空间关系。"}, "sentence_index": 6, "correct_answer": "断崖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水在断崖里奔腾，声音震耳。", "explanation": "这里应该用〈峡谷〉。断崖指陡峭的崖壁本身，不是能容纳河水奔腾的空间；河水奔腾的谷地要说峡谷。"}, {"text": "这场竞争让他陷入断崖，难以翻身。", "explanation": "这里应该用〈深渊〉。断崖是陡峭的山崖，比喻困境时不能说“陷入断崖”，要说“陷入深渊”。"}, {"text": "断崖从山顶倾泻而下，像一道白练。", "explanation": "这里应该用〈瀑布〉。断崖是静止的山崖，不会倾泻；水从高处流下形成白练要说瀑布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前方那只断崖又高又陡。", "corrected_sentence": "前方那道断崖又高又陡。", "error_description": "量词错误：断崖是一道山崖，量词应用“道”，说“那道断崖”；“只”多用于动物或成对物品中的一个，不用于断崖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们断崖边停下来休息。", "corrected_sentence": "我们在断崖边停下来休息。", "error_description": "“在”漏掉：表示处所要用“在”引出，应说“在断崖边停下”，不能直接说“断崖边停下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上涨", "is_correct": true, "explanation": "正确。“上涨”与“下跌”相反，指价格从低往高变动。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原状，不表示与价格下跌方向相反的变动。"}, {"text": "出现", "is_correct": false, "explanation": "“出现”指新事物显现，与价格下跌没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与价格变动无关。"}], "correct_answer": "上涨", "explanations": {"上涨": "正确。“上涨”与“下跌”相反，指价格从低往高变动。", "保持": "“保持”指维持原状，不表示与价格下跌方向相反的变动。", "出现": "“出现”指新事物显现，与价格下跌没有反义关系。", "参加": "“参加”指加入某项活动，与价格变动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上涨", "is_correct": true, "explanation": "正确。“上涨”与“下跌”相反，指价格从低往高变动。"}, {"text": "继续", "is_correct": false, "explanation": "“继续”指接着进行下去，与价格下跌没有反义关系。"}, {"text": "诞生", "is_correct": false, "explanation": "“诞生”指事物开始出现，与价格下跌没有反义关系。"}, {"text": "入睡", "is_correct": false, "explanation": "“入睡”指进入睡眠状态，与价格变动无关。"}], "correct_answer": "上涨", "explanations": {"上涨": "正确。“上涨”与“下跌”相反，指价格从低往高变动。", "继续": "“继续”指接着进行下去，与价格下跌没有反义关系。", "诞生": "“诞生”指事物开始出现，与价格下跌没有反义关系。", "入睡": "“入睡”指进入睡眠状态，与价格变动无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指价格、水平等从高处向低处变动。", "primary_collocate": null, "pronunciation": "xià diē", "ipa": "ɕja˥˩ tje˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "下跌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天苹果的价格下跌了。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "股票市场连续三天下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变冷，菜价突然下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价下跌，很多人想买房。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月牛肉的价格明显下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年手机的销量大幅下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的股价下跌了百分之十。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油价下跌过一次，后来又涨上去了。", "target_word": "下跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气好，水果的价格一直在下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下跌了", "label": "体标"}, {"form": "下跌过", "label": "体标"}], "register": "中性", "sense_fingerprint": "下跌|价格、水平等从高处向低处变动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下跌", "is_correct": true, "explanation": "正确。“断崖式下跌”指急剧下降，与前文“消失”“退化”“枯竭”的语境一致。"}, {"text": "上升", "is_correct": false, "explanation": "语义：“上升”是向上移动，与前文“消失”“退化”“枯竭”所描述的减少趋势相反。"}, {"text": "攀升", "is_correct": false, "explanation": "语义：“攀升”指向高处攀登，与“断崖”的向下意象和前文的损失语境相反。"}, {"text": "高涨", "is_correct": false, "explanation": "搭配：“高涨”多用于情绪、热情或物价，不用于生物多样性等数量的急剧变化。"}], "explanations": {"下跌": "正确。“断崖式下跌”指急剧下降，与前文“消失”“退化”“枯竭”的语境一致。", "上升": "语义：“上升”是向上移动，与前文“消失”“退化”“枯竭”所描述的减少趋势相反。", "攀升": "语义：“攀升”指向高处攀登，与“断崖”的向下意象和前文的损失语境相反。", "高涨": "搭配：“高涨”多用于情绪、热情或物价，不用于生物多样性等数量的急剧变化。"}, "sentence_index": 0, "correct_answer": "下跌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重下跌了三公斤。", "explanation": "这里应该用〈下降〉。下跌多用于价格、股价，体重这类数量的减少要用“下降”。"}, {"text": "这块地的面积下跌了一半。", "explanation": "这里应该用〈缩小〉。下跌用于价格、股价、水平等数值，土地面积的减少要说“缩小”。"}, {"text": "这次改革后，农民的负担下跌了很多。", "explanation": "这里应该用〈减轻〉。下跌用于价格、股价、水平等数值的降低，负担的减轻要用“减轻”，不能说下跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下跌", "is_correct": true, "explanation": "正确。“大幅下跌”表示销量急剧减少，符合句中的语境。"}, {"text": "断裂", "is_correct": false, "explanation": "搭配：“断裂”用于绳索、骨骼等实体，不说销量大幅断裂。"}, {"text": "攀登", "is_correct": false, "explanation": "语义：“攀登”指向高处爬，与销量的变化无关。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭掉，不能用于描述销量的变化。"}], "explanations": {"下跌": "正确。“大幅下跌”表示销量急剧减少，符合句中的语境。", "断裂": "搭配：“断裂”用于绳索、骨骼等实体，不说销量大幅断裂。", "攀登": "语义：“攀登”指向高处爬，与销量的变化无关。", "熄灭": "语义：“熄灭”指火或光灭掉，不能用于描述销量的变化。"}, "sentence_index": 6, "correct_answer": "下跌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的脾气下跌了很多，大家都很惊讶。", "explanation": "这里应该用〈缓和〉。下跌只用于价格、水平等数值的降低，性格、脾气的变化要说“缓和”。"}, {"text": "这篇文章的字数下跌了一半。", "explanation": "这里应该用〈减少〉。下跌用于价格、股价、水平等数值的降低，字数的减少要用“减少”，不能说下跌。"}, {"text": "他听到这件事以后，心情突然下跌。", "explanation": "这里应该用〈低落〉。下跌用于价格、数值，情绪的消沉要说“低落”，不说下跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个星期鸡蛋的价格下跌地很厉害。", "corrected_sentence": "这个星期鸡蛋的价格下跌得很厉害。", "error_description": "补语标记错误：“下跌”后带程度补语，要用结构助词“得”，不能用“地”。“地”用于动词前作状语，如“慢慢地下跌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月物价被下跌了不少。", "corrected_sentence": "这个月物价下跌了不少。", "error_description": "被字句错误：“下跌”是不及物动词，不能和“被”构成被动句，应去掉“被”，说“物价下跌了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
