INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自愿进行社会公共利益服务而不获取任何报酬的人。", "primary_collocate": null, "pronunciation": "zhì yuàn zhě", "ipa": "ʈʂɻ̩⁵¹ ɥɛn⁵¹ ʈʂɤ²¹⁴", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "志愿者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位志愿者每个周末都免费去养老院帮忙。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校招募了二十名志愿者，在运动会上帮忙。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者给社区里的老人免费送饭。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，志愿者帮外国客人带路。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当一名志愿者，去帮助山区的孩子。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者们穿着红色的衣服站在门口。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做过三年志愿者，很有经验。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的志愿者每天帮病人挂号。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做志愿者的人请先在网上报名。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "志愿者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "不为报酬、自愿参加公益服务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd4cdd9-db04-4902-a117-8e52e4bb86e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志愿者", "is_correct": true, "explanation": "志愿者：自愿参加服务的人，符合全句植树、巡护、监测的行动主体。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不会长期轮值巡护林带、记录树苗，与全句的志愿行动不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人无法植树、建立监测站，与句中的行动不符。"}, {"text": "宝宝", "is_correct": false, "explanation": "语域：“宝宝们”口语亲昵，与书面的叙述语体不协调。"}], "explanations": {"志愿者": "志愿者：自愿参加服务的人，符合全句植树、巡护、监测的行动主体。", "游客": "语义：游客不会长期轮值巡护林带、记录树苗，与全句的志愿行动不符。", "病人": "语义：病人无法植树、建立监测站，与句中的行动不符。", "宝宝": "语域：“宝宝们”口语亲昵，与书面的叙述语体不协调。"}, "sentence_index": 0, "correct_answer": "志愿者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的志愿者每月领取工资。", "explanation": "这里应该用〈员工〉。志愿者不取报酬，每月领工资的人要用员工。"}, {"text": "我家请了一个志愿者，每月付工资，负责做饭。", "explanation": "这里应该用〈保姆〉。志愿者不取报酬，有偿雇来做饭的人要用保姆。"}, {"text": "这只志愿者每天都来帮忙。", "explanation": "量词错误：这里应该用〈位〉或〈名〉。“只”多用于动物或成对物品中的一个，指人不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志愿者", "is_correct": true, "explanation": "志愿者：穿着统一服装站在门口的人，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的物质，不能穿衣服站在门口，句意矛盾。"}, {"text": "门柱", "is_correct": false, "explanation": "体貌：门柱是固定的立柱，不能穿衣服站立。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不会穿衣服站在门口，与句意矛盾。"}], "explanations": {"志愿者": "志愿者：穿着统一服装站在门口的人，与句意相符。", "空气": "语义：空气是无形的物质，不能穿衣服站在门口，句意矛盾。", "门柱": "体貌：门柱是固定的立柱，不能穿衣服站立。", "树木": "语义：树木不会穿衣服站在门口，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "志愿者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他作为一名志愿者，必须服役两年。", "explanation": "这里应该用〈义务兵〉。志愿者是自愿参加的，没有强制性；必须服役的人要用义务兵。"}, {"text": "这套房子的志愿者每月向房客收租。", "explanation": "这里应该用〈房东〉。志愿者不以营利为目的，不向他人收费；收租的人要用房东。"}, {"text": "志愿者被迫在田里干活。", "explanation": "这里应该用〈奴隶〉。被迫劳动的人要用奴隶，志愿者是自愿参加的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年在医院当了一条志愿者。", "corrected_sentence": "他去年在医院当了一名志愿者。", "error_description": "量词错误：指人的“志愿者”应用“名”或“位”，“条”用于细长的事物，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一名志愿者们。", "corrected_sentence": "他是一名志愿者。", "error_description": "“们”只用于复数，前面有“一名”这样的数量词时不能再加“们”，应说“一名志愿者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容某件事或某个状态只在一定时期出现，不是全年或一直都有。", "primary_collocate": null, "pronunciation": "jì jié xìng", "ipa": "tɕi˥˩ tɕje˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "季节性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份季节性工作只在夏天有。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草莓是季节性水果，春天才有。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在海边找了一份季节性的工作。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病有季节性，多在冬天出现。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅游业的季节性很强，夏天人多。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "季节性的花只开一两个月。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民做的是季节性的活儿，冬天没事做。", "target_word": "季节性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖季节性的菜，每个月都不一样。", "target_word": "季节性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "季节性的雨水集中在七八月。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "季節性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只在某个季节或时期出现的，非全年的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "季节性", "is_correct": true, "explanation": "正确。“季节性任务”指只在特定时期进行的任务，与后文“持续性”的对照相合。"}, {"text": "持续性", "is_correct": false, "explanation": "语义：“持续性任务”与后文的“持续性的本地行动”相矛盾，不能与前文的否定构成对照。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指无规律、偶然发生，与句中有计划的巡护、轮值不符。"}, {"text": "夜间性", "is_correct": false, "explanation": "搭配：“夜间性”指发生在夜里，植树并非夜间活动，不说夜间性任务。"}], "explanations": {"季节性": "正确。“季节性任务”指只在特定时期进行的任务，与后文“持续性”的对照相合。", "持续性": "语义：“持续性任务”与后文的“持续性的本地行动”相矛盾，不能与前文的否定构成对照。", "随机性": "语义：“随机性”指无规律、偶然发生，与句中有计划的巡护、轮值不符。", "夜间性": "搭配：“夜间性”指发生在夜里，植树并非夜间活动，不说夜间性任务。"}, "sentence_index": 0, "correct_answer": "季节性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗彗星是季节性出现的，大约每七十六年一次。", "explanation": "这里应该用〈周期性〉。季节性指按一年中的季节出现，七十六年一次的现象要说“周期性”。"}, {"text": "这场洪水是季节性的，几十年才遇到一次。", "explanation": "这里应该用〈偶发〉。季节性指按季节反复出现，几十年才一次的现象要说“偶发”。"}, {"text": "这次地震是季节性的，只发生过一次。", "explanation": "这里应该用〈突发〉。季节性指按一定时期反复出现，只发生一次的地震要说“突发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季节性", "is_correct": true, "explanation": "正确。“季节性的花”指只在一定时期开放的花，与“只开一两个月”相合。"}, {"text": "永久性", "is_correct": false, "explanation": "语义：“永久性”指长久不变，与“只开一两个月”的时限相矛盾。"}, {"text": "常年性", "is_correct": false, "explanation": "语义：“常年性”指全年都有，与“只开一两个月”相矛盾。"}, {"text": "长期性", "is_correct": false, "explanation": "搭配：“长期性”多用于计划、工作，不用来形容花的开放时间。"}], "explanations": {"季节性": "正确。“季节性的花”指只在一定时期开放的花，与“只开一两个月”相合。", "永久性": "语义：“永久性”指长久不变，与“只开一两个月”的时限相矛盾。", "常年性": "语义：“常年性”指全年都有，与“只开一两个月”相矛盾。", "长期性": "搭配：“长期性”多用于计划、工作，不用来形容花的开放时间。"}, "sentence_index": 6, "correct_answer": "季节性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的服务是季节性的，全年都在。", "explanation": "这里应该用〈持续性〉。季节性指只在一定时期出现，全年都在的服务要说“持续性”。"}, {"text": "他每天的学习时间是季节性的。", "explanation": "这里应该用〈固定〉。季节性指只在一定时期出现，每天都固定的学习时间要说“固定”。"}, {"text": "这个学校的课程每天都一样，是季节性安排的。", "explanation": "这里应该用〈固定〉。“季节性”指只在一定时期出现，每天都一样的课程要说“固定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店季节性强很，冬天几乎不开门。", "corrected_sentence": "这家店季节性很强，冬天几乎不开门。", "error_description": "语序错误：“很”修饰形容词，应放在“强”前，说“季节性很强”，不能说“季节性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个海滩的人流有很强季节性，冬天几乎没人。", "corrected_sentence": "这个海滩的人流有很强的季节性，冬天几乎没人。", "error_description": "定语错误：“很强”修饰名词“季节性”时中间要加“的”，应说“很强的季节性”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
