INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13522, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物或现象在一定时间内保持状态或性质不变的特性。", "primary_collocate": null, "pronunciation": "chí xù xìng", "ipa": "ʈʂʰɻ̩˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "持续性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个计划需要持续性，不能做做停停。", "target_word": "持续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学语言要有持续性，每天都要学。", "target_word": "持续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种努力的持续性很强，已经坚持了五年。", "target_word": "持续性", "complexity_tier": "T3", "furigana": "zhè zhǒng nǔ lì de chí xù xìng hěn qiáng, yǐ jīng jiān chí le wǔ nián.", "sentence_source": "generated"}, {"text": "运动的好处来自持续性，不是一次。", "target_word": "持续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种疼痛有持续性，要去看医生。", "target_word": "持续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作缺少持续性，常常换地方。", "target_word": "持续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法的持续性不好，很快就没用了。", "target_word": "持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好习惯的关键是持续性。", "target_word": "持续性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，学习的持续性比速度重要。", "target_word": "持续性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "持續性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物长时间保持不变、不中断的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持续性", "is_correct": true, "explanation": "与“本地行动”搭配，指事物长时间保持不变的特性，句中“轮值巡护”“记录”等都体现长期性。"}, {"text": "短期性", "is_correct": false, "explanation": "语义：“短期性”与后文“轮值巡护林带”“建立民间监测站”的长期投入相悖。"}, {"text": "随机性", "is_correct": false, "explanation": "搭配：“随机性”多修饰结果或过程，与有计划的“行动”搭配不当。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：前文已说“不再将植树视为季节性任务”，此处再用“季节性”与句意矛盾。"}], "explanations": {"持续性": "与“本地行动”搭配，指事物长时间保持不变的特性，句中“轮值巡护”“记录”等都体现长期性。", "短期性": "语义：“短期性”与后文“轮值巡护林带”“建立民间监测站”的长期投入相悖。", "随机性": "搭配：“随机性”多修饰结果或过程，与有计划的“行动”搭配不当。", "季节性": "语义：前文已说“不再将植树视为季节性任务”，此处再用“季节性”与句意矛盾。"}, "sentence_index": 0, "correct_answer": "持续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次地震的持续性很强，只有几秒钟。", "explanation": "这里应该用〈持续时间〉。持续性说事物保持不变的特性，说一件事经历了多长时间要用〈持续时间〉。"}, {"text": "这条马路的持续性很长，从城东一直到城西。", "explanation": "这里应该用〈长度〉。持续性说事物在时间上保持不变的特性，不说空间上的远近长短；马路的长度要用〈长度〉。"}, {"text": "这台机器的持续性很高，一小时能包装两千个盒子。", "explanation": "这里应该用〈效率〉。持续性说事物保持不变的特性，说工作的快慢和产量要用〈效率〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持续性", "is_correct": true, "explanation": "与“常常换地方”相对应，说明工作缺少长时间保持的特性。"}, {"text": "合法性", "is_correct": false, "explanation": "语义：“合法性”指是否符合法律，与“常常换地方”所说的情况无关。"}, {"text": "学术性", "is_correct": false, "explanation": "语域：“学术性”多用于研究、论文，一般工作不用这个词。"}, {"text": "地域性", "is_correct": false, "explanation": "搭配：“地域性”修饰文化、习俗，不修饰工作。"}], "explanations": {"持续性": "与“常常换地方”相对应，说明工作缺少长时间保持的特性。", "合法性": "语义：“合法性”指是否符合法律，与“常常换地方”所说的情况无关。", "学术性": "语域：“学术性”多用于研究、论文，一般工作不用这个词。", "地域性": "搭配：“地域性”修饰文化、习俗，不修饰工作。"}, "sentence_index": 6, "correct_answer": "持续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车的持续性很快，半个小时就到了。", "explanation": "这里应该用〈速度〉。持续性说事物保持不变的特性，不说行驶的快慢；车跑得快慢要用〈速度〉来说。"}, {"text": "他的持续性很有名，全校都知道他。", "explanation": "这里应该用〈名气〉。持续性说事物保持不变的特性，不用来说人的名气；名气大要用〈名气〉。"}, {"text": "他对工作的持续性很认真。", "explanation": "这里应该用〈态度〉。持续性说事物保持不变的特性，不用来形容人做事的态度；工作态度要用〈态度〉来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项研究需要很持续性，不能三心二意。", "corrected_sentence": "这项研究需要持续性，不能三心二意。", "error_description": "副词错误：“持续性”是名词，前面不能加“很”，应说“需要持续性”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项工作靠的是一个持续性，不靠运气。", "corrected_sentence": "这项工作靠的是持续性，不靠运气。", "error_description": "量词错误：“持续性”表示抽象的特性，不宜用“一个”计数，应直接说“靠的是持续性”，去掉“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
