INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指按照顺序轮流担任某项职务或执行某项任务。", "primary_collocate": null, "pronunciation": "lún zhí", "ipa": "lu̯ən³⁵ ʈʂɻ̩³⁵", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "轮值", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们五个同学每周轮值打扫教室。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期轮值的是小李。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司安排员工轮值，节日也有人接电话。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位医生轮值夜班，每人一晚。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长按名单安排大家轮值擦黑板。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们轮值了三个月，现在换新人了。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年由我们学校轮值主办这个活动。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的保安晚上轮值，门口一直有人。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下周由我们组轮值，大家要早点来。", "target_word": "轮值", "complexity_tier": "T3", "furigana": "xià zhōu yóu wǒ men zǔ lún zhí, dà jiā yào zǎo diǎn lái.", "sentence_source": "generated"}], "morphological_forms": [{"form": "轮值了", "label": "体标"}, {"form": "轮值过", "label": "体标"}, {"form": "轮值着", "label": "体标"}], "register": "中性", "sense_fingerprint": "按顺序轮流担任职务或执行任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd4cdd9-db04-4902-a117-8e52e4bb86e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轮值", "is_correct": true, "explanation": "正确。轮值指按顺序轮流担任，与“轮值巡护林带”的安排相符。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能用于林带。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”用于作业、文章，不能用于巡护林带。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指养育动物，与巡护林带的行动无关。"}], "explanations": {"轮值": "正确。轮值指按顺序轮流担任，与“轮值巡护林带”的安排相符。", "收割": "搭配：“收割”的对象是庄稼，不能用于林带。", "批改": "搭配：“批改”用于作业、文章，不能用于巡护林带。", "饲养": "语义：“饲养”指养育动物，与巡护林带的行动无关。"}, "sentence_index": 0, "correct_answer": "轮值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛里，球员们轮值进了三个球。", "explanation": "这里应该用〈踢进〉。轮值指按顺序担任职务，不表示进球；进球要说踢进。"}, {"text": "妈妈生病了，我轮值了她的工作。", "explanation": "这里应该用〈替换〉。轮值强调按顺序轮流担任，不表示代替别人的工作。"}, {"text": "这次活动的会场布置，他轮值了全部工作。", "explanation": "这里应该用〈承担〉。轮值要求人员轮流，一个人包揽全部工作时不用轮值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轮值", "is_correct": true, "explanation": "正确。轮值了三个月指按顺序轮流担任，与“换新人了”相符。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指出生或产生，不能用于人员轮换的时段。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体症状，不能描述人员轮换。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”须带修理的对象，“修理了三个月”缺少受事，且与“换新人了”不搭。"}], "explanations": {"轮值": "正确。轮值了三个月指按顺序轮流担任，与“换新人了”相符。", "诞生": "语义：“诞生”指出生或产生，不能用于人员轮换的时段。", "咳嗽": "语义：“咳嗽”是身体症状，不能描述人员轮换。", "修理": "配价：“修理”须带修理的对象，“修理了三个月”缺少受事，且与“换新人了”不搭。"}, "sentence_index": 6, "correct_answer": "轮值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他轮值了一下午的文件。", "explanation": "这里应该用〈整理〉。轮值表示按顺序担任职务或任务，不能用来指处理文件。"}, {"text": "工人轮值了屋顶的漏洞。", "explanation": "这里应该用〈修补〉。轮值不能带“漏洞”这类修补对象。"}, {"text": "他轮值了一个新的游戏。", "explanation": "这里应该用〈玩〉。轮值指按顺序担任职务或任务，不能用来指进行游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个星期被我轮值夜班。", "corrected_sentence": "这个星期由我轮值夜班。", "error_description": "施事标记应用“由”，不能用“被”：“被我轮值夜班”不成立，应说“由我轮值夜班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下周一我们班轮值了，负责开门。", "corrected_sentence": "下周一我们班轮值，负责开门。", "error_description": "“下周一”指将来，“轮值”后不能加“了”，应去掉“了”：“下周一我们班轮值，负责开门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
