INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13525, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13525, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在特定区域内来回查看，确保安全或规则得到遵守。", "primary_collocate": null, "pronunciation": "xún hù", "ipa": "ɕyn³⁵ xu⁵¹", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "巡护", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "护林员每天骑车巡护这片森林。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着河边巡护，检查有没有人乱倒垃圾。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区的工作人员每周巡护三次。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天天气干燥，大家要多巡护山林，防止着火。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者沿着海边巡护，保护小海龟。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这片草原巡护了十年。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪山上很冷，巡护的人要穿厚衣服。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护林员今天要巡护北边的山。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员骑马巡护，发现了一只受伤的鸟。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡护了", "label": "体标"}, {"form": "巡护过", "label": "体标"}, {"form": "巡护着", "label": "体标"}], "register": "中性", "sense_fingerprint": "在林区等特定区域来回查看以保安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd4cdd9-db04-4902-a117-8e52e4bb86e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巡护", "is_correct": true, "explanation": "正确。巡护指在区域内来回查看，与“林带”相配。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”指伐树，会破坏林带，与巡护的查看行动不符。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能用于林带。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋等建筑，不能用于林带。"}], "explanations": {"巡护": "正确。巡护指在区域内来回查看，与“林带”相配。", "砍伐": "语义：“砍伐”指伐树，会破坏林带，与巡护的查看行动不符。", "收割": "搭配：“收割”的对象是庄稼，不能用于林带。", "装修": "搭配：“装修”用于房屋等建筑，不能用于林带。"}, "sentence_index": 0, "correct_answer": "巡护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士每晚在病房巡护病人。", "explanation": "这里应该用〈看护〉。巡护指在区域内来回查看，不指照看人，照看病人要用看护。"}, {"text": "老师认真巡护了每一本作业。", "explanation": "这里应该用〈批改〉。巡护用于区域的查看，不能带“作业”作对象。"}, {"text": "他每周都去医院巡护生病的奶奶。", "explanation": "这里应该用〈探望〉。巡护指在区域内查看，不能用于看望人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巡护", "is_correct": true, "explanation": "正确。巡护指在区域内来回查看，与“这片草原”相配。"}, {"text": "排队", "is_correct": false, "explanation": "语义：“排队”指按顺序等候，与草原上来回查看的语境不符。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：“烧制”指烧制陶瓷等器物，不指在草原上做事。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，与草原这一区域无关。"}], "explanations": {"巡护": "正确。巡护指在区域内来回查看，与“这片草原”相配。", "排队": "语义：“排队”指按顺序等候，与草原上来回查看的语境不符。", "烧制": "语义：“烧制”指烧制陶瓷等器物，不指在草原上做事。", "咳嗽": "语义：“咳嗽”是身体动作，与草原这一区域无关。"}, "sentence_index": 6, "correct_answer": "巡护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察在城里巡护逃犯。", "explanation": "这里应该用〈搜索〉。巡护指在区域内来回查看，不能带“逃犯”作宾语去寻找人。"}, {"text": "工人每天巡护窗户。", "explanation": "这里应该用〈清洗〉。巡护用于查看区域安全，不能用于清洁窗户。"}, {"text": "饭店每晚巡护客人。", "explanation": "这里应该用〈招待〉。巡护指区域内的查看，不能用于接待客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护林员每天把山里巡护一圈。", "corrected_sentence": "护林员每天在山里巡护一圈。", "error_description": "“巡护”不用“把”字句引出地点，地点应用“在”引出：应为“在山里巡护一圈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天很巡护一条小路。", "corrected_sentence": "他每天都巡护一条小路。", "error_description": "“很”修饰形容词或心理动词，不修饰巡护这类动作动词，应改为“都”：“他每天都巡护一条小路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa5c5a7-b6f0-4590-ade9-e039e51ba8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
