INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人民中间，与官方或上层社会相对的社会大众。", "primary_collocate": null, "pronunciation": "mín jiān", "ipa": "min˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "这个故事是从民间传来的。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间也有很多会做菜的高手。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌在民间流传了很多年。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府和民间一起帮助了灾区。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢收集民间的老故事。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间的力量也不能小看。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多好办法来自民间。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项活动是民间组织的。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间艺人在广场上唱着歌。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手艺最早出现在民间。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与官方相对的社会大众", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb29c12-df19-4141-bf41-f1f338f175aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民间", "is_correct": true, "explanation": "“民间”指与官方相对的社会大众，「这个故事是从民间传来的」语义通顺，符合故事流传的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能作为故事的来源，“从冰箱传来的故事”不成立。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：地铁是交通设施，不会是故事的来源，与句中“传来”的语境不合。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机与故事的流传无关，句意不通。"}], "explanations": {"民间": "“民间”指与官方相对的社会大众，「这个故事是从民间传来的」语义通顺，符合故事流传的语境。", "冰箱": "语义：冰箱是家用电器，不能作为故事的来源，“从冰箱传来的故事”不成立。", "地铁": "搭配：地铁是交通设施，不会是故事的来源，与句中“传来”的语境不合。", "洗衣机": "语义：洗衣机与故事的流传无关，句意不通。"}, "sentence_index": 0, "correct_answer": "民间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份通知是民间发布的，要求全市都要执行。", "explanation": "「民间」指政府以外的社会大众，要求全市执行的通知只能由官方发布。这里应该用〈官方〉来说明发布者。"}, {"text": "市长是民间的代表，常在会上发言。", "explanation": "“民间”指社会大众，市长是官方人员，不能说成民间的代表。这里应该用〈政府〉来说明他的身份。"}, {"text": "这个小区的民间很干净。", "explanation": "“民间”指社会大众，不指小区的环境或范围。这里应该用〈环境〉来描述小区的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民间", "is_correct": true, "explanation": "“民间”指社会大众，「很多好办法来自民间」语义通顺，符合办法来源的语境。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能作为办法的来源，句子不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时用品，与办法的来源无关。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：拖鞋是日常用品，不能作为“好办法”的来源。"}], "explanations": {"民间": "“民间”指社会大众，「很多好办法来自民间」语义通顺，符合办法来源的语境。", "饼干": "语义：饼干是食品，不能作为办法的来源，句子不通。", "闹钟": "语义：闹钟是计时用品，与办法的来源无关。", "拖鞋": "搭配：拖鞋是日常用品，不能作为“好办法”的来源。"}, "sentence_index": 6, "correct_answer": "民间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个公司的民间今年增长很快。", "explanation": "“民间”指社会大众，不能指公司的业绩或规模。这里应该用〈营收〉来说明增长情况。"}, {"text": "他是民间的一名局长。", "explanation": "“民间”与官方相对，局长是政府官员，不能说成民间的。这里应该用〈官方〉来说明他的身份。"}, {"text": "我们班的民间很干净。", "explanation": "“民间”指社会大众，不指班级的卫生情况。这里应该用〈教室〉来描述班级的环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个民间故事的有意思。", "corrected_sentence": "这个民间故事很有意思。", "error_description": "结构错误：「有意思」前要用副词「很」修饰，「的」是助词，不能代替「很」，应说「这个民间故事很有意思」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种说法民间很普遍。", "corrected_sentence": "这种说法在民间很普遍。", "error_description": "介词缺失：表示处所的「民间」须由介词「在」引出，应说「在民间很普遍」，漏掉「在」则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
