INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13529, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设置用来观察、测量环境数据（如空气、水质、气象等）的固定场所。", "primary_collocate": null, "pronunciation": "jiān cè zhàn", "ipa": "tɕjɛn˥ tsʰɤ˥˩ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "监测站", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "山脚下新建了一个空气监测站。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测站每天都会记录水质数据。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在监测站工作了三年。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的监测站发现水有问题。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们参观了城里的监测站。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测站里的机器一直开着。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个监测站离我家不远。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们自己建了一个监测站。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测站的老师傅每天看数据。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "監測站", "label": "繁体"}], "register": "书面", "sense_fingerprint": "观察测量环境数据的固定场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb29c12-df19-4141-bf41-f1f338f175aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13529, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监测站", "is_correct": true, "explanation": "正确：监测站是设置用来观测、测量环境数据的场所，与追踪地下水位和鸟类迁徙轨迹相符。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场用于种植和养殖，不用于追踪地下水位和鸟类迁徙轨迹。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场供人游玩，不用于观测和记录环境数据。"}, {"text": "气氛", "is_correct": false, "explanation": "搭配：“建立”的对象是机构或设施，不能说“建立气氛”，应说“营造气氛”。"}], "explanations": {"监测站": "正确：监测站是设置用来观测、测量环境数据的场所，与追踪地下水位和鸟类迁徙轨迹相符。", "农场": "语义：农场用于种植和养殖，不用于追踪地下水位和鸟类迁徙轨迹。", "游乐场": "语义：游乐场供人游玩，不用于观测和记录环境数据。", "气氛": "搭配：“建立”的对象是机构或设施，不能说“建立气氛”，应说“营造气氛”。"}, "sentence_index": 0, "correct_answer": "监测站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车每年都要去监测站做年检。", "explanation": "这里应该用〈检测站〉。监测站用于观测空气、水质等环境数据，车辆年检要去检测站。"}, {"text": "学校门口装了监测站，防止陌生人随便进出。", "explanation": "这里应该用〈监视器〉。监测站用于测量环境数据，不用于监视人员进出。"}, {"text": "他每年都去监测站做体检。", "explanation": "这里应该用〈体检站〉。监测站测量的是环境数据，不用于给人做身体检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监测站", "is_correct": true, "explanation": "正确：监测站里放有持续运行的仪器，与“机器一直开着”相符。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不是放置机器的场所，不能说“字典里的机器一直开着”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情里”不能放置机器，“心情里的机器”也无法搭配。"}, {"text": "甜点", "is_correct": false, "explanation": "语义：甜点是食物，里面不会有一直开着的机器。"}], "explanations": {"监测站": "正确：监测站里放有持续运行的仪器，与“机器一直开着”相符。", "字典": "语义：字典不是放置机器的场所，不能说“字典里的机器一直开着”。", "心情": "搭配：“心情里”不能放置机器，“心情里的机器”也无法搭配。", "甜点": "语义：甜点是食物，里面不会有一直开着的机器。"}, "sentence_index": 6, "correct_answer": "监测站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上在监测站等公交车。", "explanation": "这里应该用〈车站〉。监测站是测量环境数据的场所，等公交车要去车站。"}, {"text": "他开车去监测站加油。", "explanation": "这里应该用〈加油站〉。监测站是观测设施，加油要去加油站。"}, {"text": "周末我们全家去监测站住宿。", "explanation": "这里应该用〈旅馆〉。监测站是观测设施，不供人住宿，住宿要去旅馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市里在河边建了一条监测站，每天测量水质。", "corrected_sentence": "市里在河边建了一座监测站，每天测量水质。", "error_description": "量词错误：监测站是建筑设施，应说“一座监测站”，不说“一条监测站”；“条”多用于狭长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把损坏的监测站修好的，今天能继续测水质。", "corrected_sentence": "工人把损坏的监测站修好了，今天能继续测水质。", "error_description": "把字句谓语不完整：「把」字句的谓语须是完整的动词短语，应说「把损坏的监测站修好了」，句末「修好的」使其成为名词性短语，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义：“简易”指构造简单，“复杂”指构造繁多，二者相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“简易”无反义关系，“漂亮”形容外观好看。"}, {"text": "明亮", "is_correct": false, "explanation": "与“简易”无反义关系，“明亮”形容光线或颜色。"}, {"text": "热情", "is_correct": false, "explanation": "与「简易」无反义关系，「热情」形容待人的态度。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义：“简易”指构造简单，“复杂”指构造繁多，二者相对。", "漂亮": "与“简易”无反义关系，“漂亮”形容外观好看。", "明亮": "与“简易”无反义关系，“明亮”形容光线或颜色。", "热情": "与「简易」无反义关系，「热情」形容待人的态度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义：“简易”指构造简单，“复杂”指构造繁多，二者相对。"}, {"text": "热闹", "is_correct": false, "explanation": "与“简易”无反义关系，“热闹”形容场面或气氛。"}, {"text": "沉默", "is_correct": false, "explanation": "与「简易」无反义关系，「沉默」形容人不说话。"}, {"text": "朴素", "is_correct": false, "explanation": "与“简易”无反义关系，“朴素”指不华丽，并非“简易”的反面。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义：“简易”指构造简单，“复杂”指构造繁多，二者相对。", "热闹": "与“简易”无反义关系，“热闹”形容场面或气氛。", "沉默": "与「简易」无反义关系，「沉默」形容人不说话。", "朴素": "与“简易”无反义关系，“朴素”指不华丽，并非“简易”的反面。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "简单而容易，不复杂。", "primary_collocate": null, "pronunciation": "jiǎn yì", "ipa": "tɕjɛn˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "简易", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "没有买桌子，我们用木板搭了一个简易的小桌子。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有电，只有一间简易的小房子。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，工人在路边搭了简易的帐篷。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室太远，学生们用简易的工具做了小实验。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没钱盖房子，他在院子里修了简易厕所。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河上没有大桥，村民用木头搭了一座简易桥。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边没有医院，医生只能给伤者做简易的包扎。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有一个用木板围成的简易篮球场。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野外没有炉子，我们只能用简易的灶做饭。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡易", "label": "繁体"}], "register": "书面", "sense_fingerprint": "简易·形容词·器具、设施构造简单，不复杂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb29c12-df19-4141-bf41-f1f338f175aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简易", "is_correct": true, "explanation": "正确：“简易设备”指构造简单的设备，与民间自行搭建的观测条件相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外观，不用来修饰用于追踪数据的设备。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：设备没有情绪，“悲伤设备”与句意完全不符。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容环境或人的状态，不用来修饰设备。"}], "explanations": {"简易": "正确：“简易设备”指构造简单的设备，与民间自行搭建的观测条件相符。", "漂亮": "搭配：“漂亮”形容外观，不用来修饰用于追踪数据的设备。", "悲伤": "语义：设备没有情绪，“悲伤设备”与句意完全不符。", "安静": "搭配：“安静”形容环境或人的状态，不用来修饰设备。"}, "sentence_index": 0, "correct_answer": "简易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很简易，从不说谎。", "explanation": "这里应该用〈简单〉。简易指器具、设施构造不复杂，形容人的性格要用简单。"}, {"text": "这孩子头脑很简易，学什么都比别人慢。", "explanation": "这里应该用〈简单〉。简易指器具、设施构造简便，形容人的头脑要用简单。"}, {"text": "他把会议的内容讲得很简易，只用了两句话。", "explanation": "这里应该用〈简略〉。简易指构造、操作简便，概括叙述的详略要用简略。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简易", "is_correct": true, "explanation": "正确：“简易桥”指用简单材料搭成的桥，与“用木头搭”相符。"}, {"text": "宏伟", "is_correct": false, "explanation": "语义：“宏伟”形容规模大、气势壮观，与“没有大桥”和“用木头搭”矛盾。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：“豪华”一般不用来形容桥梁，木头搭成的临时桥也不能用它修饰。"}, {"text": "富丽", "is_correct": false, "explanation": "语义：“富丽”形容华美，与用木头临时搭建的桥不符。"}], "explanations": {"简易": "正确：“简易桥”指用简单材料搭成的桥，与“用木头搭”相符。", "宏伟": "语义：“宏伟”形容规模大、气势壮观，与“没有大桥”和“用木头搭”矛盾。", "豪华": "搭配：“豪华”一般不用来形容桥梁，木头搭成的临时桥也不能用它修饰。", "富丽": "语义：“富丽”形容华美，与用木头临时搭建的桥不符。"}, "sentence_index": 6, "correct_answer": "简易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个很简易的人，从不计较。", "explanation": "这里应该用〈简单〉。简易指器具、设施构造简便，形容人要用简单。"}, {"text": "他做事很简易，经常忘记带东西。", "explanation": "这里应该用〈马虎〉。简易指器具、设施构造简便，形容做事态度要用马虎。"}, {"text": "他最近情绪很简易，常常一句话就生气。", "explanation": "这里应该用〈急躁〉。简易指器具、设施构造简便，形容情绪要用急躁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些年轻人用简易地工具修好了水管。", "corrected_sentence": "这些年轻人用简易的工具修好了水管。", "error_description": "助词错误：“简易”修饰名词“工具”，应用“的”，不能用“地”；“地”用于动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个棚子搭地很简易，几个人一天就能完成。", "corrected_sentence": "这个棚子搭得很简易，几个人一天就能完成。", "error_description": "补语标记错误：动词后的程度补语应用结构助词“得”，不能用“地”；“地”用于动词前修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0978689b-67ac-4035-adb1-8d40f8ec0bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
