INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13531, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟随着寻找目标，以便发现其行踪或结果。", "primary_collocate": null, "pronunciation": "zhuī zōng", "ipa": "ʈʂweɪ˥ tsʊŋ˥", "syllable_count": 2, "sentences": [{"text": "科学家用卫星追踪这只大雁的路线。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生追踪了病人三个月的血压变化。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用软件追踪每个包裹的位置。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在追踪这个案子的结果。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者追踪这条新闻已经两年了。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以在手机上追踪快递的位置。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员追踪了这群海龟好几年。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察通过手机信号追踪到了小偷。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说要长期追踪学生的学习情况。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能追踪你每天走多少步。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追踪了", "label": "完成体"}, {"form": "追踪着", "label": "持续体"}, {"form": "追踪过", "label": "经历体"}, {"form": "追蹤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "追踪：借助工具、数据或持续关注，跟踪目标以了解其行踪或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追踪", "is_correct": true, "explanation": "正确：“追踪”指借助卫星持续跟随目标，以了解大雁的行踪，与句意相符。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”是人为规划，大雁的飞行路线由迁徙本能形成，不能由人设计。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，“路线”不能被吃。"}, {"text": "驯养", "is_correct": false, "explanation": "配价：“驯养”要求动物作宾语，句中的“路线”不能被驯养。"}], "explanations": {"追踪": "正确：“追踪”指借助卫星持续跟随目标，以了解大雁的行踪，与句意相符。", "设计": "语义：“设计”是人为规划，大雁的飞行路线由迁徙本能形成，不能由人设计。", "吃": "搭配：“吃”的对象是食物，“路线”不能被吃。", "驯养": "配价：“驯养”要求动物作宾语，句中的“路线”不能被驯养。"}, "sentence_index": 0, "correct_answer": "追踪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她一直在追踪心中的理想。", "explanation": "这里应该用〈追求〉。“追踪”只用于寻找行踪或结果，不能用来说理想。"}, {"text": "他努力追踪落下的功课。", "explanation": "这里应该用〈追赶〉。“追赶”指赶上落后的进度，“追踪”指沿痕迹寻找，不能用于功课。"}, {"text": "他一直在追踪这件事的责任，不肯放手。", "explanation": "这里应该用〈追究〉。“追踪”指借助痕迹或数据寻找行踪或结果，不能用来说要求查明并负责，那要用〈追究〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追踪", "is_correct": true, "explanation": "正确：“追踪”表示持续跟随海龟以了解其情况，与“研究人员”和“好几年”相符。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”表示殴打，与研究人员对海龟的观察工作相悖。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”的对象通常是数据或文件，不能用于“这群海龟”。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”含有恶意伤害的意思，与研究人员的身份和“研究”的语境不合。"}], "explanations": {"追踪": "正确：“追踪”表示持续跟随海龟以了解其情况，与“研究人员”和“好几年”相符。", "打": "语义：“打”表示殴打，与研究人员对海龟的观察工作相悖。", "删除": "搭配：“删除”的对象通常是数据或文件，不能用于“这群海龟”。", "欺负": "语义：“欺负”含有恶意伤害的意思，与研究人员的身份和“研究”的语境不合。"}, "sentence_index": 6, "correct_answer": "追踪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈一直追踪孩子的友谊。", "explanation": "这里应该用〈维护〉。“追踪”指沿痕迹寻找行踪或结果，不能用来说维护友谊。"}, {"text": "学生追踪老师学习英语。", "explanation": "这里应该用〈跟随〉。“追踪”是寻找目标的行踪，不能用来说跟着人学习。"}, {"text": "老师追踪学生为什么迟到。", "explanation": "这里应该用〈追问〉。“追踪”不能接“为什么迟到”这类问句，要表示穷追不舍地问要用〈追问〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员用雷达追踪了着台风的路线。", "corrected_sentence": "研究人员用雷达追踪着台风的路线。", "error_description": "错误：“了”与“着”不能同用，写成“追踪了着”。正确：“追踪着”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家通过卫星追踪了到这只鸟的迁徙路线。", "corrected_sentence": "科学家通过卫星追踪到了这只鸟的迁徙路线。", "error_description": "错误：“了”放在结果补语“到”之前，写成“追踪了到”。正确：“追踪到了”。结果补语“到”应紧接动词，“了”应放在“到”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
