INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过种植植物改善环境并促进社区参与的生态行动", "primary_collocate": null, "pronunciation": "lǜ huà", "ipa": "ly˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，该项目的深层意义早已超越单纯的绿化指标。", "target_word": "绿化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "社区的绿化活动让邻居们认识了彼此。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次绿化需要居民一起参加。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的绿化行动从春天开始。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区绿化让大家有机会一起做事。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为社区绿化准备了很多树苗。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿化不只是种树，也是邻里合作。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小区的绿化项目有很多志愿者。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民参加绿化活动后，更愿意爱护环境。", "target_word": "绿化", "complexity_tier": "T3", "furigana": "jūmín cānjiā lǜhuà huódòng hòu, gèng yuànyì àihù huánjìng.", "sentence_source": "generated"}, {"text": "村里的绿化工作需要大家商量。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绿化带", "label": "复合"}, {"form": "绿化率", "label": "复合"}, {"form": "綠化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "社区居民共同参与的生态绿化行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7050c44d-4887-4a5d-8657-6743f77125d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿化", "is_correct": true, "explanation": "正确：“绿化指标”指与生态绿化相关的衡量数据，与句中的“深层意义”形成对比。"}, {"text": "厨艺", "is_correct": false, "explanation": "语义：“厨艺指标”不成立，“厨艺”与衡量环境的指标无关。"}, {"text": "书法", "is_correct": false, "explanation": "搭配：“指标”多指可量化的环境或经济数据，不说“书法指标”。"}, {"text": "美食", "is_correct": false, "explanation": "语义：“美食”与句中的深层意义和指标毫无关联，句意不通。"}], "explanations": {"绿化": "正确：“绿化指标”指与生态绿化相关的衡量数据，与句中的“深层意义”形成对比。", "厨艺": "语义：“厨艺指标”不成立，“厨艺”与衡量环境的指标无关。", "书法": "搭配：“指标”多指可量化的环境或经济数据，不说“书法指标”。", "美食": "语义：“美食”与句中的深层意义和指标毫无关联，句意不通。"}, "sentence_index": 0, "correct_answer": "绿化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们用彩灯绿化了操场。", "explanation": "这里应该用〈装饰〉。绿化是通过种植改善环境，用彩灯布置不属于绿化。"}, {"text": "政府绿化了这笔资金。", "explanation": "这里应该用〈拨付〉。绿化是通过种植改善环境的生态行动，不能用于资金。"}, {"text": "社区组织了一只绿化，居民都参加了。", "explanation": "这里应该用〈次〉。“只”用于动物等个体，不能计数绿化行动，要用“次”或“项”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿化", "is_correct": true, "explanation": "正确：“绿化”作主语，说明它不只是种树，还包括邻里合作。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”不是可以用“种树”来说明的行动，与句中的说明不相容。"}, {"text": "厨艺", "is_correct": false, "explanation": "搭配：“厨艺”不能与“种树”并列来说明同一个主语，“厨艺不只是种树”说不通。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：“篮球”与种树、邻里合作的内容毫无关系，句意不通。"}], "explanations": {"绿化": "正确：“绿化”作主语，说明它不只是种树，还包括邻里合作。", "友谊": "语义：“友谊”不是可以用“种树”来说明的行动，与句中的说明不相容。", "厨艺": "搭配：“厨艺”不能与“种树”并列来说明同一个主语，“厨艺不只是种树”说不通。", "篮球": "语义：“篮球”与种树、邻里合作的内容毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "绿化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里的孩子们常玩绿化。", "explanation": "这里应该用〈游戏〉。绿化指生态行动，不是可以玩的游戏。"}, {"text": "会计已经绿化了那笔账。", "explanation": "这里应该用〈核对〉。绿化指通过种植改善环境的生态行动，不能用于账目。"}, {"text": "社区开展了一把绿化，大家都来帮忙。", "explanation": "这里应该用〈次〉。“把”用于有柄的器具，不能用来计数绿化行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区明年会进行了绿化行动。", "corrected_sentence": "社区明年会进行绿化行动。", "error_description": "时间与体标错误：“明年”表示将来，“会进行”后不能加“了”，应说“社区明年会进行绿化行动”，不能说“进行了绿化行动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区去年进行了一只绿化。", "corrected_sentence": "社区去年进行了一次绿化。", "error_description": "量词错误：“绿化”作为一次活动，应用“次”，“只”用于动物等个体，不能用于绿化。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
