INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "举行、组织（活动、会议、比赛等）。", "primary_collocate": null, "pronunciation": "jǔ bàn", "ipa": "tɕy˨˩˦ pan˥˩", "syllable_count": 2, "sentences": [{"text": "学校下个月要举办运动会。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在北京举办了一场大会。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区每年春天都举办音乐节。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算举办一次读书比赛。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次展览由市图书馆举办。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班想举办新年晚会。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议在上海举办，来了很多人。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校举办过三次作文比赛。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来举办这次活动？", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经举办了十年音乐会。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举办了", "label": "体标"}, {"form": "举办过", "label": "体标"}, {"form": "舉辦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "组织并举行活动、会议、比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7050c44d-4887-4a5d-8657-6743f77125d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举办", "is_correct": true, "explanation": "正确：“举办运动会”指组织并举行运动会，与“下个月”的安排相合。"}, {"text": "组装", "is_correct": false, "explanation": "语义：“组装”指把零件装成整体，不能用来指组织一场运动会。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”多用于房屋、道路等，不说“修建运动会”。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”指用牙齿嚼碎食物，与运动会毫无关系。"}], "explanations": {"举办": "正确：“举办运动会”指组织并举行运动会，与“下个月”的安排相合。", "组装": "语义：“组装”指把零件装成整体，不能用来指组织一场运动会。", "修建": "搭配：“修建”多用于房屋、道路等，不说“修建运动会”。", "咀嚼": "语义：“咀嚼”指用牙齿嚼碎食物，与运动会毫无关系。"}, "sentence_index": 0, "correct_answer": "举办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们举办了这座体育馆。", "explanation": "这里应该用〈修建〉。举办用于活动、会议，建造建筑要用修建。"}, {"text": "他举办了一家书店。", "explanation": "这里应该用〈创办〉。举办用于活动、会议，开办商店、企业要用创办。"}, {"text": "村里举办了一座新桥。", "explanation": "这里应该用〈架设〉。举办用于活动、会议，桥梁要用架设或修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举办", "is_correct": true, "explanation": "正确：“会议在上海举办”指在上海组织并举行会议，与后句的人数相合。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”多用于书籍、报刊，不说“会议在上海出版”。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造产品，与会议在某地举行的意思无关。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动作，“会议在上海咳嗽”说不通。"}], "explanations": {"举办": "正确：“会议在上海举办”指在上海组织并举行会议，与后句的人数相合。", "出版": "搭配：“出版”多用于书籍、报刊，不说“会议在上海出版”。", "生产": "语义：“生产”指制造产品，与会议在某地举行的意思无关。", "咳嗽": "配价：“咳嗽”是不及物动作，“会议在上海咳嗽”说不通。"}, "sentence_index": 6, "correct_answer": "举办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们举办了一支乐队。", "explanation": "这里应该用〈组建〉。举办用于活动、会议，团体、乐队要用组建。"}, {"text": "观众举办了这场球赛。", "explanation": "这里应该用〈观看〉。观众是看的人，不是组织者，不能说举办球赛。"}, {"text": "作曲家举办了一部交响乐。", "explanation": "这里应该用〈创作〉。举办用于活动，乐曲、作品要用创作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛北京举办。", "corrected_sentence": "比赛在北京举办。", "error_description": "介词错误：“在北京”作地点状语，应说“在北京举办”，不能省略“在”直接说“北京举办”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把运动会举办。", "corrected_sentence": "学校把运动会举办了。", "error_description": "结构错误：“把”字句中动词后需要其他成分，如“了”，应说“把运动会举办了”，不能只说“把运动会举办”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
