INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13538, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指跨越或涉及多个村庄，通常用于形容道路、项目、合作等在不同村庄之间进行。", "primary_collocate": null, "pronunciation": "kuà cūn", "ipa": "kʰua˥˩ tsʰuən˥", "syllable_count": 2, "sentences": [{"text": "通过定期举办生态工作坊与跨村交流会，志愿服务成为社区建设的黏合剂。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这条跨村公路让两个村子近了很多。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县里支持跨村合作，大家一起种茶叶。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做了一个跨村的水果销售项目。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨村的小路很窄，开车要慢一点。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨村合作让两个村的农民都多赚了钱。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座跨村的桥是去年修好的。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里想建一条跨村自行车道。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨村学校让山里的孩子也能上好课。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个村子成立了跨村的养鸡合作社。", "target_word": "跨村", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "涉及多个村庄的（道路、项目、合作）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7050c44d-4887-4a5d-8657-6743f77125d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨村", "is_correct": true, "explanation": "正确：“跨村”指涉及多个村庄，修饰“交流会”，符合语境。"}, {"text": "跨年", "is_correct": false, "explanation": "语义：“跨年”指跨越新旧年，与村庄和交流会的范围无关。"}, {"text": "跨海", "is_correct": false, "explanation": "语义：“跨海”指跨越大海，与村庄之间的交流不相符。"}, {"text": "跨时代", "is_correct": false, "explanation": "语义：“跨时代”形容划时代的意义，不描述交流会的范围。"}], "explanations": {"跨村": "正确：“跨村”指涉及多个村庄，修饰“交流会”，符合语境。", "跨年": "语义：“跨年”指跨越新旧年，与村庄和交流会的范围无关。", "跨海": "语义：“跨海”指跨越大海，与村庄之间的交流不相符。", "跨时代": "语义：“跨时代”形容划时代的意义，不描述交流会的范围。"}, "sentence_index": 0, "correct_answer": "跨村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把跨村的房子都刷成了白色。", "explanation": "这里应该用〈村里的〉。“跨村”指涉及多个村庄，房子只在一处，不能是跨村的。"}, {"text": "我家的跨村猫很喜欢晒太阳。", "explanation": "这里应该用〈村里的〉。“跨村”指涉及多个村庄，用来修饰一只猫并不合适。"}, {"text": "我叫跨村，住在村东头。", "explanation": "这里应该用〈名字〉。“跨村”是形容词，指涉及多个村庄，不能用作人名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨村", "is_correct": true, "explanation": "正确：“跨村”修饰“桥”，表示桥连接多个村庄，符合语境。"}, {"text": "跨夜", "is_correct": false, "explanation": "语义：“跨夜”指跨越一夜，不能用来修饰桥。"}, {"text": "跨季", "is_correct": false, "explanation": "语义：“跨季”指跨越季节，与桥的修建无关。"}, {"text": "跨代", "is_correct": false, "explanation": "语义：“跨代”指跨越几代人，不用于描述桥。"}], "explanations": {"跨村": "正确：“跨村”修饰“桥”，表示桥连接多个村庄，符合语境。", "跨夜": "语义：“跨夜”指跨越一夜，不能用来修饰桥。", "跨季": "语义：“跨季”指跨越季节，与桥的修建无关。", "跨代": "语义：“跨代”指跨越几代人，不用于描述桥。"}, "sentence_index": 6, "correct_answer": "跨村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个养鸡合作社把鸡卖到了国外，所以它是跨村的。", "explanation": "这里应该用〈跨国〉。“跨村”指涉及多个村庄，不能用来说国际合作。"}, {"text": "这个养鸡合作社的那只鸡是跨村的。", "explanation": "这里应该用〈本村〉。“跨村”指涉及多个村庄，一只鸡只在一个村里，不能说跨村的。"}, {"text": "这个养鸡合作社只有一个村参加，却是跨村的。", "explanation": "这里应该用〈本村〉。“跨村”指涉及多个村庄，只有一个村参加时应说“本村的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路很跨村的，很方便。", "corrected_sentence": "这条路是跨村的，很方便。", "error_description": "错误在“很”。“跨村”是分类形容词，表示“涉及多个村庄”的性质，不能受程度副词“很”修饰。应说“这条路是跨村的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥很跨村的。", "corrected_sentence": "这座桥是跨村的。", "error_description": "错误在“很”。“跨村”是分类形容词，不能受程度副词“很”修饰。把“很”换成“是”，即得“这座桥是跨村的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
