INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们为了互相交流信息、经验或想法而组织的活动或会议。", "primary_collocate": null, "pronunciation": "jiāo liú huì", "ipa": "tɕjɑʊ˥ ljoʊ˧˥ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "通过定期举办生态工作坊与跨村交流会，志愿服务成为社区建设的黏合剂。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "学校下周办一场英语交流会。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我报名参加了读书交流会。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交流会上，大家说了各自的经验。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次交流会让我认识了很多新朋友。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每月开一次交流会，大家分享做法。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们在交流会上谈了教学想法。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交流会九点开始，请大家准时到。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在交流会上介绍了自己的旅行。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社区常办种花交流会。", "target_word": "交流会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "为交流信息、经验、想法而组织的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7050c44d-4887-4a5d-8657-6743f77125d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交流会", "is_correct": true, "explanation": "“交流会”指为互相交流信息和经验而组织的活动，填入句中与“志愿服务”和社区建设相合。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：“葬礼”是悼念死者的仪式，与“志愿服务成为社区建设的黏合剂”的语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验知识的活动，与“生态工作坊”和社区志愿服务的语境不合。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：“演唱会”指表演性活动，与句中强调的交流和建设目的不相合。"}], "explanations": {"交流会": "“交流会”指为互相交流信息和经验而组织的活动，填入句中与“志愿服务”和社区建设相合。", "葬礼": "语义：“葬礼”是悼念死者的仪式，与“志愿服务成为社区建设的黏合剂”的语境不符。", "考试": "语义：“考试”是测验知识的活动，与“生态工作坊”和社区志愿服务的语境不合。", "演唱会": "语义：“演唱会”指表演性活动，与句中强调的交流和建设目的不相合。"}, "sentence_index": 0, "correct_answer": "交流会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯交流会。", "explanation": "这里应该用〈咖啡〉。“交流会”是活动，不能拿来喝。"}, {"text": "我们把交流会搬到了书架上。", "explanation": "这里应该用〈书〉。“交流会”是活动，不能搬到书架上。"}, {"text": "我们参加了一只交流会。", "explanation": "这里应该用〈场〉或〈次〉。“只”用于动物或成对的东西，“交流会”是活动，不能用“只”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交流会", "is_correct": true, "explanation": "“交流会”指老师们为交流想法而参加的活动，填入句中与“谈了教学想法”相合。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“婚礼”是喜庆仪式，不是老师们谈论教学想法的场合。"}, {"text": "运动会", "is_correct": false, "explanation": "语义：“运动会”以体育竞赛为主，与“谈教学想法”的内容不符。"}, {"text": "春游", "is_correct": false, "explanation": "语义：“春游”指外出游玩，与“谈教学想法”的正式交流语境不合。"}], "explanations": {"交流会": "“交流会”指老师们为交流想法而参加的活动，填入句中与“谈了教学想法”相合。", "婚礼": "语义：“婚礼”是喜庆仪式，不是老师们谈论教学想法的场合。", "运动会": "语义：“运动会”以体育竞赛为主，与“谈教学想法”的内容不符。", "春游": "语义：“春游”指外出游玩，与“谈教学想法”的正式交流语境不合。"}, "sentence_index": 6, "correct_answer": "交流会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们社区常给交流会浇水。", "explanation": "这里应该用〈花〉。“交流会”是活动，不能浇水，浇水的对象应是植物。"}, {"text": "我们社区的交流会一共有三斤。", "explanation": "这里的量词错误。“斤”用于称重的物品，“交流会”是活动，不能用“斤”计量。"}, {"text": "我们社区常把交流会种在花园里。", "explanation": "这里应该用〈花苗〉。“交流会”是活动，不能种在花园里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们社区每年都开一把交流会。", "corrected_sentence": "我们社区每年都开一场交流会。", "error_description": "量词错误：“一把交流会”应为“一场交流会”。“把”用于有柄的东西，“交流会”是活动，应用量词“场”或“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们村上个月办了一条读书交流会。", "corrected_sentence": "他们村上个月办了一次读书交流会。", "error_description": "量词错误：“一条读书交流会”应为“一次读书交流会”。“条”用于细长的东西，“交流会”是活动，计次应用“次”或“场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
