INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依靠手工技艺制造产品或提供服务的劳动者。", "primary_collocate": null, "pronunciation": "shǒu gōng yè zhě", "ipa": "ʂoʊ˨˩˦ kʊŋ˥ jɛ˥˩ ʈʂɤ˨˩˦", "syllable_count": 4, "sentences": [{"text": "农民、学生、手工业者在共同劳作中重建了濒临瓦解的邻里纽带，形成了非正式但高效的合作网络。", "target_word": "手工业者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个小镇上有很多手工业者。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者每天在小店里做竹篮。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位手工业者做的瓷碗很漂亮。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者把自己做的东西拿到市场上卖。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前，手工业者大多住在城里。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷是一位老手工业者。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者需要很多年才能学好手艺。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场里的手工业者正在做布鞋。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些手工业者用木头做出了漂亮的家具。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手工業者", "label": "繁体"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "靠手工技艺谋生的劳动者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5550218b-ec4e-49ae-9fcc-40aea9a55e53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手工业者", "is_correct": true, "explanation": "正确：手工业者是靠手艺劳动的人，与“共同劳作”的语境相符。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是场所，不是能参与劳作、重建纽带的人。"}, {"text": "矿泉水", "is_correct": false, "explanation": "搭配：“共同劳作”的主体应是人，矿泉水不能与之搭配。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只报时，不能参与劳作、重建邻里纽带。"}], "explanations": {"手工业者": "正确：手工业者是靠手艺劳动的人，与“共同劳作”的语境相符。", "动物园": "语义：动物园是场所，不是能参与劳作、重建纽带的人。", "矿泉水": "搭配：“共同劳作”的主体应是人，矿泉水不能与之搭配。", "闹钟": "语义：闹钟只报时，不能参与劳作、重建邻里纽带。"}, "sentence_index": 0, "correct_answer": "手工业者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位手工业者在银行里负责存款和贷款。", "explanation": "这里应该用〈银行职员〉。手工业者靠手工技艺做东西，不用来指在银行工作的人。"}, {"text": "手工业者在实验室里研究新药。", "explanation": "这里应该用〈科学家〉。手工业者指做手工活的人，不是在实验室研究新药的人。"}, {"text": "工厂里的手工业者每天生产许多电器。", "explanation": "这里应该用〈工人〉。手工业者靠手工制作，不用来描述在工厂里批量生产的工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手工业者", "is_correct": true, "explanation": "正确：手工业者是劳动者，与“他的爷爷是一位老……”的语境相符。"}, {"text": "老大娘", "is_correct": false, "explanation": "语义：“大娘”指女性，与“他的爷爷”的性别不符。"}, {"text": "老姑娘", "is_correct": false, "explanation": "语义：“姑娘”指未婚的女性，与“爷爷”的性别和身份矛盾。"}, {"text": "老花镜", "is_correct": false, "explanation": "语义：“老花镜”是眼镜，不能指人，句意不通。"}], "explanations": {"手工业者": "正确：手工业者是劳动者，与“他的爷爷是一位老……”的语境相符。", "老大娘": "语义：“大娘”指女性，与“他的爷爷”的性别不符。", "老姑娘": "语义：“姑娘”指未婚的女性，与“爷爷”的性别和身份矛盾。", "老花镜": "语义：“老花镜”是眼镜，不能指人，句意不通。"}, "sentence_index": 6, "correct_answer": "手工业者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位手工业者在医院里为病人做手术。", "explanation": "这里应该用〈医生〉。手工业者指做手工活的人，不能指在医院做手术的人。"}, {"text": "这位手工业者在学校教孩子们数学。", "explanation": "这里应该用〈教师〉。手工业者靠手艺做东西，教数学的人要用〈教师〉。"}, {"text": "这位手工业者每天在公司里处理财务报表。", "explanation": "这里应该用〈会计〉。手工业者靠手艺做东西，处理财务报表的人要用〈会计〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一手工业者做的椅子很结实。", "corrected_sentence": "一位手工业者做的椅子很结实。", "error_description": "量词缺失：指人的“手工业者”前用数词“一”时要加量词“位”，应说“一位手工业者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一棵手工业者，他做的椅子很好。", "corrected_sentence": "我认识一位手工业者，他做的椅子很好。", "error_description": "量词错误：指人的“手工业者”应用“位”，“棵”只用于植物，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
