INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13544, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指邻居或同一社区的人，也指邻里关系。", "primary_collocate": null, "pronunciation": "lín lǐ", "ipa": "lin˧˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "农民、学生、手工业者在共同劳作中重建了濒临瓦解的邻里纽带，形成了非正式但高效的合作网络。", "target_word": "邻里", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们小区的邻里关系很好。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻里之间应该互相帮助。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我很想念以前的邻里。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻里发生了矛盾，社区干部来帮忙。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，邻里都会送来饺子。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的邻里往来比农村少。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和邻里相处得很愉快。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人生病时，邻里轮流照顾他。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的邻里让我们觉得很温暖。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "邻里：邻居与社区的人，及彼此的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5550218b-ec4e-49ae-9fcc-40aea9a55e53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邻里", "is_correct": true, "explanation": "正确。“邻里纽带”指附近居民之间的联结，与“共同劳作”“合作网络”的语境相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”之间本无往来，与“重建了濒临瓦解的……纽带”矛盾。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“纽带”联结的是人与人或人与关系，“工厂”是场所，不构成“纽带”的搭配。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”指同班关系，句中的农民、手工业者并非同学，不合句意。"}], "explanations": {"邻里": "正确。“邻里纽带”指附近居民之间的联结，与“共同劳作”“合作网络”的语境相合。", "陌生人": "语义：“陌生人”之间本无往来，与“重建了濒临瓦解的……纽带”矛盾。", "工厂": "搭配：“纽带”联结的是人与人或人与关系，“工厂”是场所，不构成“纽带”的搭配。", "同学": "语义：“同学”指同班关系，句中的农民、手工业者并非同学，不合句意。"}, "sentence_index": 0, "correct_answer": "邻里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天上班都能遇见一台邻里。", "explanation": "这里应该用〈位〉。〈台〉用于机器、设备，不能用来数人。"}, {"text": "今天的邻里很热，我们去游泳吧。", "explanation": "这里应该用〈天气〉。〈邻里〉指人或人际关系，不能用来描述气温。"}, {"text": "这家餐厅的邻里很好吃。", "explanation": "这里应该用〈菜〉。〈邻里〉指人或人际关系，不能用来形容食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邻里", "is_correct": true, "explanation": "正确。“城市里的邻里往来”指附近居民之间的走动，与“比农村少”的比较相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，没有“往来”的意思，句子不成立。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“往来”的主体是人或车辆，“石头”不能与“往来”搭配。"}, {"text": "树木", "is_correct": false, "explanation": "语义：“树木”是植物，不能进行“往来”，句意不通。"}], "explanations": {"邻里": "正确。“城市里的邻里往来”指附近居民之间的走动，与“比农村少”的比较相合。", "冰箱": "语义：“冰箱”是家用电器，没有“往来”的意思，句子不成立。", "石头": "搭配：“往来”的主体是人或车辆，“石头”不能与“往来”搭配。", "树木": "语义：“树木”是植物，不能进行“往来”，句意不通。"}, "sentence_index": 6, "correct_answer": "邻里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这一只邻里很热闹。", "explanation": "这里应该用〈群〉。〈邻里〉指一群邻居，应用集体量词〈群〉，不能用动物或成对物品类量词。"}, {"text": "我们这一本邻里很热闹。", "explanation": "这里应该用〈群〉。〈邻里〉指一群邻居，应用集体量词〈群〉，不能用书册类量词。"}, {"text": "我们这一张邻里很热闹。", "explanation": "这里应该用〈群〉。〈邻里〉指一群邻居，应用集体量词〈群〉，不能用平面物类量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这栋楼的一只邻里关系很融洽。", "corrected_sentence": "我们这栋楼的邻里关系很融洽。", "error_description": "量词误用：“只”用于动物或成对物品中的一个，不能修饰“邻里关系”，应去掉“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老街的一本邻里都很热心。", "corrected_sentence": "老街的一群邻里都很热心。", "error_description": "“邻里”指一群邻居，量词应用集体量词“群”，不能用书册类量词“本”。应改为“一群邻里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73314fce-2485-4994-baef-e3de6e863eea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
