INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物初步形成但尚未完善的状态或最初的模样。", "primary_collocate": null, "pronunciation": "chú xíng", "ipa": "tʂʰu˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "雏形", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市的新机场已经初具雏形。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划只有一个雏形，还要继续改。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子画的这张图已经有了房子的雏形。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过一年的努力，公司的雏形终于出现了。", "target_word": "雏形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说现在只是一个雏形，还没写完。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的雏形是三年前做出来的。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把脑子里的想法写成了方案的雏形。", "target_word": "雏形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的雏形很小，只有几间旧房子。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是机器人的雏形，功能还不多。", "target_word": "雏形", "complexity_tier": "T3", "furigana": "zhè shì jī qì rén de chú xíng, gōng néng hái bù duō.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "雛形", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物初步形成、尚未完善的最初模样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9892029b-aaf9-44ec-a70b-07515791e893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雏形", "is_correct": true, "explanation": "正确。雏形指事物初步形成、尚未完善的样子，与释义相符。"}, {"text": "出行", "is_correct": false, "explanation": "chū（第一声）与 chú（第二声）声调不同，意思是外出、出门旅行。"}, {"text": "图形", "is_correct": false, "explanation": "tú 与 chú 声母不同（t 与 ch），意思是图案或几何形状。"}, {"text": "除名", "is_correct": false, "explanation": "míng 与 xíng 声母不同（m 与 x），意思是把名字从名单上去掉。"}], "explanations": {"雏形": "正确。雏形指事物初步形成、尚未完善的样子，与释义相符。", "出行": "chū（第一声）与 chú（第二声）声调不同，意思是外出、出门旅行。", "图形": "tú 与 chú 声母不同（t 与 ch），意思是图案或几何形状。", "除名": "míng 与 xíng 声母不同（m 与 x），意思是把名字从名单上去掉。"}, "sentence_index": null, "correct_answer": "雏形"}, "level_3": {"options": [{"text": "雏形", "is_correct": true, "explanation": "正确。雏形指事物初步形成的样子，与“催生出”的萌芽义相合。"}, {"text": "尾声", "is_correct": false, "explanation": "语义：“尾声”指结束的部分，与“催生出”的开端义相反。"}, {"text": "成品", "is_correct": false, "explanation": "搭配：“催生”说萌发出新事物，不能说催生出成品。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：“废墟”指毁坏后的残迹，与“新型”的新生义冲突。"}], "explanations": {"雏形": "正确。雏形指事物初步形成的样子，与“催生出”的萌芽义相合。", "尾声": "语义：“尾声”指结束的部分，与“催生出”的开端义相反。", "成品": "搭配：“催生”说萌发出新事物，不能说催生出成品。", "废墟": "语义：“废墟”指毁坏后的残迹，与“新型”的新生义冲突。"}, "sentence_index": 0, "correct_answer": "雏形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器已经是雏形了，可以直接出售。", "explanation": "这里应该用〈成品〉。雏形指尚未完善的样子，能直接出售的东西要说成品。"}, {"text": "这份报告已经是雏形，可以印刷了。", "explanation": "这里应该用〈定稿〉。雏形指尚未完善的样子，要印刷的报告应说定稿。"}, {"text": "这是一个完整的建筑雏形，可以在展览上展示。", "explanation": "这里应该用〈模型〉。雏形指尚未完善的样子，“完整”的建筑要说模型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雏形", "is_correct": true, "explanation": "正确。雏形指游戏最初的样子，与“三年前做出来的”相合。"}, {"text": "结局", "is_correct": false, "explanation": "搭配：“做出来”说制作出的东西，不能说结局是做出来的。"}, {"text": "墓碑", "is_correct": false, "explanation": "语义：墓碑是纪念死者的石碑，与游戏的开发过程毫不相关。"}, {"text": "句号", "is_correct": false, "explanation": "语义：句号是标点符号，不是可以做出来的东西，与游戏无关。"}], "explanations": {"雏形": "正确。雏形指游戏最初的样子，与“三年前做出来的”相合。", "结局": "搭配：“做出来”说制作出的东西，不能说结局是做出来的。", "墓碑": "语义：墓碑是纪念死者的石碑，与游戏的开发过程毫不相关。", "句号": "语义：句号是标点符号，不是可以做出来的东西，与游戏无关。"}, "sentence_index": 6, "correct_answer": "雏形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个雏形已经上市了，大家都在买。", "explanation": "这里应该用〈产品〉。雏形指尚未完善的样子，已经上市的东西不能叫雏形。"}, {"text": "这座大楼已经是雏形了，大家都住进去了。", "explanation": "这里应该用〈竣工〉。雏形指尚未完善的样子，大楼已经有人入住时不能说是雏形。"}, {"text": "他的雏形获得了金奖，大家都很佩服。", "explanation": "这里应该用〈作品〉。雏形指尚未完善的样子，获奖的完成之作要说作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个新计划有一块雏形，还要继续改。", "corrected_sentence": "这个新计划有一个雏形，还要继续改。", "error_description": "量词错误：“雏形”应该用“个”。“块”用于成块的东西，不能说“一块雏形”，正确的是“一个雏形”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏的一只雏形是三年前做出来的。", "corrected_sentence": "这个游戏的一个雏形是三年前做出来的。", "error_description": "量词错误：“雏形”应该用“个”；“只”用于动物或成对的东西，不能说“一只雏形”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
