INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "村民代表是指由村民选举产生，代表村民参与村务管理、表达村民意愿的人。", "primary_collocate": null, "pronunciation": "cūn mín dài biǎo", "ipa": "tsʰwən˥ min˧˥ taɪ̯˥˩ piɑʊ̯˨˩˦", "syllable_count": 4, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "村民代表", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "村民代表由全村人投票选出来。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表在会上说出了大家的想法。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位村民代表每个月都去村委会开会。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里要修路，村民代表先去看了地方。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表把大家的意见交给了村长。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全村人投票选出了新的村民代表。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了三年村民代表，帮村里解决了不少问题。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，村民代表先听了邻居们的意见。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表要向村民说明村里的钱怎么用。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位村民代表", "label": "量词"}, {"form": "村民代表大会", "label": "复合"}], "register": "中性", "sense_fingerprint": "由村民选举产生、参与村务管理并表达村民意愿的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9892029b-aaf9-44ec-a70b-07515791e893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村民代表", "is_correct": true, "explanation": "正确：村民代表能依据本村的生态数据与法律条文，在听证会上代表村民提出意见。"}, {"text": "伐木公司", "is_correct": false, "explanation": "语义：伐木公司是砍伐方，不会在听证会上反对自己的砍伐计划。"}, {"text": "小孩子", "is_correct": false, "explanation": "语域：“小孩子”是口语，与听证会、法律条文等正式语境不合。"}, {"text": "外地商人", "is_correct": false, "explanation": "语义：外地商人没有本村长期积累的生态数据，也不代表村民的意愿。"}], "explanations": {"村民代表": "正确：村民代表能依据本村的生态数据与法律条文，在听证会上代表村民提出意见。", "伐木公司": "语义：伐木公司是砍伐方，不会在听证会上反对自己的砍伐计划。", "小孩子": "语域：“小孩子”是口语，与听证会、法律条文等正式语境不合。", "外地商人": "语义：外地商人没有本村长期积累的生态数据，也不代表村民的意愿。"}, "sentence_index": 0, "correct_answer": "村民代表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村民代表代表公司回答记者的问题。", "explanation": "这里应该用〈发言人〉。发言人代表机构对外发言；村民代表代表的是村民的意愿，不代表公司。"}, {"text": "村民代表负责管理全班的同学。", "explanation": "这里应该用〈班长〉。班长管理班级事务；村民代表是村民选出来表达意愿的人，不管理班级。"}, {"text": "村民代表负责把包裹送到家门口。", "explanation": "这里应该用〈快递员〉。快递员负责送件；村民代表的职责是表达村民意愿，不负责送包裹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村民代表", "is_correct": true, "explanation": "正确：全村人投票选出的是担任村务代表的人，村民代表与句意相合。"}, {"text": "村规", "is_correct": false, "explanation": "语义：投票选出的是人，村规是规章，不能被选出来担任职务。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“选出”的对象应是人或职务，不说“选出木头”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能经投票选出来担任职务。"}], "explanations": {"村民代表": "正确：全村人投票选出的是担任村务代表的人，村民代表与句意相合。", "村规": "语义：投票选出的是人，村规是规章，不能被选出来担任职务。", "木头": "搭配：“选出”的对象应是人或职务，不说“选出木头”。", "桌子": "语义：桌子不能经投票选出来担任职务。"}, "sentence_index": 6, "correct_answer": "村民代表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村民代表负责治疗病人。", "explanation": "这里应该用〈医生〉。医生负责诊治病人；村民代表是表达村民意愿的人，不负责治疗。"}, {"text": "村民代表负责做饭。", "explanation": "这里应该用〈厨师〉。厨师负责烹饪；村民代表的职责是表达村民意愿，不负责做饭。"}, {"text": "村民代表负责教学生。", "explanation": "这里应该用〈老师〉。老师负责教学；村民代表不负责教育学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村推选了两只村民代表。", "corrected_sentence": "我们村推选了两位村民代表。", "error_description": "量词错误：村民代表指人，应用“位”或“个”，“只”用于动物或小物件。错误形式为“两只村民代表”，正确形式为“两位村民代表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里推选了三村民代表。", "corrected_sentence": "村里推选了三位村民代表。", "error_description": "量词缺失：数词“三”后面必须加量词，指人的“村民代表”应用“位”。错误形式为“三村民代表”，正确形式为“三位村民代表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为听取公众意见或进行法律程序而召开的正式会议。", "primary_collocate": null, "pronunciation": "tīng zhèng huì", "ipa": "tʰiŋ˥ ʈʂɤŋ˥˩ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "听证会", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "市政府将召开听证会，听取居民的意见。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水价要涨，先要开一场听证会。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听证会上，专家和居民都发了言。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场听证会有三十多位市民参加。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院明天公开举行听证会，听双方说明理由。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在听证会上回答了议员的问题。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听证会结束后，政府会公布结果。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想建新工厂，居民要求召开听证会。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者坐在听证会的后排，认真地做记录。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场听证会", "label": "量词"}, {"form": "价格听证会", "label": "复合"}, {"form": "聽證會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "为听取公众意见或进行法律程序而召开的正式会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9892029b-aaf9-44ec-a70b-07515791e893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听证会", "is_correct": true, "explanation": "“听证会”是为听取公众意见而召开的正式会议，可以“在听证会上提出反对意见”，与“依据法律条文”“规划争议”的语境相符。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是喜庆的私人仪式，不是为听取公众意见设立的程序，与防护林砍伐的规划争议不符。"}, {"text": "运动场", "is_correct": false, "explanation": "搭配：“提出有理有据的反对意见”需要议事的场合，“运动场”是体育场地，两者搭配不通。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是娱乐表演，与依据法律条文提出反对意见的语境不符。"}], "explanations": {"听证会": "“听证会”是为听取公众意见而召开的正式会议，可以“在听证会上提出反对意见”，与“依据法律条文”“规划争议”的语境相符。", "婚礼": "语义：婚礼是喜庆的私人仪式，不是为听取公众意见设立的程序，与防护林砍伐的规划争议不符。", "运动场": "搭配：“提出有理有据的反对意见”需要议事的场合，“运动场”是体育场地，两者搭配不通。", "演唱会": "语义：演唱会是娱乐表演，与依据法律条文提出反对意见的语境不符。"}, "sentence_index": 0, "correct_answer": "听证会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们开听证会，大家随便聊聊工作。", "explanation": "这里应该用〈座谈会〉。座谈会可以随意交流，听证会是为听取公众意见、依法召开的正式会议，不能用于随便聊天。"}, {"text": "公司在听证会上表彰了三位优秀员工。", "explanation": "这里应该用〈颁奖典礼〉。颁奖典礼用于授奖、表彰先进，听证会是听取公众意见、依法召开的正式会议，不用于表彰员工。"}, {"text": "听证会上，老师和同学一起讨论论文。", "explanation": "这里应该用〈研讨会〉。研讨会是共同讨论学术问题的场合，听证会是听取公众意见的正式程序，不用于师生讨论论文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听证会", "is_correct": true, "explanation": "“听证会”是正式的听证场合，议员可以在此提出问题，与“回答议员的问题”相符。"}, {"text": "球场", "is_correct": false, "explanation": "搭配：“回答议员的问题”需要议事或质询的场合，“球场”是体育场地，两者搭配不通。"}, {"text": "菜场", "is_correct": false, "explanation": "语义：菜场是买卖蔬菜的地方，与议员质询的语境毫不相干。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“操场”是学校的运动场地，与“回答议员的问题”的正式场合不符。"}], "explanations": {"听证会": "“听证会”是正式的听证场合，议员可以在此提出问题，与“回答议员的问题”相符。", "球场": "搭配：“回答议员的问题”需要议事或质询的场合，“球场”是体育场地，两者搭配不通。", "菜场": "语义：菜场是买卖蔬菜的地方，与议员质询的语境毫不相干。", "操场": "搭配：“操场”是学校的运动场地，与“回答议员的问题”的正式场合不符。"}, "sentence_index": 6, "correct_answer": "听证会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司召开听证会，向员工介绍新的福利政策。", "explanation": "这里应该用〈说明会〉。说明会是单向介绍信息的场合，听证会是听取意见的正式程序，不用于向员工介绍政策。"}, {"text": "听证会上，老师讲解了古代历史。", "explanation": "这里应该用〈讲座〉。讲座由讲者单向讲授，听证会是听取公众意见、依法进行的会议，不能用于老师讲课。"}, {"text": "听证会上，网友们自由讨论热门话题。", "explanation": "这里应该用〈论坛〉。论坛供人自由发表看法，听证会有法定议题和程序，不用于随意讨论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "居民们听证会上提出了反对意见。", "corrected_sentence": "居民们在听证会上提出了反对意见。", "error_description": "介词错误：“听证会”作处所时要用介词“在”引出，应说“在听证会上”，漏掉“在”句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参加了一杯听证会，很有收获。", "corrected_sentence": "他参加了一场听证会，很有收获。", "error_description": "量词错误：听证会是会议，应该用“场”；“杯”多用于饮品，不能说“一杯听证会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说话、写文章有道理也有证据，不是凭空捏造。", "primary_collocate": null, "pronunciation": "yǒu lǐ yǒu jù", "ipa": "joʊ̯˨˩˦ li˨˩˦ joʊ̯˨˩˦ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "有理有据", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的发言有理有据，大家都同意了。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章写得有理有据，很有说服力。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用数字说明问题，说得有理有据。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们写有理有据的作文。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得有理有据，我没有别的意见。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答有理有据，没人说他不对。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲话要有理有据，不能乱说。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师有理有据地说明了自己的看法。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告有理有据，经理很满意。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有理有據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说话或写文章既有道理又有证据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9892029b-aaf9-44ec-a70b-07515791e893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有理有据", "is_correct": true, "explanation": "“有理有据”形容反对意见既有道理又有依据，与“依据长期积累的生态数据与法律条文”相符。"}, {"text": "空洞", "is_correct": false, "explanation": "语义：“空洞”指没有实际内容，与句中“依据生态数据与法律条文”的内容相矛盾。"}, {"text": "情绪化", "is_correct": false, "explanation": "语义：“情绪化”指凭情绪而非事实讲话，与“依据生态数据与法律条文”不符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或形象，不能修饰“反对意见”，两者搭配不通。"}], "explanations": {"有理有据": "“有理有据”形容反对意见既有道理又有依据，与“依据长期积累的生态数据与法律条文”相符。", "空洞": "语义：“空洞”指没有实际内容，与句中“依据生态数据与法律条文”的内容相矛盾。", "情绪化": "语义：“情绪化”指凭情绪而非事实讲话，与“依据生态数据与法律条文”不符。", "高大": "搭配：“高大”形容体型或形象，不能修饰“反对意见”，两者搭配不通。"}, "sentence_index": 0, "correct_answer": "有理有据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没有证据，却有理有据地反驳。", "explanation": "这里应该用〈理直气壮〉。“有理有据”要求说法有根据，此句说“没有证据”，两者矛盾。"}, {"text": "他明明说错了，还有理有据，一点也不心虚。", "explanation": "这里应该用〈振振有词〉。“有理有据”要求说法有根据，此句说“明明说错了”，与之矛盾。"}, {"text": "他有理有据，乱说一气。", "explanation": "这里应该用〈信口开河〉。“有理有据”指说话有根据，与“乱说一气”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有理有据", "is_correct": true, "explanation": "“有理有据”说明回答有道理、有依据，与“没人说他不对”相符。"}, {"text": "荒唐", "is_correct": false, "explanation": "语义：“荒唐”指不合情理，与“没人说他不对”的语境相矛盾。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”形容人或物的体型，不能用来描写回答。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容体型，不能用来形容回答。"}], "explanations": {"有理有据": "“有理有据”说明回答有道理、有依据，与“没人说他不对”相符。", "荒唐": "语义：“荒唐”指不合情理，与“没人说他不对”的语境相矛盾。", "粗壮": "体貌：“粗壮”形容人或物的体型，不能用来描写回答。", "瘦": "体貌：“瘦”形容体型，不能用来形容回答。"}, "sentence_index": 6, "correct_answer": "有理有据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有理有据，却拿不出任何证据。", "explanation": "这里应该用〈夸夸其谈〉。夸夸其谈指说话空泛浮夸，而“有理有据”要求有根据，此句说“拿不出任何证据”，二者矛盾。"}, {"text": "他有理有据，连自己都说不清楚。", "explanation": "这里应该用〈胡说八道〉。胡说八道指随口乱说，与“有理有据”的根据要求相反，此句说“连自己都说不清楚”，两者矛盾。"}, {"text": "他有理有据，根本不讲证据。", "explanation": "这里应该用〈强词夺理〉。强词夺理指硬要为错误辩解，与“有理有据”的要求矛盾，此句说“根本不讲证据”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有理有据的向大家解释了原因。", "corrected_sentence": "他有理有据地向大家解释了原因。", "error_description": "结构助词错误：“有理有据”修饰动词“解释”时要用“地”，应说“有理有据地解释”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲有理有据，大家都服气。", "corrected_sentence": "他讲得有理有据，大家都服气。", "error_description": "补语错误：“讲”后面引出补语“有理有据”时要用“得”，应说“讲得有理有据”。漏掉“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb133f5e-5669-4042-8d69-ea07b91973ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赞成", "is_correct": true, "explanation": "“赞成”表示同意，与“反对”（不赞成）意思相反，是反义词。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“反对”的意思没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中活动，与“反对”没有反义关系。"}, {"text": "记住", "is_correct": false, "explanation": "“记住”指把事情留在记忆中，与“反对”没有反义关系。"}], "correct_answer": "赞成", "explanations": {"赞成": "“赞成”表示同意，与“反对”（不赞成）意思相反，是反义词。", "完成": "“完成”指做完某件事，与“反对”的意思没有反义关系。", "游泳": "“游泳”指在水中活动，与“反对”没有反义关系。", "记住": "“记住”指把事情留在记忆中，与“反对”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支持", "is_correct": true, "explanation": "“支持”表示赞成、拥护，与“反对”（不赞成）意思相反，是反义词。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子考虑问题，与“反对”没有反义关系。"}, {"text": "改变", "is_correct": false, "explanation": "“改变”指使事物变得不同，与“反对”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”指快速移动双腿，与“反对”没有反义关系。"}], "correct_answer": "支持", "explanations": {"支持": "“支持”表示赞成、拥护，与“反对”（不赞成）意思相反，是反义词。", "思考": "“思考”指用脑子考虑问题，与“反对”没有反义关系。", "改变": "“改变”指使事物变得不同，与“反对”没有反义关系。", "跑步": "“跑步”指快速移动双腿，与“反对”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不赞成；不同意。", "primary_collocate": null, "pronunciation": "fǎn duì", "ipa": "fan²¹⁴ tuei⁵¹", "syllable_count": 2, "sentences": [{"text": "我反对他一个人去爬山，太危险了。", "target_word": "反对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸反对我这么晚还出去玩。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都同意，只有小王一个人反对。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈反对过这个计划，后来才同意。", "target_word": "反对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她反对我买这么贵的手机。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这样做不对，我不敢反对。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都反对明天考试。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我举手表示反对，因为我不同意这个办法。", "target_word": "反对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们反对了很久，最后还是同意了。", "target_word": "反对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意还是反对，请大声说出来。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反對", "label": "繁体"}, {"form": "反对了", "label": "体标"}, {"form": "反对过", "label": "体标"}, {"form": "反对者", "label": "复合"}, {"form": "反对票", "label": "复合"}], "register": "中性", "sense_fingerprint": "对某事不赞成、不同意（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反对", "is_correct": true, "explanation": "“反对”指不赞成、不同意。"}, {"text": "面对", "is_correct": false, "explanation": "miàn（第四声）与 fǎn（第三声）声母不同（m/f），意思是正对着、面向。"}, {"text": "分队", "is_correct": false, "explanation": "fēn（第一声）与 fǎn（第三声）韵母不同（en/an），意思是分成的队伍。"}, {"text": "反推", "is_correct": false, "explanation": "tuī（第一声）与 duì（第四声）声母不同（t/d），意思是逆向推算。"}], "explanations": {"反对": "“反对”指不赞成、不同意。", "面对": "miàn（第四声）与 fǎn（第三声）声母不同（m/f），意思是正对着、面向。", "分队": "fēn（第一声）与 fǎn（第三声）韵母不同（en/an），意思是分成的队伍。", "反推": "tuī（第一声）与 duì（第四声）声母不同（t/d），意思是逆向推算。"}, "sentence_index": null, "correct_answer": "反对"}, "level_3": {"options": [{"text": "反对", "is_correct": true, "explanation": "“反对”表示不赞成，与“太危险了”的担心相符。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”表示赞成，与后面“太危险了”的担心矛盾。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”表示劝勉、支持，与“太危险了”的评价矛盾。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是值得称赞的人或事，不能用来评价一件危险的行为。"}], "explanations": {"反对": "“反对”表示不赞成，与“太危险了”的担心相符。", "支持": "语义：“支持”表示赞成，与后面“太危险了”的担心矛盾。", "鼓励": "语义：“鼓励”表示劝勉、支持，与“太危险了”的评价矛盾。", "赞美": "搭配：“赞美”的对象是值得称赞的人或事，不能用来评价一件危险的行为。"}, "sentence_index": 0, "correct_answer": "反对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "光线照到镜面上，会向原来的方向反对回去。", "explanation": "这里应该用〈反射〉。反射指光线遇到镜面等障碍后返回，反对指不赞同，不能用于光线的方向。"}, {"text": "村民向政府反对了这个问题，希望尽快解决。", "explanation": "这里应该用〈反映〉。反映指把情况或意见告诉有关部门，反对只表示不同意，不能用来说明问题。"}, {"text": "这盘蛋糕很好吃，我反对了三块。", "explanation": "这里应该用〈吃〉。反对指不赞同、不同意，不能表示吃掉食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反对", "is_correct": true, "explanation": "“反对”表示不同意明天考试，符合句意。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的宾语应是人或帮助，不能接“考试”。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是对人或来访的表示，用于“考试”语义不通。"}, {"text": "赞扬", "is_correct": false, "explanation": "搭配：“赞扬”的对象是人或成绩，不能用来说“考试”。"}], "explanations": {"反对": "“反对”表示不同意明天考试，符合句意。", "感谢": "搭配：“感谢”的宾语应是人或帮助，不能接“考试”。", "欢迎": "语义：“欢迎”是对人或来访的表示，用于“考试”语义不通。", "赞扬": "搭配：“赞扬”的对象是人或成绩，不能用来说“考试”。"}, "sentence_index": 6, "correct_answer": "反对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "敌人突然发起进攻，我们立刻反对，打退了他们。", "explanation": "这里应该用〈反击〉。反击指对进攻进行还击，反对指不赞同，不能用于战场上的还手。"}, {"text": "听到这个消息，他的反对很快，马上跑去找朋友。", "explanation": "这里应该用〈反应〉。反应指对外界刺激作出的回应，反对指不赞同，不能用来表示回应的快慢。"}, {"text": "他的态度反对无常，让人很难相信。", "explanation": "这里应该用〈反复〉。反复指变化不定，反对指不赞成，不能用来形容态度多变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个新规定让很多人反对很厉害。", "corrected_sentence": "这个新规定让很多人反对得很厉害。", "error_description": "“反对”后接程度补语时要用“得”，应说“反对得很厉害”，不能直接说“反对很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸反对了过我养宠物。", "corrected_sentence": "我爸爸反对过我养宠物。", "error_description": "“过”表示曾经有过的经历，用了“过”就不能再加“了”，应说“反对过”，不说“反对了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
