INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某事表达的不同看法或反对的想法", "primary_collocate": null, "pronunciation": "yì jiàn", "ipa": "i˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "大家对新规定有意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对老板的做法很有意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对晚上不能玩手机有意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居对半夜的噪音提出了意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是有意见，现在就说出来。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个安排没有意见，可以。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人对服务态度有很多意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们对考试时间有意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当面向经理提意见，说太累了。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工对加班有意见，不愿意留下。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "意见箱", "label": "复合"}, {"form": "意見", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对某事不满、不同意而持有的异议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见 yì jiàn：对某事的不满或不同看法，是本题正确答案。"}, {"text": "一件", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一个物件。"}, {"text": "一键", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一个按键，如“一键启动”。"}, {"text": "一间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，“一”读 yì，意思是一个房间。"}, {"text": "器件", "is_correct": false, "explanation": "qì 与 yì 声母不同（qì 有声母 q，yì 没有声母），意思是电子或机械的零部件。"}], "explanations": {"意见": "意见 yì jiàn：对某事的不满或不同看法，是本题正确答案。", "一件": "yí（第二声）与 yì（第四声）声调不同，意思是一个物件。", "一键": "yí（第二声）与 yì（第四声）声调不同，意思是一个按键，如“一键启动”。", "一间": "jiān（第一声）与 jiàn（第四声）声调不同，“一”读 yì，意思是一个房间。", "器件": "qì 与 yì 声母不同（qì 有声母 q，yì 没有声母），意思是电子或机械的零部件。"}, "sentence_index": null, "correct_answer": "意见"}, "level_3": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见：对某事的不同看法或不满，与“有”搭配，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”与对新规定的态度无关，“有房子”句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“有时间”指有空闲，不能说“对新规定有时间”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，与对规定的看法无关，句子不通。"}], "explanations": {"意见": "意见：对某事的不同看法或不满，与“有”搭配，句意通顺。", "房子": "语义：“房子”与对新规定的态度无关，“有房子”句意不通。", "时间": "搭配：“有时间”指有空闲，不能说“对新规定有时间”。", "手机": "语义：“手机”是物品，与对规定的看法无关，句子不通。"}, "sentence_index": 0, "correct_answer": "意见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句话的意见我没听懂。", "explanation": "这里应该用〈意思〉。意思指话语的含义，意见指对某事的看法或不满，不能用来说句子的含义。"}, {"text": "这个结果出乎我的意见。", "explanation": "这里应该用〈意料〉。固定说“出乎……的意料”，意见指看法或不满，不能用来表示预料之外。"}, {"text": "他昨天在路上出了意见，幸好没有受伤。", "explanation": "这里应该用〈意外〉。出意外指发生了事故，意见指对某事的看法或不满，不能用来描述事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13553, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见 yì jiàn：对某事的不满或不同看法，是本题正确答案。"}, {"text": "一箭", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一支箭，如“一箭双雕”。"}, {"text": "一见", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是看一眼，如“一见如故”。"}, {"text": "寄件", "is_correct": false, "explanation": "jì 与 yì 声母不同（jì 有声母 j，yì 没有声母），寄件指寄送物件。"}, {"text": "一剑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一次剑击，如“一剑封喉”。"}], "explanations": {"意见": "意见 yì jiàn：对某事的不满或不同看法，是本题正确答案。", "一箭": "yí（第二声）与 yì（第四声）声调不同，意思是一支箭，如“一箭双雕”。", "一见": "yí（第二声）与 yì（第四声）声调不同，意思是看一眼，如“一见如故”。", "寄件": "jì 与 yì 声母不同（jì 有声母 j，yì 没有声母），寄件指寄送物件。", "一剑": "yí（第二声）与 yì（第四声）声调不同，意思是一次剑击，如“一剑封喉”。"}, "sentence_index": null, "correct_answer": "意见"}, "level_3": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见：对某事的不满或不同看法，与“有很多”搭配，句意通顺。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”与对服务态度的看法无关，“有很多房间”句意不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能用来表示客人对服务态度的看法，句子不通。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”指体力，不说“对服务态度有很多力气”。"}], "explanations": {"意见": "意见：对某事的不满或不同看法，与“有很多”搭配，句意通顺。", "房间": "语义：“房间”与对服务态度的看法无关，“有很多房间”句意不通。", "苹果": "语义：“苹果”是水果，不能用来表示客人对服务态度的看法，句子不通。", "力气": "搭配：“力气”指体力，不说“对服务态度有很多力气”。"}, "sentence_index": 6, "correct_answer": "意见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革的意见很深远，影响了很多人。", "explanation": "这里应该用〈意义〉。意义指事情的重要价值，意见指对某事的看法或不满，不能用来形容改革的影响。"}, {"text": "这首诗的意见很美，读起来很感人。", "explanation": "这里应该用〈意境〉。意境指作品中的境界和情调，意见指看法或不满，不能用来形容诗的境界。"}, {"text": "他有很强的意见，所以每天都早起学习。", "explanation": "这里应该用〈意愿〉。意愿指想做某事的心愿，意见指看法或不满，不能用来表示想学习的心愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个安排有一只意见，想当面说。", "corrected_sentence": "他对这个安排有一条意见，想当面说。", "error_description": "量词错误：“意见”应用量词“条”计数，“只”多用于动物或成对器官，不能用来数意见。应改为“一条意见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家向这个安排有意见，不太满意。", "corrected_sentence": "大家对这个安排有意见，不太满意。", "error_description": "介词错误：“有意见”前的对象要用介词“对”，“向”表示动作的方向，不能说“向……有意见”，应改为“对这个安排有意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
