INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指各种组织中最直接与群众接触、开展具体工作的一层，如基层单位、基层干部。", "primary_collocate": null, "pronunciation": "jī céng", "ipa": "tɕi⁵⁵ tsʰəŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这表明，基层环保实践正逐步演进为公民参与社会治理的有效路径。", "target_word": "基层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他毕业后去基层工作了两年。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生一直在基层为农民看病。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基层干部每天都要和村民打交道。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要多听基层的声音。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人愿意到基层去锻炼。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基层单位的工作很忙，但很有意义。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从基层做起，一步一步当上了经理。", "target_word": "基层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些政策要真正落实到基层。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在基层待过十年，很了解老百姓的生活。", "target_word": "基层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基層", "label": "繁体"}, {"form": "基层干部", "label": "复合"}, {"form": "基层单位", "label": "复合"}, {"form": "基层组织", "label": "复合"}], "register": "中性", "sense_fingerprint": "组织中直接接触群众、做具体工作的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”指组织中直接接触群众、开展具体工作的一层。"}, {"text": "几层", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是几个楼层、几层。"}, {"text": "集成", "is_correct": false, "explanation": "jí（第二声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是把各部分合在一起。"}, {"text": "几成", "is_correct": false, "explanation": "jǐ（第三声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是几成、几分之几。"}], "explanations": {"基层": "“基层”指组织中直接接触群众、开展具体工作的一层。", "几层": "jǐ（第三声）与 jī（第一声）声调不同，意思是几个楼层、几层。", "集成": "jí（第二声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是把各部分合在一起。", "几成": "jǐ（第三声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是几成、几分之几。"}, "sentence_index": null, "correct_answer": "基层"}, "level_3": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”修饰“环保实践”，指在最基层直接开展的实践，与句意相符。"}, {"text": "理论", "is_correct": false, "explanation": "语义：“理论”指抽象学说，与“实践”相对，不能修饰“环保实践”。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球与环保实践无关，不能修饰“实践”。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“书本”不能修饰“实践”，说“书本环保实践”搭配不当。"}], "explanations": {"基层": "“基层”修饰“环保实践”，指在最基层直接开展的实践，与句意相符。", "理论": "语义：“理论”指抽象学说，与“实践”相对，不能修饰“环保实践”。", "足球": "语义：足球与环保实践无关，不能修饰“实践”。", "书本": "搭配：“书本”不能修饰“实践”，说“书本环保实践”搭配不当。"}, "sentence_index": 0, "correct_answer": "基层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的英语基层很好。", "explanation": "这里应该用〈基础〉。基础指事物的根基，基层指组织中直接接触群众的一层。"}, {"text": "他明白了做人的基层道理。", "explanation": "这里应该用〈基本〉。基本指根本、主要，基层指组织中直接接触群众的一层。"}, {"text": "我们的训练基层在山里，条件很好。", "explanation": "这里应该用〈基地〉。基地指进行某项活动的场所，基层指组织中的一层，不能表示训练场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”指组织中直接接触群众的一层，修饰“单位”符合句意。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是组织机构，不能作为“单位”的修饰语，句意不通。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：“植物”不能修饰“单位”（指机构），搭配不当。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是组织机构，“动物单位”无法指代工作单位，句意不通。"}], "explanations": {"基层": "“基层”指组织中直接接触群众的一层，修饰“单位”符合句意。", "水果": "语义：水果不是组织机构，不能作为“单位”的修饰语，句意不通。", "植物": "搭配：“植物”不能修饰“单位”（指机构），搭配不当。", "动物": "语义：动物不是组织机构，“动物单位”无法指代工作单位，句意不通。"}, "sentence_index": 6, "correct_answer": "基层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们成立了一个教育基层，帮助贫困学生。", "explanation": "这里应该用〈基金〉。基金指为某种用途聚集的资金，基层指组织中直接接触群众的一层。"}, {"text": "这个基层决定了孩子的眼睛颜色。", "explanation": "这里应该用〈基因〉。基因指决定生物遗传性状的单位，基层指组织中的一层。"}, {"text": "诚信是做人的基层。", "explanation": "这里应该用〈基石〉。基石指建筑的基础，比喻根本，基层指组织中直接接触群众的一层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她毕业后先基层锻炼了三年。", "corrected_sentence": "她毕业后先在基层锻炼了三年。", "error_description": "“基层”作处所时要用介词“在”引出，应说“在基层锻炼”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县的每个村都有一把基层组织。", "corrected_sentence": "这个县的每个村都有一个基层组织。", "error_description": "量词“把”用于有柄的器具，不能用于组织，应说“一个基层组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物种是生物分类的基本单位，指一群形态相似、能相互交配并产生可育后代的生物个体。", "primary_collocate": null, "pronunciation": "wù zhǒng", "ipa": "u˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "从生态学视角审视，该项目尤为重视物种配置的科学性。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "生物多样性的维系并非仅关乎物种数量的多寡，更在于物种间相互依存关系的稳健性。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "然而，当前全球平均每三年就有一种野生蜂类被列为濒危物种，这一速度是自然灭绝率的数百倍。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个岛上有许多珍贵的物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新物种的发现让科学家很高兴。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外来物种可能会伤害本地的动物。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个物种都有自己的生活方式。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护濒危物种需要大家一起努力。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家给这个新物种起了名字。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "物種", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物种：生物学中分类的基本单位，能相互交配并产生可育后代的一群生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。物种读作 wù zhǒng，指生物分类的基本单位。"}, {"text": "五种", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，“五种”意思是五类，不是物种。"}, {"text": "物证", "is_correct": false, "explanation": "zhèng（第四声）与 zhǒng（第三声）韵母和声调都不同，“物证”指可作证据的实物。"}, {"text": "物重", "is_correct": false, "explanation": "zhòng（第四声）与 zhǒng（第三声）声调不同，“物重”指物体的重量，不是物种。"}], "explanations": {"物种": "正确。物种读作 wù zhǒng，指生物分类的基本单位。", "五种": "wǔ（第三声）与 wù（第四声）声调不同，“五种”意思是五类，不是物种。", "物证": "zhèng（第四声）与 zhǒng（第三声）韵母和声调都不同，“物证”指可作证据的实物。", "物重": "zhòng（第四声）与 zhǒng（第三声）声调不同，“物重”指物体的重量，不是物种。"}, "sentence_index": null, "correct_answer": "物种"}, "level_3": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。“物种配置”指生物物种的安排，与“生态学视角”相合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑配置”指计算机硬件，与句中的“生态学视角”不符。"}, {"text": "东西", "is_correct": false, "explanation": "语域：“东西”是口语泛称，与句中的书面语体不合。"}, {"text": "单词", "is_correct": false, "explanation": "搭配：“配置”多用于人员、资源、设备，不说“单词配置”。"}], "explanations": {"物种": "正确。“物种配置”指生物物种的安排，与“生态学视角”相合。", "电脑": "语义：“电脑配置”指计算机硬件，与句中的“生态学视角”不符。", "东西": "语域：“东西”是口语泛称，与句中的书面语体不合。", "单词": "搭配：“配置”多用于人员、资源、设备，不说“单词配置”。"}, "sentence_index": 0, "correct_answer": "物种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗是一个很纯的物种。", "explanation": "这里应该用〈品种〉。物种是生物学分类单位，同一物种内不同类型叫品种，狗的纯不纯指品种。"}, {"text": "这家商店的商品物种很多。", "explanation": "这里应该用〈种类〉。物种只用于生物学分类，不能用来说商品的种类。"}, {"text": "超市里摆满了各种物种。", "explanation": "这里应该用〈物品〉。物种只用于生物分类，不能指超市里摆的商品，应说物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。“外来物种”指从外地或外国引入的生物，能伤害本地动物。"}, {"text": "资金", "is_correct": false, "explanation": "语义：资金是金钱，不会伤害动物，与句意不符。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流工具，不会伤害动物，与句意不符。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍是文字载体，不会伤害动物，“外来书籍伤害本地动物”与句意不符。"}], "explanations": {"物种": "正确。“外来物种”指从外地或外国引入的生物，能伤害本地动物。", "资金": "语义：资金是金钱，不会伤害动物，与句意不符。", "语言": "语义：语言是交流工具，不会伤害动物，与句意不符。", "书籍": "语义：书籍是文字载体，不会伤害动物，“外来书籍伤害本地动物”与句意不符。"}, "sentence_index": 6, "correct_answer": "物种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影属于喜剧物种。", "explanation": "这里应该用〈类型〉。物种只用于生物分类，不能指电影的类型。"}, {"text": "最近物种上涨了很多。", "explanation": "这里应该用〈物价〉。物种是生物分类单位，不能说价格上涨，应说物价。"}, {"text": "这种金属是一种稀有的物种。", "explanation": "这里应该用〈物质〉。物种只指生物的分类，金属等非生物不属于物种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片森林里发现了三只新物种。", "corrected_sentence": "这片森林里发现了三个新物种。", "error_description": "量词错误：“物种”应搭配“个”或“种”，“只”用于单个动物，不能用来数物种类别。正确说法：三个新物种。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书里读到了一条新物种。", "corrected_sentence": "我在书里读到了一个新物种。", "error_description": "量词错误：“物种”应搭配“个”或“种”，“条”用于细长的东西，不能修饰物种。正确说法：一个新物种。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
