INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13557, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "按一定的要求安排、搭配；也指这种搭配的方式。", "primary_collocate": null, "pronunciation": "pèi zhì", "ipa": "pʰei⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "从生态学视角审视，该项目尤为重视物种配置的科学性。", "target_word": "配置", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "公司重新配置了人员，工作更有效率。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的家具配置得很合理。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要合理配置老师和教室。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的资源配置能让每个人都用得上。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们根据学生的水平合理配置师资力量。", "target_word": "配置", "complexity_tier": "T3", "furigana": "tā men gēn jù xué shēng de shuǐ píng hé lǐ pèi zhì shī zī lì liàng", "sentence_source": "generated"}, {"text": "球队的人员配置很好，进攻防守都不错。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院会根据病人数量合理配置医生。", "target_word": "配置", "complexity_tier": "T3", "furigana": "yī yuàn huì gēn jù bìng rén shù liàng hé lǐ pèi zhì yī shēng", "sentence_source": "generated"}, {"text": "这个花园的植物配置很有层次。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理正在为各部门合理配置人员。", "target_word": "配置", "complexity_tier": "T3", "furigana": "jīng lǐ zhèng zài wèi gè bù mén hé lǐ pèi zhì rén yuán", "sentence_source": "generated"}], "morphological_forms": [{"form": "配置了", "label": "体标"}, {"form": "配置过", "label": "体标"}, {"form": "重新配置", "label": "复合"}, {"form": "资源配置", "label": "复合"}], "register": "中性", "sense_fingerprint": "按要求安排、搭配人员或资源，也指搭配方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13557, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案，pèi zhì，意思是按一定要求安排、搭配。"}, {"text": "培植", "is_correct": false, "explanation": "培植（péi zhí）与配置（pèi zhì）两个音节的声调都不同，意思是培育栽培植物。"}, {"text": "日志", "is_correct": false, "explanation": "日志（rì zhì）与配置（pèi zhì）声母不同（r 与 p），意思是按日记录的本子。"}, {"text": "皮质", "is_correct": false, "explanation": "皮质（pí zhì）与配置（pèi zhì）韵母和声调都不同，意思是皮层的物质。"}], "explanations": {"配置": "正确答案，pèi zhì，意思是按一定要求安排、搭配。", "培植": "培植（péi zhí）与配置（pèi zhì）两个音节的声调都不同，意思是培育栽培植物。", "日志": "日志（rì zhì）与配置（pèi zhì）声母不同（r 与 p），意思是按日记录的本子。", "皮质": "皮质（pí zhì）与配置（pèi zhì）韵母和声调都不同，意思是皮层的物质。"}, "sentence_index": null, "correct_answer": "配置"}, "level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案。“配置”在此指物种的搭配安排，与“科学性”搭配通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能用来说物种的安排。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是歌唱的作品，与物种的安排无关。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”多用于房屋，不能用于物种。"}], "explanations": {"配置": "正确答案。“配置”在此指物种的搭配安排，与“科学性”搭配通顺。", "价格": "语义：“价格”指钱数，不能用来说物种的安排。", "歌曲": "语义：“歌曲”是歌唱的作品，与物种的安排无关。", "装修": "搭配：“装修”多用于房屋，不能用于物种。"}, "sentence_index": 0, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板配置了一次出差。", "explanation": "这里应该用〈安排〉。配置指按要求组合设备、人员等，不用于具体的日程或活动。"}, {"text": "他配置了一份报告。", "explanation": "这里应该用〈撰写〉。配置指组合设备或人员，不用于写作文件。"}, {"text": "妈妈在厨房里配置了一杯蜂蜜水。", "explanation": "这里应该用〈调制〉。配置指按要求安排、组合设备或人员，不用于调制饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案。“配置”指人员的合理安排，与“人员”搭配通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是人员的属性，“球队的人员价格很好”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说事物的色彩，不能用来评价人员。"}, {"text": "酱油", "is_correct": false, "explanation": "语义：“酱油”是调味品，与球队的人员无关。"}], "explanations": {"配置": "正确答案。“配置”指人员的合理安排，与“人员”搭配通顺。", "价格": "语义：“价格”不是人员的属性，“球队的人员价格很好”说不通。", "颜色": "搭配：“颜色”说事物的色彩，不能用来评价人员。", "酱油": "语义：“酱油”是调味品，与球队的人员无关。"}, "sentence_index": 6, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧团配置了一场话剧。", "explanation": "这里应该用〈上演〉。配置指安排设备或人员，不用于组织演出活动。"}, {"text": "学校配置了很多新学生。", "explanation": "这里应该用〈招收〉。配置不用于录取、招收学生。"}, {"text": "译员配置了这篇文章。", "explanation": "这里应该用〈翻译〉。配置不表示语言之间的转换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校给每间教室配置了一投影仪。", "corrected_sentence": "学校给每间教室配置了一台投影仪。", "error_description": "“投影仪”前用“一”时要带量词“台”，应说“一台投影仪”，不能说“一投影仪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些机器已经配置了好。", "corrected_sentence": "这些机器已经配置好了。", "error_description": "结果补语“好”应紧跟动词，说“配置好了”；“配置了好”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
