INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13559, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指抛弃、扔掉不好的或没用的东西。", "primary_collocate": null, "pronunciation": "bìng qì", "ipa": "piŋ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "摒弃了过去大面积单一树种造林的老办法，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该摒弃旧的想法。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他决定摒弃那些不好的习惯。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言要摒弃怕出错的心理。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司摒弃了过时的管理方法。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都摒弃偏见，认真听她说话。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望我们摒弃抄作业的坏习惯。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂摒弃了落后的做法。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想进步，就要摒弃骄傲自满的态度。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摒弃了所有的成见，重新认识了邻居。", "target_word": "摒弃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摒弃了", "label": "体标"}, {"form": "摒弃过", "label": "体标"}, {"form": "摒棄", "label": "繁体"}], "register": "书面", "sense_fingerprint": "抛弃不好的、没用的观念或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9700a-6e7f-419a-8baf-8a5692ef0729') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13559, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摒弃", "is_correct": true, "explanation": "摒弃 bìng qì：抛弃不好的观念或做法，是正确答案。"}, {"text": "兵器", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是兵器、武器。"}, {"text": "病历", "is_correct": false, "explanation": "lì 与 qì 声母不同（l 与 q），意思是病人的诊疗记录。"}, {"text": "病句", "is_correct": false, "explanation": "jù 与 qì 声母不同（j 与 q），意思是有语法或用词错误的句子。"}], "explanations": {"摒弃": "摒弃 bìng qì：抛弃不好的观念或做法，是正确答案。", "兵器": "bīng（第一声）与 bìng（第四声）声调不同，意思是兵器、武器。", "病历": "lì 与 qì 声母不同（l 与 q），意思是病人的诊疗记录。", "病句": "jù 与 qì 声母不同（j 与 q），意思是有语法或用词错误的句子。"}, "sentence_index": null, "correct_answer": "摒弃"}, "level_3": {"options": [{"text": "摒弃", "is_correct": true, "explanation": "摒弃：抛弃过去的老办法，指不再沿用，与后文的新做法相合。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」指栽种植物，与舍弃旧办法的意思不符。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：「修建」多用于建筑、道路，不能搭配「老办法」。"}, {"text": "购买", "is_correct": false, "explanation": "语义：办法不是可以购买的物品，与句意不符。"}], "explanations": {"摒弃": "摒弃：抛弃过去的老办法，指不再沿用，与后文的新做法相合。", "种植": "语义：「种植」指栽种植物，与舍弃旧办法的意思不符。", "修建": "搭配：「修建」多用于建筑、道路，不能搭配「老办法」。", "购买": "语义：办法不是可以购买的物品，与句意不符。"}, "sentence_index": 0, "correct_answer": "摒弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摒弃了家人，独自去了外地。", "explanation": "这里应该用〈抛弃〉。摒弃用于应当去掉的不良观念或做法，不能用于人，对人要用抛弃。"}, {"text": "这么好的机会，他却决定摒弃。", "explanation": "这里应该用〈放弃〉。摒弃用于应当去掉的不良观念，好的机会不能摒弃，应说放弃。"}, {"text": "我们要摒弃艰苦奋斗的精神。", "explanation": "这里应该用〈发扬〉。摒弃指扔掉不好或没用的东西，艰苦奋斗的好精神要发扬，不能摒弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摒弃", "is_correct": true, "explanation": "摒弃：去掉抄作业的坏习惯，与老师的希望相合，符合句意。"}, {"text": "学习", "is_correct": false, "explanation": "语义：“学习”指获取知识或技能，不能指坏习惯，与老师希望去掉坏习惯的意思相反。"}, {"text": "保持", "is_correct": false, "explanation": "语义：“保持”坏习惯与老师希望去掉它的意思相反，句意不通。"}, {"text": "发扬", "is_correct": false, "explanation": "搭配：“发扬”多用于优良传统、作风，不能与“坏习惯”搭配。"}], "explanations": {"摒弃": "摒弃：去掉抄作业的坏习惯，与老师的希望相合，符合句意。", "学习": "语义：“学习”指获取知识或技能，不能指坏习惯，与老师希望去掉坏习惯的意思相反。", "保持": "语义：“保持”坏习惯与老师希望去掉它的意思相反，句意不通。", "发扬": "搭配：“发扬”多用于优良传统、作风，不能与“坏习惯”搭配。"}, "sentence_index": 6, "correct_answer": "摒弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摒弃了这段漫长的时光。", "explanation": "这里应该用〈度过〉。摒弃用于应当去掉的不良观念，时光不能被摒弃，应说度过。"}, {"text": "他摒弃了多年的老朋友。", "explanation": "这里应该用〈疏远〉。摒弃不用于人，对老朋友要说疏远。"}, {"text": "我们要摒弃集体的团结。", "explanation": "这里应该用〈维护〉。摒弃用于应当去掉的东西，团结是好的，要说维护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该摒弃了坏习惯。", "corrected_sentence": "我们应该摒弃坏习惯。", "error_description": "“了”表示动作已经完成或发生了变化，不能放在“应该”后面的动作前。应说“应该摒弃”，不说“应该摒弃了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那些坏习惯摒弃干干净净。", "corrected_sentence": "他把那些坏习惯摒弃得干干净净。", "error_description": "表示结果的补语前要加“得”。应说“摒弃得干干净净”，省略“得”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
