INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从错误或失败中得到的经验或批评，用来提醒自己以后不再犯同样的错误。", "primary_collocate": null, "pronunciation": "jiào xùn", "ipa": "tɕjɑʊ˥˩ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "这次失败给了我一个很大的教训。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要记住这个教训，以后别再迟到。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从错误中学到了教训。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丢了钱包以后，我才明白这个教训。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个教训让公司更小心了。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们应该吸取教训。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史给我们留下了很多教训。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次事故的教训，大家都没有忘记。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用自己的经历告诉我们一个教训：别太相信陌生人。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好是个教训，下次要早点复习。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "教訓", "label": "繁体"}], "register": "通用", "sense_fingerprint": "从错误或失败中得到的、提醒自己的经验", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教训", "is_correct": true, "explanation": "教训 jiàoxùn：意思是从失败中得到的经验，与听到的读音一致。"}, {"text": "校训", "is_correct": false, "explanation": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的校训，不是从失败中得来的经验。"}, {"text": "驾训", "is_correct": false, "explanation": "jià 与 jiào 韵母不同（a 与 ao），意思是驾驶培训。"}, {"text": "校讯", "is_correct": false, "explanation": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的通知。"}], "explanations": {"教训": "教训 jiàoxùn：意思是从失败中得到的经验，与听到的读音一致。", "校训": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的校训，不是从失败中得来的经验。", "驾训": "jià 与 jiào 韵母不同（a 与 ao），意思是驾驶培训。", "校讯": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的通知。"}, "sentence_index": null, "correct_answer": "教训"}, "level_3": {"options": [{"text": "教训", "is_correct": true, "explanation": "“教训”指从失败中得到的经验，与“这次失败”的语境相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：奖励是对成绩的好处，与“失败”的语境相矛盾。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：荣誉是因成绩得来的光彩，和“失败”放在一起说不通。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“收入”指钱财来源，与“失败”的语境不搭配。"}], "explanations": {"教训": "“教训”指从失败中得到的经验，与“这次失败”的语境相符。", "奖励": "语义：奖励是对成绩的好处，与“失败”的语境相矛盾。", "荣誉": "语义：荣誉是因成绩得来的光彩，和“失败”放在一起说不通。", "收入": "搭配：“收入”指钱财来源，与“失败”的语境不搭配。"}, "sentence_index": 0, "correct_answer": "教训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一个很好笑的教训，大家都笑个不停。", "explanation": "这里应该用〈笑话〉。笑话是让人发笑的故事；教训是从错误中得到的经验，不能用“好笑”来形容。"}, {"text": "孩子们拿着新教训，玩得很开心。", "explanation": "这里应该用〈玩具〉。玩具是可以拿在手里玩的具体东西；教训是从错误中得到的经验，不能拿着玩。"}, {"text": "我家的教训坏了，要送去修。", "explanation": "这里应该用〈电脑〉。电脑是可以送去修的机器；教训是从错误中得到的经验，不能说“坏了”或“送去修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教训", "is_correct": true, "explanation": "“留下了很多教训”指历史给人留下的经验与提醒，与语境相符。"}, {"text": "零食", "is_correct": false, "explanation": "语义：零食是吃的东西，不是历史留下的经验。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“留下”多指遗产、痕迹，不能说历史留下冰箱。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，与历史留下的经验无关。"}], "explanations": {"教训": "“留下了很多教训”指历史给人留下的经验与提醒，与语境相符。", "零食": "语义：零食是吃的东西，不是历史留下的经验。", "冰箱": "搭配：“留下”多指遗产、痕迹，不能说历史留下冰箱。", "饮料": "语义：饮料是喝的东西，与历史留下的经验无关。"}, "sentence_index": 6, "correct_answer": "教训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他犯了一个教训，老师很生气。", "explanation": "这里应该用〈错误〉。犯的是错误，教训是从错误中得来的经验，不能说“犯教训”。"}, {"text": "他在阳光下弹教训，很开心。", "explanation": "这里应该用〈钢琴〉。弹的是乐器，教训是从错误中得来的经验，不能用“弹”。"}, {"text": "这个教训放进了箱子里。", "explanation": "这里应该用〈书〉。书是具体的物品，可以放进箱子；教训是从错误中得来的经验，是抽象的，不能被装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事给大家留下了一位深刻的教训。", "corrected_sentence": "这件事给大家留下了一个深刻的教训。", "error_description": "量词错误：“位”只用于人，不能修饰“教训”，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试给我教训很大，我以后会早点复习。", "corrected_sentence": "这次考试给我的教训很大，我以后会早点复习。", "error_description": "“的”漏掉了。“给我的教训”是定语结构，省略后“给我教训”不成词组，应加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
