INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13563, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指示教导；指点引导。", "primary_collocate": null, "pronunciation": "zhǐ dǎo", "ipa": "ʈʂʐ̩˨˩˦ tau˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师指导我们写作文。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他指导学生做实验。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "王教练指导孩子们练习游泳。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师昨天指导了我的作文。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理指导新同事做这份工作。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你指导一下我画画。", "target_word": "指导", "complexity_tier": "T3", "furigana": "zhǐ dǎo", "sentence_source": "generated"}, {"text": "他指导过很多年轻的歌手。", "target_word": "指导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶指导我怎么做饺子。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家来农村指导农民种树。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导师指导着他完成了论文。", "target_word": "指导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指导了", "label": "体标"}, {"form": "指导过", "label": "体标"}, {"form": "指导着", "label": "体标"}, {"form": "指导员", "label": "复合"}, {"form": "指导老师", "label": "复合"}, {"form": "指導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指点并引导别人学习或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80e8d62d-12a7-44df-af83-f63c701fa43b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13563, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知道", "is_correct": false, "explanation": "zhī dào 与 zhǐ dǎo 两个音节的声调都不同，意思是知道、了解，不是指点引导。"}, {"text": "指导", "is_correct": true, "explanation": "正确答案：指导（zhǐ dǎo），意思是指示教导、指点引导。"}, {"text": "直到", "is_correct": false, "explanation": "zhí dào 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），第二音节也不同，意思是一直到某个时候。"}, {"text": "主导", "is_correct": false, "explanation": "zhǔ dǎo 与 zhǐ dǎo 第一音节韵母不同（ǔ 与 ǐ），意思是居于主要地位、起支配作用。"}, {"text": "执导", "is_correct": false, "explanation": "zhí dǎo 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），意思是担任导演、执导影片。"}], "explanations": {"知道": "zhī dào 与 zhǐ dǎo 两个音节的声调都不同，意思是知道、了解，不是指点引导。", "指导": "正确答案：指导（zhǐ dǎo），意思是指示教导、指点引导。", "直到": "zhí dào 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），第二音节也不同，意思是一直到某个时候。", "主导": "zhǔ dǎo 与 zhǐ dǎo 第一音节韵母不同（ǔ 与 ǐ），意思是居于主要地位、起支配作用。", "执导": "zhí dǎo 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），意思是担任导演、执导影片。"}, "sentence_index": null, "correct_answer": "指导"}, "level_3": {"options": [{"text": "指导", "is_correct": true, "explanation": "正确：“老师指导我们写作文”，指导即指点教导，与“写作文”的学习语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“我们写作文”搭配，“写作文”不能被吃，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“写作文”作宾语，句子不成立。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，与“写作文”的教学场景毫无关系，句子不通。"}], "explanations": {"指导": "正确：“老师指导我们写作文”，指导即指点教导，与“写作文”的学习语境相合。", "吃": "搭配：“吃”不能与“我们写作文”搭配，“写作文”不能被吃，句子不通。", "唱": "搭配：“唱”不能带“写作文”作宾语，句子不成立。", "踢": "语义：“踢”是用脚击打，与“写作文”的教学场景毫无关系，句子不通。"}, "sentence_index": 0, "correct_answer": "指导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人每天指导办公室。", "explanation": "这里应该用〈打扫〉。指导的对象是人或做事的方法，不能指导办公室；清理办公室要用打扫。"}, {"text": "司机每天指导汽车。", "explanation": "这里应该用〈驾驶〉。指导的对象是人或做事的方法，不能指导汽车；操纵汽车要用驾驶。"}, {"text": "交警每天指导早高峰的汽车。", "explanation": "这里应该用〈指挥〉。指导是教人做事，不能用来指使车辆；交警指挥车辆要用“指挥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指导", "is_correct": true, "explanation": "正确：“指导过”表示教导过，“他指导过很多年轻的歌手”成立。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物送食物，“歌手”不能被喂，句子不通。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀斧等击打，不能用来对歌手这样说，句子不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能带“歌手”作宾语表示与人交往，“咬过很多年轻的歌手”不成句。"}], "explanations": {"指导": "正确：“指导过”表示教导过，“他指导过很多年轻的歌手”成立。", "喂": "语义：“喂”指给人或动物送食物，“歌手”不能被喂，句子不通。", "砍": "语义：“砍”是用刀斧等击打，不能用来对歌手这样说，句子不通。", "咬": "搭配：“咬”不能带“歌手”作宾语表示与人交往，“咬过很多年轻的歌手”不成句。"}, "sentence_index": 6, "correct_answer": "指导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生指导了病人的身体。", "explanation": "这里应该用〈检查〉。指导是教人做事，不能用来说对病人身体的检查。"}, {"text": "工人指导了那台坏掉的电脑。", "explanation": "这里应该用〈修理〉。指导的对象是人或做事的方法，不能指导一台机器。"}, {"text": "厨师指导了一桌好菜。", "explanation": "这里应该用〈烧〉。指导是教人做事，不能拿一桌成品菜作宾语；做出一桌菜要用“烧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师很指导我们做实验。", "corrected_sentence": "老师指导我们做实验。", "error_description": "错误：“很”是程度副词，不能修饰动作动词“指导”。正确：“老师指导我们做实验”，“指导”前不加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师指导我了三次。", "corrected_sentence": "老师指导了我三次。", "error_description": "错误：“了”放在了宾语“我”后面。正确：“指导了我三次”，“了”应紧跟动词“指导”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
