INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乔木是指树身高大、主干明显、分枝点高的树木，与灌木相对。", "primary_collocate": null, "pronunciation": "qiáo mù", "ipa": "tɕʰjɑʊ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "摒弃了过去单一树种大规模种植的教训，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公园里最高的乔木有三十米高。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵乔木的树干很粗，两个人才能抱住。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乔木长得高，夏天能给我们遮阴。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有很多乔木，比如松树和杨树。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乔木的主干明显，灌木却没有。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，松树是常见的乔木。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，路边的乔木叶子都黄了。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林的上层是乔木，下层是小草。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟把窝搭在乔木的高处。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "落叶乔木", "label": "复合"}, {"form": "喬木", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树身高大、主干明显的树木，与灌木相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80e8d62d-12a7-44df-af83-f63c701fa43b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乔木", "is_correct": true, "explanation": "正确：乔木是高大的树木，与灌木、草本植物同属植被层次。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不属于植被，与“灌木、草本植物”不是同一类，句子不通。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石不是生物，不能构成植被系统的层次。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：植被系统的组成中列举不能包括汽车，“包含汽车”与语境不搭。"}], "explanations": {"乔木": "正确：乔木是高大的树木，与灌木、草本植物同属植被层次。", "动物": "语义：动物不属于植被，与“灌木、草本植物”不是同一类，句子不通。", "矿石": "语义：矿石不是生物，不能构成植被系统的层次。", "汽车": "搭配：植被系统的组成中列举不能包括汽车，“包含汽车”与语境不搭。"}, "sentence_index": 0, "correct_answer": "乔木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这株乔木只有一尺高，蹲下就能看到它的叶子。", "explanation": "这里应该用〈灌木〉。乔木指树身高大、主干明显的树；只有一尺高、丛生的植物应说灌木。"}, {"text": "这排乔木每天早上都会唱歌。", "explanation": "这里应该用〈鸟〉。乔木是植物，不会唱歌；会唱歌的应说鸟。"}, {"text": "这种乔木会攀着墙向上长。", "explanation": "这里应该用〈藤本植物〉。乔木是直立生长的高大树木，不会攀着墙向上长；攀墙生长的是藤本植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乔木", "is_correct": true, "explanation": "正确：松树是常见的乔木，乔木指高大的树，与松树同类。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：松树是植物而不是鱼，“常见的鱼”与松树的类别不符，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“常见的”后面接的应是事物类别，“颜色”不能作松树所属的类别。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与松树不属于同一类，“松树是常见的乐器”不成立。"}], "explanations": {"乔木": "正确：松树是常见的乔木，乔木指高大的树，与松树同类。", "鱼": "语义：松树是植物而不是鱼，“常见的鱼”与松树的类别不符，句子不通。", "颜色": "搭配：“常见的”后面接的应是事物类别，“颜色”不能作松树所属的类别。", "乐器": "语义：乐器与松树不属于同一类，“松树是常见的乐器”不成立。"}, "sentence_index": 6, "correct_answer": "乔木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乔木很软，摸上去很舒服。", "explanation": "这里应该用〈棉花〉。乔木是高大的树木，不能柔软得让人摸上去很舒服；柔软、摸上去舒服说的是棉花一类的东西。"}, {"text": "花园里开满了乔木。", "explanation": "这里应该用〈鲜花〉。“开满”说的是花，乔木是树，不能这样说。"}, {"text": "这栋乔木有五十层，在城市里特别显眼。", "explanation": "这里应该用〈高楼〉。乔木只指树木，不能用来指建筑物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有一个乔木。", "corrected_sentence": "山上有一棵乔木。", "error_description": "错误：量词“个”不能用于乔木。正确：“一棵乔木”，树木应使用量词“棵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵乔木很很茂盛。", "corrected_sentence": "这棵乔木很茂盛。", "error_description": "错误：副词“很”重复，“很很茂盛”。正确：“这棵乔木很茂盛”，只用一个“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
