INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "低矮的木本植物，没有明显主干，从地面附近就开始分枝。", "primary_collocate": null, "pronunciation": "guàn mù", "ipa": "kwan˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "摒弃了过去单一树种大规模种植的教训，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "路边的灌木只有一米高。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种灌木从地面附近就开始分枝。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的灌木每年春天都要修剪。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小兔子躲在灌木后面。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灌木矮矮的，不像乔木那么高。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园用灌木围成了一道绿色的墙。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，这丛灌木开满了小白花。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上长满了灌木，走路很不方便。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在给马路中间的灌木浇水。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丛", "label": "量词"}, {"form": "灌木丛", "label": "复合"}], "register": "中性", "sense_fingerprint": "低矮、无明显主干、近地面分枝的木本植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80e8d62d-12a7-44df-af83-f63c701fa43b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灌木", "is_correct": true, "explanation": "正确。灌木是低矮、没有明显主干的木本植物，与乔木、草本植物并列为植被层次之一。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是果实，不是植被的层次类型，不能与乔木、草本植物并列。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是植物，不能列入植被系统的组成部分。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：花朵是植物的一部分，不能与乔木、草本植物并列作为植物类型。"}], "explanations": {"灌木": "正确。灌木是低矮、没有明显主干的木本植物，与乔木、草本植物并列为植被层次之一。", "水果": "语义：水果是果实，不是植被的层次类型，不能与乔木、草本植物并列。", "石头": "语义：石头不是植物，不能列入植被系统的组成部分。", "花朵": "搭配：花朵是植物的一部分，不能与乔木、草本植物并列作为植物类型。"}, "sentence_index": 0, "correct_answer": "灌木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子角落里立着一棵灌木，树干笔直，像一根柱子。", "explanation": "这里应该用〈乔木〉。灌木没有明显主干；树干笔直、像柱子一样立着的是乔木。"}, {"text": "灌木的茎很软，冬天容易枯死。", "explanation": "这里应该用〈草本植物〉。灌木的茎木质化、较硬，不会因为一个冬天就枯死；茎柔软、容易枯死是草本植物的特点。"}, {"text": "这棵灌木的树干很粗，要两个人才能抱住。", "explanation": "这里应该用〈乔木〉。灌木没有明显主干，说“树干很粗、要两个人才能抱住”的是有明显主干的乔木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灌木", "is_correct": true, "explanation": "正确。灌木矮矮的，可以用来围成一道绿色的墙。"}, {"text": "红砖", "is_correct": false, "explanation": "体貌：红砖是红色的，与“绿色的墙”的颜色相矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能用来围成墙，句子说的是公园里的围墙。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，不能围成一道墙。"}], "explanations": {"灌木": "正确。灌木矮矮的，可以用来围成一道绿色的墙。", "红砖": "体貌：红砖是红色的，与“绿色的墙”的颜色相矛盾。", "玩具": "语义：玩具不能用来围成墙，句子说的是公园里的围墙。", "空气": "语义：空气看不见、摸不着，不能围成一道墙。"}, "sentence_index": 6, "correct_answer": "灌木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的灌木一节一节的，又直又高，一根分枝也没有。", "explanation": "这里应该用〈竹子〉。竹子有节、直立、不分枝；灌木矮矮的，从地面附近就开始分枝，不能说“一节一节、一根分枝也没有”。"}, {"text": "河里漂着一丛灌木，顺着水流轻轻摇摆。", "explanation": "这里应该用〈水草〉。灌木长在陆地上，不会漂在河里随水摇摆；随水漂动的是水草。"}, {"text": "墙边的灌木中间是空的，细长的茎风一吹就弯下腰。", "explanation": "这里应该用〈芦苇〉。灌木的茎是木质的，不是中空的；中空、细长、风一吹就弯腰的是芦苇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在马路中间种了几丛灌木们。", "corrected_sentence": "工人在马路中间种了几丛灌木。", "error_description": "错在“灌木”后面加了“们”。灌木是植物名词，不能表示复数，应直接说“几丛灌木”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天，山坡上长出了一支灌木。", "corrected_sentence": "春天，山坡上长出了一丛灌木。", "error_description": "错在量词。“灌木”应用量词“丛”，“支”用于细长的杆状物，不能修饰灌木。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
