INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指茎内木质部不发达、木质化细胞较少的植物，茎干通常柔软，一般开花结果后枯死。", "primary_collocate": null, "pronunciation": "cǎo běn zhí wù", "ipa": "tsʰɑʊ˨˩˦ pən˨˩˦ ʈʂɨ˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "摒弃了过去单一树种大规模种植的教训，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "草本植物的茎很软，冬天容易枯死。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数花都是草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草本植物开花结果后就会枯死。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小麦和水稻都是草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上长着各种草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草本植物没有硬硬的树干。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草本植物一年就能长大。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，山坡上的草本植物最先变绿。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们认识了几种草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "多年生草本植物", "label": "复合"}], "register": "中性", "sense_fingerprint": "茎柔软、木质部不发达、开花结果后枯死的植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80e8d62d-12a7-44df-af83-f63c701fa43b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草本植物", "is_correct": true, "explanation": "正确。草本植物是茎柔软、木质部不发达的植物，与乔木、灌木并列为植被的一类。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋不是植物，不属于植被的层次分类。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是果实，不是植被的类型，不能与乔木、灌木并列。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：花朵是植物的一部分，不能与乔木、灌木并列作为植物类型。"}], "explanations": {"草本植物": "正确。草本植物是茎柔软、木质部不发达的植物，与乔木、灌木并列为植被的一类。", "房屋": "语义：房屋不是植物，不属于植被的层次分类。", "水果": "语义：水果是果实，不是植被的类型，不能与乔木、灌木并列。", "花朵": "搭配：花朵是植物的一部分，不能与乔木、灌木并列作为植物类型。"}, "sentence_index": 0, "correct_answer": "草本植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草本植物的茎木质化，冬天也不会枯死。", "explanation": "这里应该用〈木本植物〉。草本植物的茎柔软，开花结果后通常枯死；茎木质化、冬天不枯是木本植物的特点。"}, {"text": "这棵草本植物已经长了几十年，树冠很大。", "explanation": "这里应该用〈乔木〉。草本植物没有木质化的主干和树冠，描述树冠、树龄要用乔木。"}, {"text": "这棵草本植物的枝条又硬又长，每年冬天都要修剪。", "explanation": "这里应该用〈灌木〉。草本植物的茎柔软，不会木质化成硬枝；枝条又硬又长、需要年年修剪的是灌木这类木本植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草本植物", "is_correct": true, "explanation": "正确。草本植物茎柔软，没有硬硬的树干。"}, {"text": "乔木", "is_correct": false, "explanation": "语义：乔木有明显的主干，与“没有硬硬的树干”相矛盾。"}, {"text": "大树", "is_correct": false, "explanation": "体貌：大树的树干粗壮坚硬，与句中“没有硬硬的树干”的描述相反。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是植物，谈不上有没有树干。"}], "explanations": {"草本植物": "正确。草本植物茎柔软，没有硬硬的树干。", "乔木": "语义：乔木有明显的主干，与“没有硬硬的树干”相矛盾。", "大树": "体貌：大树的树干粗壮坚硬，与句中“没有硬硬的树干”的描述相反。", "石头": "语义：石头不是植物，谈不上有没有树干。"}, "sentence_index": 6, "correct_answer": "草本植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池塘里浮着一团绿色的草本植物，没有根，也没有叶子，随水漂来漂去。", "explanation": "这里应该用〈藻类〉。草本植物是有根、有叶子的植物；没有根叶、在水面漂来漂去的是藻类。"}, {"text": "院子中间立着一棵草本植物，树干里有一圈圈的年轮。", "explanation": "这里应该用〈大树〉。草本植物茎内木质部不发达，不会长出明显的年轮；有一圈圈年轮的是大树。"}, {"text": "林子里的烂木头上长出一丛草本植物，伞盖圆圆的，底下有许多菌褶。", "explanation": "这里应该用〈蘑菇〉。蘑菇属于真菌，有伞盖和菌褶；草本植物是有茎有叶的植物，不会长出菌褶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里种着几株草本植物们。", "corrected_sentence": "院子里种着几株草本植物。", "error_description": "错在“草本植物”后面加了“们”。这是植物名词，不能表示复数，应直接说“几株草本植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花园里的那只草本植物开花了。", "corrected_sentence": "花园里的那株草本植物开花了。", "error_description": "错在量词。“草本植物”应用量词“株”，“只”用于动物，不能修饰植物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff28fae2-6baa-4b2d-9466-d3bbd1fd0f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "植被指覆盖在地球表面的植物群落的总称，包括森林、草原、灌木丛等。", "primary_collocate": null, "pronunciation": "zhí bèi", "ipa": "ʈʂɻ̩˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "部分前沿研究指出，建立生态廊道、恢复原生植被、实施精准农业管理以及制定跨区域的授粉保护政策，可能是缓解危机的有效路径。", "target_word": "植被", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "山上的植被很好，空气也很新鲜。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了大雨以后，这里的植被长得更绿了。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林和草原都是重要的植被。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片植被保护着山下的村子。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植被很少，动物也不多。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，河边的植被开始变绿。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们在山坡上种树，是为了恢复植被。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾毁坏了大片植被，要很多年才能长好。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的地方，植被的种类也不一样。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片植被", "label": "量词"}], "register": "中性", "sense_fingerprint": "植被：覆盖地表的植物群落总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植被", "is_correct": true, "explanation": "正确。“恢复原生植被”指恢复自然生长的植物群落，合乎语境。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“原生”多用于自然界的生物或环境，不说“原生家具”。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是人造材料，无法“恢复原生”，与生态语境不符。"}, {"text": "东西", "is_correct": false, "explanation": "语域：“东西”是口语泛称，与句中的书面政策论述不合。"}], "explanations": {"植被": "正确。“恢复原生植被”指恢复自然生长的植物群落，合乎语境。", "家具": "搭配：“原生”多用于自然界的生物或环境，不说“原生家具”。", "钢铁": "语义：钢铁是人造材料，无法“恢复原生”，与生态语境不符。", "东西": "语域：“东西”是口语泛称，与句中的书面政策论述不合。"}, "sentence_index": 0, "correct_answer": "植被"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种植被可以治感冒。", "explanation": "这里应该用〈草药〉。植被指覆盖地面的植物群落，不能用来治病，治感冒的应说草药。"}, {"text": "这树的植被很甜。", "explanation": "这里应该用〈果实〉。植被指植物群落，不是可以吃的果实，“很甜”应指果实。"}, {"text": "草地上的植被在吃草。", "explanation": "这里应该用〈羊〉。植被是植物群落的总称，不会吃草，会吃草的是动物，应说羊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植被", "is_correct": true, "explanation": "正确。“春天来了，河边的植被开始变绿”，植被会随季节变绿。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是人造机械，不会随季节变绿，与句意不符。"}, {"text": "桌椅", "is_correct": false, "explanation": "搭配：“变绿”用于草木等植物，不说桌椅变绿。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与句中的书面叙述不合，且指代物件，不能变绿。"}], "explanations": {"植被": "正确。“春天来了，河边的植被开始变绿”，植被会随季节变绿。", "汽车": "语义：汽车是人造机械，不会随季节变绿，与句意不符。", "桌椅": "搭配：“变绿”用于草木等植物，不说桌椅变绿。", "玩意儿": "语域：“玩意儿”是口语，与句中的书面叙述不合，且指代物件，不能变绿。"}, "sentence_index": 6, "correct_answer": "植被"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民今年收了很多植被。", "explanation": "这里应该用〈粮食〉。植被是植物群落的总称，不是可以收获的农产品，收获的应是粮食。"}, {"text": "花园里开满了植被。", "explanation": "这里应该用〈鲜花〉。“开满”用于花朵，植被是植物群落的总称，不能说开满了植被。"}, {"text": "我们每天都要喝植被。", "explanation": "这里应该用〈水〉。植被不是饮品，不能喝，喝的应是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上有一个茂密的植被。", "corrected_sentence": "山坡上有一片茂密的植被。", "error_description": "量词错误：“植被”是成片的植物群落，应搭配“片”，不用“个”。正确说法：一片茂密的植被。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人们开始恢复这片被烧毁的植被们。", "corrected_sentence": "人们开始恢复这片被烧毁的植被。", "error_description": "词缀错误：“植被”是不可数的植物群落总称，不能加“们”表示复数。正确说法：这片被烧毁的植被。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
