INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13572, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示前后相继，时断时续地进行。", "primary_collocate": null, "pronunciation": "lù xù", "ipa": "lu˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "新书店陆续开门了。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月，学校的新楼会陆续开放。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天，我陆续收到了朋友的信。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花陆续开了。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，村里陆续修了新路。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书是我这几年陆续买的。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，路边的灯陆续亮了。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十月以后，陆续有新游客来到这座小镇。", "target_word": "陆续", "complexity_tier": "T3", "furigana": "shí yuè yǐ hòu， lù xù yǒu xīn yóu kè lái dào zhè zuò xiǎo zhèn。", "sentence_source": "generated"}, {"text": "这个月，商店陆续把新货摆出来了。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停后，街上陆续有了行人。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，事情在一段时间内前后相继、时断时续地发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7220669f-a54a-43ff-a5c1-c20a76c762d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "露宿", "is_correct": false, "explanation": "sù（第四声）与 xù（第四声）的声母不同（s 与 x），其余相同，意思是在户外过夜，与“前后相继”无关。"}, {"text": "陆续", "is_correct": true, "explanation": "正确答案：lù xù，表示前后相继、时断时续地进行。"}, {"text": "路遇", "is_correct": false, "explanation": "yù（第四声）与 xù 的声母不同（零声母 y 与 x），意思是途中偶然碰见。"}, {"text": "芦絮", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇的絮状穗。"}, {"text": "路数", "is_correct": false, "explanation": "shù（第四声）与 xù（第四声）的声母不同（sh 与 x），其余相同，意思是套路、门道。"}], "explanations": {"露宿": "sù（第四声）与 xù（第四声）的声母不同（s 与 x），其余相同，意思是在户外过夜，与“前后相继”无关。", "陆续": "正确答案：lù xù，表示前后相继、时断时续地进行。", "路遇": "yù（第四声）与 xù 的声母不同（零声母 y 与 x），意思是途中偶然碰见。", "芦絮": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇的絮状穗。", "路数": "shù（第四声）与 xù（第四声）的声母不同（sh 与 x），其余相同，意思是套路、门道。"}, "sentence_index": null, "correct_answer": "陆续"}, "level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求施事是人，书店不能亲自开门。"}, {"text": "陆续", "is_correct": true, "explanation": "正确：新书店一家接一家地前后开门，符合“陆续”的含义。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与“开门了”这一次性完成的事相矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与句末“了”的完成语气矛盾。"}], "explanations": {"亲自": "搭配：“亲自”要求施事是人，书店不能亲自开门。", "陆续": "正确：新书店一家接一家地前后开门，符合“陆续”的含义。", "永远": "语义：“永远”表示持续不变，与“开门了”这一次性完成的事相矛盾。", "正在": "体貌：“正在”表示进行中，与句末“了”的完成语气矛盾。"}, "sentence_index": 0, "correct_answer": "陆续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他陆续打碎了一个杯子。", "explanation": "这里应该用〈一下子〉。陆续表示多个事件先后相继，只打碎一个杯子是一次性事件，不能用陆续。"}, {"text": "她陆续生下了一个孩子。", "explanation": "这里应该用〈终于〉。陆续表示多个事件先后相继，只生下一个孩子是一次性事件，不能用陆续。"}, {"text": "他陆续拿到了一张车票。", "explanation": "这里应该用〈顺利〉。陆续表示多个事件先后相继，只拿到一张车票是一次性事件，不能用陆续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与天黑后路灯一盏接一盏亮起的语境不合。"}, {"text": "陆续", "is_correct": true, "explanation": "正确：天黑以后，路灯一盏接一盏地前后亮起，符合“陆续”的含义。"}, {"text": "故意", "is_correct": false, "explanation": "搭配：“故意”要求施事有意图，路灯没有意图，不能说故意亮。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：“亲手”指亲自动手，要求施事是人，路灯不能亲手亮。"}], "explanations": {"偶尔": "语义：“偶尔”表示间或发生，与天黑后路灯一盏接一盏亮起的语境不合。", "陆续": "正确：天黑以后，路灯一盏接一盏地前后亮起，符合“陆续”的含义。", "故意": "搭配：“故意”要求施事有意图，路灯没有意图，不能说故意亮。", "亲手": "搭配：“亲手”指亲自动手，要求施事是人，路灯不能亲手亮。"}, "sentence_index": 6, "correct_answer": "陆续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他陆续就到。", "explanation": "这里应该用〈马上〉。陆续用于多人或多事物先后出现，一个人马上到达不能用陆续。"}, {"text": "他陆续打了一个喷嚏。", "explanation": "这里应该用〈突然〉。陆续表示多个动作先后相继，只打了一个喷嚏是一次性动作，不能用陆续。"}, {"text": "他陆续眨了一下眼睛。", "explanation": "这里应该用〈一下子〉。陆续表示多个动作先后相继，眨一下眼是一瞬间的动作，不能用陆续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个星期，村民陆续的交上了报名表。", "corrected_sentence": "这个星期，村民陆续交上了报名表。", "error_description": "「陆续」是副词，后面不能加「的」，应说「陆续交上」；「陆续的交上」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，村口的路灯很陆续亮了。", "corrected_sentence": "夜里，村口的路灯陆续亮了。", "error_description": "副词错误：「陆续」本身是副词，不能再受程度副词「很」修饰，应说「路灯陆续亮了」，不能说「路灯很陆续亮了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
