INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "豹猫是一种体型较小的猫科动物，身上有类似豹子的斑点，生活在森林中。", "primary_collocate": null, "pronunciation": "bào māo", "ipa": "pɑu˥˩ mɑu˥", "syllable_count": 2, "sentences": [{"text": "这种仿自然群落的种植模式，显著提升了栖息地质量，红外相机陆续捕捉到包括豹猫、斑羚在内的十余种野生哺乳动物踪迹，鸟类种类较十年前增加了近两倍。", "target_word": "豹猫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "豹猫身上有斑点，像一只小豹子。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里有一只豹猫，它的眼睛很亮。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豹猫比家猫大一点，身上的斑点像豹子。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的豹猫身上有圆圆的斑点。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豹猫是猫科动物，常常在树林里捉老鼠。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红外相机拍到了一只在夜里走路的豹猫。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护森林，也就是保护豹猫的家。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，豹猫的尾巴上有一圈一圈的黑色。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豹猫白天睡觉，晚上在森林里找吃的。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "豹貓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体型较小、有豹纹斑点、生活在森林里的猫科动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c4f15-32da-40c3-b527-73291bf6ea7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豹猫", "is_correct": true, "explanation": "豹猫是野生哺乳动物，与斑羚并列，符合句意。"}, {"text": "家猫", "is_correct": false, "explanation": "语义：家猫是家养宠物，不是野生哺乳动物，与“野生”的语境不符。"}, {"text": "金鱼", "is_correct": false, "explanation": "语义：金鱼不是哺乳动物，生活在水中，与“哺乳动物”不符。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "体貌：蝴蝶是昆虫，有翅膀，身体结构与哺乳动物不同。"}], "explanations": {"豹猫": "豹猫是野生哺乳动物，与斑羚并列，符合句意。", "家猫": "语义：家猫是家养宠物，不是野生哺乳动物，与“野生”的语境不符。", "金鱼": "语义：金鱼不是哺乳动物，生活在水中，与“哺乳动物”不符。", "蝴蝶": "体貌：蝴蝶是昆虫，有翅膀，身体结构与哺乳动物不同。"}, "sentence_index": 0, "correct_answer": "豹猫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草丛里忽然跳出一棵豹猫，吓了我一跳。", "explanation": "这里应该用〈只〉。“棵”用于树木、植物，不用于动物，豹猫应用“只”。"}, {"text": "草原上走过一头豹猫，它的身上有很多斑点。", "explanation": "这里应该用〈只〉。“头”用于牛、象等大型动物，豹猫体型较小，应用“只”。"}, {"text": "草丛里有一张豹猫，它的斑点很亮。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西，不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "豹猫", "is_correct": true, "explanation": "豹猫是会在夜里活动的小型猫科动物，能够走路，符合句意。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋不会自己走路，与“红外相机拍到的动物”不符。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“走路”的主语应是人或动物，不能说“一只手走路”。"}, {"text": "船", "is_correct": false, "explanation": "体貌：船没有腿，外形上无法在夜里走路。"}], "explanations": {"豹猫": "豹猫是会在夜里活动的小型猫科动物，能够走路，符合句意。", "鞋": "语义：鞋不会自己走路，与“红外相机拍到的动物”不符。", "手": "搭配：“走路”的主语应是人或动物，不能说“一只手走路”。", "船": "体貌：船没有腿，外形上无法在夜里走路。"}, "sentence_index": 6, "correct_answer": "豹猫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天穿了一件豹猫的裙子。", "explanation": "这里应该用〈豹纹〉。“豹纹”指身上的斑纹图案，“豹猫”是动物名，不能用来指花纹。"}, {"text": "他真是个豹猫胆，什么危险都敢闯。", "explanation": "这里应该用〈豹子〉。“豹子胆”是固定说法，形容胆子大，不能把“豹子”换成“豹猫”。"}, {"text": "池塘边忽然跳出一朵豹猫。", "explanation": "这里应该用〈只〉。“朵”用于花，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在山里看到一条豹猫。", "corrected_sentence": "我在山里看到一只豹猫。", "error_description": "量词错误：“豹猫”是动物，应用量词“只”。“条”多用于蛇、鱼等细长的东西，不用于豹猫，应改为“一只豹猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "红外相机拍到了一只豹猫们。", "corrected_sentence": "红外相机拍到了一只豹猫。", "error_description": "量词与复数错误：“一只”表示单个，与表示复数的“们”不能同时用于“豹猫”，且“们”一般只用于人。应去掉“们”，写成“一只豹猫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
