INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "斑羚，又称青羊，是一种生活在高山地区的哺乳动物，体型像山羊，毛色灰褐，善于在悬崖峭壁上跳跃。", "primary_collocate": null, "pronunciation": "bān líng", "ipa": "pan˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种仿自然群落的种植模式，显著提升了栖息地质量，红外相机陆续捕捉到包括豹猫、斑羚在内的十余种野生哺乳动物踪迹，鸟类种类较十年前增加了近两倍。", "target_word": "斑羚", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "斑羚住在高高的山上。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的斑羚跳得很高。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在动物园看见了一只斑羚。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚的毛是灰褐色的。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚善于在悬崖上跳来跳去。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只斑羚长得像山羊。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上有一群斑羚在吃草。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到我们，斑羚很快跑进了树林。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区里还有不少斑羚。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，生活在高山悬崖地带、像山羊的灰褐色哺乳动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7220669f-a54a-43ff-a5c1-c20a76c762d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蚂蚁", "is_correct": false, "explanation": "语义：蚂蚁是昆虫，不是哺乳动物，与后文“野生哺乳动物”矛盾。"}, {"text": "斑羚", "is_correct": true, "explanation": "斑羚是哺乳动物，与前面的豹猫同属野生哺乳动物，符合语境。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“树木”是植物，不能与豹猫并列，作为“哺乳动物”的成员。"}, {"text": "鲨鱼", "is_correct": false, "explanation": "语义：鲨鱼是鱼类，不是哺乳动物，不能列入“野生哺乳动物”。"}], "explanations": {"蚂蚁": "语义：蚂蚁是昆虫，不是哺乳动物，与后文“野生哺乳动物”矛盾。", "斑羚": "斑羚是哺乳动物，与前面的豹猫同属野生哺乳动物，符合语境。", "树木": "搭配：“树木”是植物，不能与豹猫并列，作为“哺乳动物”的成员。", "鲨鱼": "语义：鲨鱼是鱼类，不是哺乳动物，不能列入“野生哺乳动物”。"}, "sentence_index": 0, "correct_answer": "斑羚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在动物园看见了一条斑羚。", "explanation": "这里应该用〈只〉。斑羚是动物，用“只”；“条”多用于鱼、蛇等细长的东西。"}, {"text": "我在动物园看见了一棵斑羚。", "explanation": "这里应该用〈只〉。“棵”用于树木、植物，不用于动物。"}, {"text": "我在动物园看见了一根斑羚。", "explanation": "这里应该用〈只〉。“根”用于细长的条状物，不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大、长着长鼻子，与“长得像山羊”的外形不符。"}, {"text": "斑羚", "is_correct": true, "explanation": "斑羚的外形像山羊，与“长得像山羊”的描述相符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水中，没有四条腿，与“长得像山羊”不协调。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "体貌：蝴蝶有翅膀、体形细小，与“长得像山羊”的外形不符。"}], "explanations": {"大象": "体貌：大象体型庞大、长着长鼻子，与“长得像山羊”的外形不符。", "斑羚": "斑羚的外形像山羊，与“长得像山羊”的描述相符。", "鱼": "语义：鱼生活在水中，没有四条腿，与“长得像山羊”不协调。", "蝴蝶": "体貌：蝴蝶有翅膀、体形细小，与“长得像山羊”的外形不符。"}, "sentence_index": 6, "correct_answer": "斑羚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他留着一撮斑羚胡子。", "explanation": "这里应该用〈山羊〉。“山羊胡子”是固定说法，斑羚不能这样搭配。"}, {"text": "我们每天在草场上给一群斑羚剪羊毛。", "explanation": "这里应该用〈羊〉。剪羊毛针对绵羊等家畜，斑羚是野生动物，没有可剪的羊毛。"}, {"text": "这只斑羚每天早上都会下蛋。", "explanation": "这里应该用〈鸡〉。斑羚是哺乳动物，不会下蛋，下蛋的是鸡等禽类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条斑羚在悬崖上跳了起来。", "corrected_sentence": "那只斑羚在悬崖上跳了起来。", "error_description": "量词错误：“斑羚”是动物，应使用量词“只”；“条”多用于鱼、蛇等细长的东西，不能用于斑羚。正确说法是“那只斑羚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这群斑羚的都从悬崖上跳了下去。", "corrected_sentence": "这群斑羚都从悬崖上跳了下去。", "error_description": "助词错误：「斑羚」后多出「的」，「斑羚的」变成所属关系，「都」失去所修饰的主语；应说「这群斑羚都从悬崖上跳了下去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437186ef-f3ab-40fd-86c9-0e2b09206707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
