INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13576, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哺乳动物是一类用肺呼吸、身体有毛发、母体用乳汁喂养幼崽的脊椎动物。", "primary_collocate": null, "pronunciation": "bǔ rǔ dòng wù", "ipa": "pu˨˩˦ ɻu˨˩˦ tʊŋ˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "这种仿自然群落的种植模式，显著提升了栖息地质量，红外相机陆续捕捉到包括豹猫、斑羚在内的十余种野生哺乳动物踪迹，鸟类种类较十年前增加了近两倍。", "target_word": "哺乳动物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "哺乳动物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "鲸鱼不是鱼，是生活在海里的哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哺乳动物的妈妈用奶喂养小宝宝。", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗、猫和马都是哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蝙蝠会飞，但它是哺乳动物，不是鸟。", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象是陆地上最大的哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动物园里有很多哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哺乳动物大多身上有毛。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇和青蛙不是哺乳动物，因为它们不喝奶。", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种哺乳动物", "label": "量词"}], "register": "中性", "sense_fingerprint": "哺乳动物：用肺呼吸、有毛发、以乳汁喂幼崽的脊椎动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哺乳动物", "is_correct": true, "explanation": "正确。豹猫、斑羚都是哺乳动物，“哺乳动物”正好概括它们。"}, {"text": "爬行动物", "is_correct": false, "explanation": "语义：豹猫、斑羚是哺乳动物，不是爬行动物，与“包括豹猫、斑羚在内”的列举矛盾。"}, {"text": "鸟类", "is_correct": false, "explanation": "语义：豹猫、斑羚是兽类，不会飞，不是鸟类，与句中所列动物不符。"}, {"text": "昆虫", "is_correct": false, "explanation": "体貌：昆虫有六足、外骨骼，豹猫和斑羚身上长毛发，外形不符。"}], "explanations": {"哺乳动物": "正确。豹猫、斑羚都是哺乳动物，“哺乳动物”正好概括它们。", "爬行动物": "语义：豹猫、斑羚是哺乳动物，不是爬行动物，与“包括豹猫、斑羚在内”的列举矛盾。", "鸟类": "语义：豹猫、斑羚是兽类，不会飞，不是鸟类，与句中所列动物不符。", "昆虫": "体貌：昆虫有六足、外骨骼，豹猫和斑羚身上长毛发，外形不符。"}, "sentence_index": 0, "correct_answer": "哺乳动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在草地上看到一条哺乳动物。", "explanation": "这里应该用〈种〉。〈条〉用于蛇、鱼等细长的动物或东西，不能用来数哺乳动物。"}, {"text": "动物园的草地上有一座哺乳动物。", "explanation": "这里应该用〈种〉。〈座〉用于山、楼房等大型固定的东西，不能用来数动物。"}, {"text": "森林里有一棵哺乳动物。", "explanation": "这里应该用〈种〉。〈棵〉用于树、菜等植物，哺乳动物不能用〈棵〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哺乳动物", "is_correct": true, "explanation": "正确。大象是陆地上最大的动物，属于哺乳动物，“哺乳动物”指它所属的类群。"}, {"text": "爬行动物", "is_correct": false, "explanation": "语义：大象不是爬行动物，“陆地上最大的爬行动物”与大象的类别不符。"}, {"text": "鱼类", "is_correct": false, "explanation": "体貌：鱼用鳃呼吸、身上有鳞，与大象用肺呼吸、皮厚无鳞的特征不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：大象是动物，不是植物，主语与“植物”的类别矛盾。"}], "explanations": {"哺乳动物": "正确。大象是陆地上最大的动物，属于哺乳动物，“哺乳动物”指它所属的类群。", "爬行动物": "语义：大象不是爬行动物，“陆地上最大的爬行动物”与大象的类别不符。", "鱼类": "体貌：鱼用鳃呼吸、身上有鳞，与大象用肺呼吸、皮厚无鳞的特征不符。", "植物": "语义：大象是动物，不是植物，主语与“植物”的类别矛盾。"}, "sentence_index": 6, "correct_answer": "哺乳动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子上放着一块哺乳动物。", "explanation": "这里应该用〈种〉。〈块〉用于块状的东西，不能用来数哺乳动物。"}, {"text": "池塘里漂着一朵哺乳动物。", "explanation": "这里应该用〈种〉。〈朵〉用于花、云等，哺乳动物不能用〈朵〉来数。"}, {"text": "墙上挂着一扇哺乳动物。", "explanation": "这里应该用〈种〉。〈扇〉用于门、窗等，哺乳动物不能用〈扇〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森林里住着很多条哺乳动物。", "corrected_sentence": "森林里住着很多种哺乳动物。", "error_description": "错误形式是“很多条哺乳动物”，正确形式是“很多种哺乳动物”。“哺乳动物”是一类动物，应用量词“种”；“条”用于蛇、鱼等细长的动物，不能用来数哺乳动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蓝鲸是海洋里最大哺乳动物。", "corrected_sentence": "蓝鲸是海洋里最大的哺乳动物。", "error_description": "错误：“最大”修饰名词“哺乳动物”时要用结构助词“的”，写成“最大哺乳动物”。正确：“最大的哺乳动物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
