INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行动或事物经过后留下的痕迹或线索。", "primary_collocate": null, "pronunciation": "zōng jì", "ipa": "tsʊŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "警察一直在寻找小偷的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬家以后，我们再也找不到他的踪迹了。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人好像突然消失了，没有留下任何踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想办法找到了那位老人的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨冲走了坏人留下的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搜救队没有发现那条船的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会隐藏自己，我们发现不了一点踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友离开了这个城市，没有人知道他的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着线索，终于发现了他的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地方的人说，最近没有发现陌生人的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "furigana": "nà gè dì fang de rén shuō, zuì jìn méi yǒu fā xiàn mò shēng rén de zōng jì", "sentence_source": "generated"}], "morphological_forms": [{"form": "蹤跡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物行动后留下的痕迹、线索", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9700a-6e7f-419a-8baf-8a5692ef0729') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13577, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "踪迹", "is_correct": true, "explanation": "踪迹 zōng jì：人或事物经过后留下的痕迹或线索，是正确答案。"}, {"text": "总计", "is_correct": false, "explanation": "zǒng（第三声）与 zōng（第一声）声调不同，意思是合计、总共。"}, {"text": "总机", "is_correct": false, "explanation": "两个音节的声调都与 zōng jì 不同（zǒng jī），意思是电话总机。"}, {"text": "中继", "is_correct": false, "explanation": "zhōng 与 zōng 声母不同（zh 与 z），意思是中间转接，如中继站。"}], "explanations": {"踪迹": "踪迹 zōng jì：人或事物经过后留下的痕迹或线索，是正确答案。", "总计": "zǒng（第三声）与 zōng（第一声）声调不同，意思是合计、总共。", "总机": "两个音节的声调都与 zōng jì 不同（zǒng jī），意思是电话总机。", "中继": "zhōng 与 zōng 声母不同（zh 与 z），意思是中间转接，如中继站。"}, "sentence_index": null, "correct_answer": "踪迹"}, "level_3": {"options": [{"text": "踪迹", "is_correct": true, "explanation": "踪迹：与“寻找”搭配，指小偷行动后留下的痕迹，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“寻找”的对象不能是价格，句中要找的是小偷留下的线索。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资与小偷无关，不是警察寻找的对象。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是缴给学校的费用，不是可以寻找的线索，与句意不符。"}], "explanations": {"踪迹": "踪迹：与“寻找”搭配，指小偷行动后留下的痕迹，符合句意。", "价格": "语义：“寻找”的对象不能是价格，句中要找的是小偷留下的线索。", "工资": "语义：工资与小偷无关，不是警察寻找的对象。", "学费": "语义：学费是缴给学校的费用，不是可以寻找的线索，与句意不符。"}, "sentence_index": 0, "correct_answer": "踪迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的踪迹很长。", "explanation": "这里应该用〈篇幅〉。踪迹指行动后留下的线索，文章的长短要说篇幅。"}, {"text": "他的踪迹很高。", "explanation": "这里应该用〈个子〉。踪迹不指人的高矮，说人高要用个子。"}, {"text": "这次演出的踪迹很好。", "explanation": "这里应该用〈效果〉。踪迹不指演出的好坏，演出效果好才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "踪迹", "is_correct": true, "explanation": "踪迹：与“隐藏”相照应，指他隐藏后仍留下的一点痕迹，“发现不了一点”正是在找这样的线索。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“发现不了一点”不搭配“体重”，人的体重不能像痕迹那样被找到。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不是隐藏后可以被发现或找不到的东西，与句意不符。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是个人的教育经历，与隐藏后找不到的痕迹无关。"}], "explanations": {"踪迹": "踪迹：与“隐藏”相照应，指他隐藏后仍留下的一点痕迹，“发现不了一点”正是在找这样的线索。", "体重": "搭配：“发现不了一点”不搭配“体重”，人的体重不能像痕迹那样被找到。", "年龄": "语义：年龄是人的岁数，不是隐藏后可以被发现或找不到的东西，与句意不符。", "学历": "语义：学历是个人的教育经历，与隐藏后找不到的痕迹无关。"}, "sentence_index": 6, "correct_answer": "踪迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本词典的踪迹很多。", "explanation": "这里应该用〈词条〉。踪迹指行动后留下的线索，词典里的条目要说词条。"}, {"text": "这首歌的踪迹很好听。", "explanation": "这里应该用〈旋律〉。踪迹不指声音的曲调，好听的曲调要说旋律。"}, {"text": "这场雨的踪迹很大。", "explanation": "这里应该用〈雨势〉。踪迹不指降水的强弱，雨的大小要说雨势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在森林里找到了他踪迹。", "corrected_sentence": "我们在森林里找到了他的踪迹。", "error_description": "错误形式是“他踪迹”，正确形式是“他的踪迹”。“他”修饰“踪迹”时要加“的”，省略后“他踪迹”不成词组。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每次行动后都不留下踪迹们。", "corrected_sentence": "他每次行动后都不留下踪迹。", "error_description": "错误：「们」只用于指人或有生命的名词，「踪迹」不能加「们」。正确说法是「他每次行动后都不留下踪迹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指方向、顺序、位置等颠倒过来，与原来相反。", "primary_collocate": null, "pronunciation": "fǎn guò lái", "ipa": "fan˨˩ kwɔ˥˩ laɪ˧˥", "syllable_count": 3, "sentences": [{"text": "生物多样性的恢复，反过来强化了生态系统的自我调节能力，使得林区在面对极端干旱或病虫害时展现出更强的韧性。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "以前是你照顾我，现在我反过来照顾你。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学大人说话，大人有时也反过来向孩子学习。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教学生，学生也会反过来影响老师。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮了我，我也反过来帮助他。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的睡眠让人有精神，精神好反过来又让人睡得好。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先说结果，再反过来讲原因。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把句子反过来读，意思就变了。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但没生气，反过来还向我道歉。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先别急着怪别人，反过来想想自己有没有错。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反過來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "顺序、关系或方向倒转，与原来相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9700a-6e7f-419a-8baf-8a5692ef0729') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，而生物多样性的恢复是自然过程，没有人主动“故意”强化能力。"}, {"text": "反过来", "is_correct": true, "explanation": "反过来表示作用方向倒转：恢复本身反过来加强了生态系统的调节能力，形成因果链的反向作用。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”表示将要发生，与句中已完成的“强化了”矛盾。"}, {"text": "压根", "is_correct": false, "explanation": "语义：“压根”通常接否定，不能用来肯定地说明“强化了能力”。"}], "explanations": {"故意": "语义：“故意”表示有意为之，而生物多样性的恢复是自然过程，没有人主动“故意”强化能力。", "反过来": "反过来表示作用方向倒转：恢复本身反过来加强了生态系统的调节能力，形成因果链的反向作用。", "将": "体貌：“将”表示将要发生，与句中已完成的“强化了”矛盾。", "压根": "语义：“压根”通常接否定，不能用来肯定地说明“强化了能力”。"}, "sentence_index": 0, "correct_answer": "反过来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都反过来跑步。", "explanation": "这里应该用〈坚持〉。反过来表示颠倒或相反，不表示持续；每天坚持跑步才对。"}, {"text": "他的头发忽然反过来白了。", "explanation": "这里应该用〈忽然〉。反过来表示颠倒或相反，不表示突然发生；头发忽然白了才对。"}, {"text": "我们一起吃完饭，反过来聊了很久。", "explanation": "这里应该用〈然后〉。反过来表示颠倒或相反，吃饭与聊天之间没有颠倒关系；吃完饭然后聊了很久才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示两件事并行，与“先说结果，再……”的先后顺序相矛盾。"}, {"text": "反过来", "is_correct": true, "explanation": "反过来表示顺序颠倒：先说结果，再倒过来讲原因，正对应句中的先后安排。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“再……讲”所表示的后续动作矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与有计划的先后安排不合。"}], "explanations": {"同时": "语义：“同时”表示两件事并行，与“先说结果，再……”的先后顺序相矛盾。", "反过来": "反过来表示顺序颠倒：先说结果，再倒过来讲原因，正对应句中的先后安排。", "已经": "体貌：“已经”表示动作已经完成，与“再……讲”所表示的后续动作矛盾。", "忽然": "语义：“忽然”表示突然发生，与有计划的先后安排不合。"}, "sentence_index": 6, "correct_answer": "反过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直反过来学习外语。", "explanation": "这里应该用〈一直〉。反过来表示颠倒或相反，不表示持续；应说一直学习外语。"}, {"text": "他听见敲门声，反过来就去开门了。", "explanation": "这里应该用〈马上〉。反过来表示颠倒或相反，听到敲门后去开门不是颠倒关系；应说马上去开门。"}, {"text": "他每周反过来打扫一次房间。", "explanation": "这里应该用〈定期〉。反过来表示颠倒或相反，不表示周期性；应说定期打扫房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以前他总是批评我，现在我反过来反过来鼓励他。", "corrected_sentence": "以前他总是批评我，现在我反过来鼓励他。", "error_description": "错误：“反过来”重复出现了两次。它只需用一次，正确说法是“现在我反过来鼓励他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以前她总是教我，现在我反过来的教她英语。", "corrected_sentence": "以前她总是教我，现在我反过来教她英语。", "error_description": "错误：“反过来”后面不能加“的”。它是副词，直接修饰动词“教”，不带“的”，正确说法是“我反过来教她英语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da540922-ea9b-4e02-a646-90ad71bed7ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
