INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13587, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指故乡，家乡的土地，也泛指地方特色。", "primary_collocate": null, "pronunciation": "xiāng tǔ", "ipa": "ɕiɑŋ˥ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "年轻一代在参与过程中重新建立了对乡土的认同感，他们拍摄纪录片，整理地方植物志，将传统农耕智慧与现代环境科学相融合。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他离开多年，仍然热爱自己的乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家喜欢写乡土，书里有很多老村子的故事。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一直守着这片乡土，不愿搬到城里。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的菜带着浓浓的乡土特色。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习这片乡土的历史。", "target_word": "乡土", "complexity_tier": "T3", "furigana": "háizimen zài kèshàng xuéxí zhè piàn xiāngtǔ de lìshǐ", "sentence_source": "generated"}, {"text": "他在外打工，心里总想着乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览介绍了这座城市的乡土文化。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老歌里有他童年的乡土记忆。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把乡土的故事写成了一本书。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鄉土", "label": "繁体"}, {"form": "乡土文化", "label": "复合"}], "register": "书面", "sense_fingerprint": "故乡的土地；泛指地方特色与文化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '864d71e1-253d-43e5-8216-c6d2d4741dfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乡土", "is_correct": true, "explanation": "正确。「对乡土的认同感」指对故乡土地的情感，与「整理地方植物志」「农耕智慧」的语境相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能成为「认同感」的对象，也无法与「地方植物志」相关。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠植被稀少，与「整理地方植物志」「农耕智慧」的语境相矛盾。"}, {"text": "高楼", "is_correct": false, "explanation": "搭配：「认同感」常与故乡、地方文化搭配，「高楼」与「传统农耕智慧」的语境不搭。"}], "explanations": {"乡土": "正确。「对乡土的认同感」指对故乡土地的情感，与「整理地方植物志」「农耕智慧」的语境相符。", "电脑": "语义：电脑是机器，不能成为「认同感」的对象，也无法与「地方植物志」相关。", "沙漠": "语义：沙漠植被稀少，与「整理地方植物志」「农耕智慧」的语境相矛盾。", "高楼": "搭配：「认同感」常与故乡、地方文化搭配，「高楼」与「传统农耕智慧」的语境不搭。"}, "sentence_index": 0, "correct_answer": "乡土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小用乡土写作业。", "explanation": "这里应该用〈铅笔〉。乡土指家乡或地方特色，不是可以用来写字的工具。"}, {"text": "这位村长是我们的乡土，很能干。", "explanation": "乡土指故乡或地方特色，不指人；指同乡的人应说〈乡亲〉。"}, {"text": "他用乡土买了一台电脑。", "explanation": "这里应该用〈钱〉。乡土指家乡或地方特色，不能用来付钱或交换物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乡土", "is_correct": true, "explanation": "正确。「在外打工，心里总想着乡土」指心里惦记故乡，与语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能被「心里想着」所惦记，句子不合常理。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是燃料，不会成为打工者心里惦记的对象。"}, {"text": "语法", "is_correct": false, "explanation": "搭配：「心里总想着」所惦记的应是人、地方或亲情，「语法」不能搭配这种表达。"}], "explanations": {"乡土": "正确。「在外打工，心里总想着乡土」指心里惦记故乡，与语境相符。", "冰箱": "语义：冰箱是家电，不能被「心里想着」所惦记，句子不合常理。", "煤炭": "语义：煤炭是燃料，不会成为打工者心里惦记的对象。", "语法": "搭配：「心里总想着」所惦记的应是人、地方或亲情，「语法」不能搭配这种表达。"}, "sentence_index": 6, "correct_answer": "乡土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的乡土有一米八。", "explanation": "这里应该用〈身高〉。乡土指家乡或地方特色，不能用来表示人的身高。"}, {"text": "她的乡土是一所很有名的大学。", "explanation": "乡土指故乡或地方特色，不指学校，这里应该用〈学校〉。"}, {"text": "她把乡土放进了冰箱里保存。", "explanation": "这里应该用〈食物〉。乡土指故乡的土地或地方特色，不是可以放进冰箱保存的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他离开后，仍然惦记着这条乡土。", "corrected_sentence": "他离开后，仍然惦记着这片乡土。", "error_description": "错误在于量词「条」：乡土指一片土地，计量时应用量词「片」；「条」多用于狭长的东西，不能用来计量乡土。正确说法是「这片乡土」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很怀念乡土得风俗，常常写下来。", "corrected_sentence": "他很怀念乡土的风俗，常常写下来。", "error_description": "错误在于助词「得」：修饰名词「风俗」时应用结构助词「的」，「乡土得风俗」不成立；正确说法是「乡土的风俗」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
