INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人对某个群体、想法或事物感到认可、接受，并觉得自己属于它的一种心理感受。", "primary_collocate": null, "pronunciation": "rèn tóng gǎn", "ipa": "ɻən˥˩ tʰʊŋ˧˥ kan˨˩˦", "syllable_count": 3, "sentences": [{"text": "年轻一代在参与过程中重新建立了对乡土的认同感，他们拍摄纪录片，整理地方植物志，将传统农耕智慧与现代环境科学相融合。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "住在同一个社区，让居民有了认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工需要时间，才会对公司有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同的语言能增强人们的认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷对自己的球队有很强的认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外长大，对这个国家没有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动让大家的认同感更强了。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师经常讲故事，帮学生建立认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得没人理解她，缺少认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家乡的节日让他找到了认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "認同感", "label": "繁体"}, {"form": "文化认同感", "label": "复合"}], "register": "中性", "sense_fingerprint": "对群体或事物认可并有归属的心理感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '864d71e1-253d-43e5-8216-c6d2d4741dfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认同感", "is_correct": true, "explanation": "正确。“重新建立了对乡土的……”指对家乡的认可与归属感受，与“参与过程”“拍摄纪录片”的语境一致。"}, {"text": "敌意", "is_correct": false, "explanation": "语义：“敌意”表示对立的恶意，与“重新建立”“参与”所体现的亲近态度相反。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：“利润”是经济收益，不能说“对乡土的利润”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”是买卖中的数额，不用于“对乡土的……”这类情感关系。"}], "explanations": {"认同感": "正确。“重新建立了对乡土的……”指对家乡的认可与归属感受，与“参与过程”“拍摄纪录片”的语境一致。", "敌意": "语义：“敌意”表示对立的恶意，与“重新建立”“参与”所体现的亲近态度相反。", "利润": "搭配：“利润”是经济收益，不能说“对乡土的利润”。", "价格": "搭配：“价格”是买卖中的数额，不用于“对乡土的……”这类情感关系。"}, "sentence_index": 0, "correct_answer": "认同感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看到那条狗，他感到很强的认同感。", "explanation": "这里应该用〈恐惧感〉。认同感指接受并归属于某个群体或观念，面对猛犬时的害怕要用“恐惧感”。"}, {"text": "我对这位新来的同事很有认同感。", "explanation": "这里应该用〈好感〉。认同感指对群体、观念的接受与归属，对个人的喜欢要用“好感”。"}, {"text": "听他重复同一个故事，我感到很强的认同感。", "explanation": "这里应该用〈厌烦感〉。认同感指接受并归属于某个群体或观念，对重复内容的不耐烦要用“厌烦感”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认同感", "is_correct": true, "explanation": "正确。“让大家的……更强了”指大家对群体的认可与归属感增强，与“这次活动”相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”与活动带来的心理变化无关，不能“更强”。"}, {"text": "食量", "is_correct": false, "explanation": "搭配：“食量”用“大”“小”来形容，不说“更强”。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不用“强”来形容程度，不说“脚步更强了”。"}], "explanations": {"认同感": "正确。“让大家的……更强了”指大家对群体的认可与归属感增强，与“这次活动”相符。", "体重": "语义：“体重”与活动带来的心理变化无关，不能“更强”。", "食量": "搭配：“食量”用“大”“小”来形容，不说“更强”。", "脚步": "搭配：“脚步”不用“强”来形容程度，不说“脚步更强了”。"}, "sentence_index": 6, "correct_answer": "认同感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他解出那道难题后，心里有很强的认同感。", "explanation": "这里应该用〈成就感〉。认同感指接受并归属于某个群体或观念，解题后的满足要用“成就感”。"}, {"text": "比赛前，他手心直冒汗，心里有很强的认同感。", "explanation": "这里应该用〈紧张感〉。认同感指接受并归属于某个群体或观念，比赛前的心理紧绷要用“紧张感”。"}, {"text": "没吃早饭，我感到很强的认同感。", "explanation": "这里应该用〈饥饿感〉。认同感指接受并归属于某个群体或观念，空腹时的感受要用“饥饿感”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这座城市有一块很强的认同感。", "corrected_sentence": "他对这座城市有一种很强的认同感。", "error_description": "量词错误：“认同感”是抽象名词，应该用“一种”，不能用“一块”。“块”只用于有形的块状物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家学校的认同感越来越强了。", "corrected_sentence": "大家对学校的认同感越来越强了。", "error_description": "介词错误：认同感所指的对象要用介词“对”引出，应说“大家对学校的认同感”。原句中“大家”直接修饰“学校的认同感”，搭配不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd1236d4-b544-4300-a535-4befb01082a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用摄影设备记录影像，如拍照或录像。", "primary_collocate": null, "pronunciation": "pāi shè", "ipa": "pʰai˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "年轻一代在参与过程中重新建立了对乡土的认同感，他们拍摄纪录片，整理地方植物志，将传统农耕智慧与现代环境科学相融合。", "target_word": "拍摄", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他想拍摄一部关于家乡的短片。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天去公园拍摄照片。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演正在拍摄最后一场戏。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍摄了很多美丽的风景。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影在海边拍摄，风景很美。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师拍摄过很多有名的人。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在博物馆里拍摄。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机拍摄了孩子跑步的样子。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台来学校拍摄学生们的比赛。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍摄了", "label": "体标：完成"}, {"form": "拍摄过", "label": "体标：经历"}, {"form": "拍摄着", "label": "体标：持续"}], "register": "中性", "sense_fingerprint": "用设备拍照或录像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb5dee-9d44-4bb3-8c39-0659efa57b2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍摄", "is_correct": true, "explanation": "正确：“拍摄”指用摄影设备记录影像，可以用来说拍纪录片。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，纪录片不能吃。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，与记录影像无关。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物或作物，不能用于纪录片。"}], "explanations": {"拍摄": "正确：“拍摄”指用摄影设备记录影像，可以用来说拍纪录片。", "吃": "搭配：“吃”的对象是食物，纪录片不能吃。", "煮": "语义：“煮”是加热食物，与记录影像无关。", "种植": "搭配：“种植”用于植物或作物，不能用于纪录片。"}, "sentence_index": 0, "correct_answer": "拍摄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在录音棚拍摄了一首歌。", "explanation": "这里应该用〈录制〉。拍摄只用于记录影像，录音只能说〈录制〉。"}, {"text": "他拍摄了一个想法。", "explanation": "拍摄的对象必须是能被记录成影像的人或景物，“想法”不能被拍摄，这里应该用〈表达〉。"}, {"text": "他用手拍摄了桌子。", "explanation": "这里是“用手打”的意思，应该用〈拍打〉。拍摄只用于记录影像，不表示打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍摄", "is_correct": true, "explanation": "正确：“拍摄”与“有名的人”搭配，指用摄影设备记录他们的影像。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是用火加热，与拍摄人物无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬过很多有名的人”语义荒谬，“咬”不能这样搭配。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，不能用于人。"}], "explanations": {"拍摄": "正确：“拍摄”与“有名的人”搭配，指用摄影设备记录他们的影像。", "烧": "语义：“烧”是用火加热，与拍摄人物无关。", "咬": "搭配：“咬过很多有名的人”语义荒谬，“咬”不能这样搭配。", "烤": "语义：“烤”是加热食物，不能用于人。"}, "sentence_index": 6, "correct_answer": "拍摄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影院每晚都拍摄新电影。", "explanation": "这里应该用〈放映〉。拍摄是记录影像，电影院播放电影要说〈放映〉。"}, {"text": "这幅古画去年被拍摄出了八十万元。", "explanation": "这里应该用〈拍卖〉。拍卖是把东西卖出高价，拍摄只指记录影像。"}, {"text": "观众在电视机前拍摄电视剧。", "explanation": "这里应该用〈收看〉。观众只是观看节目，不拍摄，应说〈收看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拍摄了过很多野生动物的纪录片。", "corrected_sentence": "他拍摄过很多野生动物的纪录片。", "error_description": "“拍摄”后的体标用错：“了”和“过”不能同时用。表示经历应说“拍摄过”，不能说“拍摄了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天拍摄着一张照片。", "corrected_sentence": "她昨天拍摄了一张照片。", "error_description": "“拍摄”后的体标用错：“昨天”说明动作已经完成，应该用“了”，不能用表示持续的“着”。应说“拍摄了一张照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
