INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13593, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13593, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "农耕指农业生产中耕种土地、栽培作物等相关活动。", "primary_collocate": null, "pronunciation": "nóng gēng", "ipa": "nʊŋ˧˥ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "年轻一代在参与过程中重新建立了对乡土的认同感，他们拍摄纪录片，整理地方植物志，将传统农耕智慧与现代环境科学相融合。", "target_word": "农耕", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "爷爷一辈子在农村从事农耕。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天一到，农耕就忙起来了。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的农耕主要靠牛和人力。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子的农耕历史有三千多年。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代农耕已经用上了很多机器。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农耕离不开阳光、雨水和土地。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家世代以农耕为生。", "target_word": "农耕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们参观了一个体验农耕的农场。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的农耕以种水稻为主。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "农耕文化", "label": "复合"}, {"form": "農耕", "label": "繁体"}], "register": "书面", "sense_fingerprint": "农业生产中耕种土地、栽培作物的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '998929c8-6bfe-49c6-be32-027efe40f4d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13593, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农耕", "is_correct": true, "explanation": "农耕指耕种土地、栽培作物的农业活动，与「传统」「乡土」的语境相合。"}, {"text": "城市", "is_correct": false, "explanation": "语义：全句讲的是乡土与地方植物志，「城市」与此语境相悖。"}, {"text": "网络", "is_correct": false, "explanation": "搭配：「传统」一般不修饰「网络」，「传统网络智慧」不成立。"}, {"text": "电子", "is_correct": false, "explanation": "语义：「电子」属于现代技术，与「传统」相矛盾。"}], "explanations": {"农耕": "农耕指耕种土地、栽培作物的农业活动，与「传统」「乡土」的语境相合。", "城市": "语义：全句讲的是乡土与地方植物志，「城市」与此语境相悖。", "网络": "搭配：「传统」一般不修饰「网络」，「传统网络智慧」不成立。", "电子": "语义：「电子」属于现代技术，与「传统」相矛盾。"}, "sentence_index": 0, "correct_answer": "农耕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们国家的农耕占国内生产总值的比重逐年下降。", "explanation": "这里应该用〈农业〉。农耕指耕种土地、栽培作物的具体活动；说产业规模和产值比重时要用农业。"}, {"text": "全县的农耕面积有十万亩。", "explanation": "这里应该用〈耕地〉。农耕是耕种活动，不是土地；统计面积时要用耕地。"}, {"text": "这片农耕很肥沃。", "explanation": "这里应该用〈农田〉。农耕指耕种活动，不能指土地本身；说土壤肥沃时要用农田。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农耕", "is_correct": true, "explanation": "农耕指耕种土地、栽培作物的农业活动，依赖阳光、雨水和土地，与句意一致。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不依赖阳光、雨水和土地，与句意相悖。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱与阳光、雨水无关，句子说的是依赖自然条件的活动。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：「离不开阳光、雨水和土地」需要依赖自然条件的主语，「电脑」不搭配。"}], "explanations": {"农耕": "农耕指耕种土地、栽培作物的农业活动，依赖阳光、雨水和土地，与句意一致。", "手机": "语义：手机不依赖阳光、雨水和土地，与句意相悖。", "冰箱": "语义：冰箱与阳光、雨水无关，句子说的是依赖自然条件的活动。", "电脑": "搭配：「离不开阳光、雨水和土地」需要依赖自然条件的主语，「电脑」不搭配。"}, "sentence_index": 6, "correct_answer": "农耕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷的农耕都挂在墙上。", "explanation": "这里应该用〈农具〉。农耕是耕种的活动，不是可以挂起来的器具；挂在墙上的工具要用农具。"}, {"text": "他是村里最勤快的农耕。", "explanation": "这里应该用〈农民〉。农耕指耕种的活动，不指人；说一个人勤快要用农民。"}, {"text": "地里的农耕长得很高。", "explanation": "这里应该用〈庄稼〉。农耕是耕种的活动，不会生长；地里长出来的作物要用庄稼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们农耕方式已经改变了很多。", "corrected_sentence": "他们的农耕方式已经改变了很多。", "error_description": "「农耕方式」前作定语的领属「他们」后要加「的」，应说「他们的农耕方式」；漏掉「的」是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里还保留着一件古老的农耕。", "corrected_sentence": "村里还保留着一种古老的农耕。", "error_description": "「农耕」的量词应为「种」，不能用「件」；应说「一种农耕」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "由上而下", "is_correct": true, "explanation": "反义：由上而下表示从高处到低处，与「由下而上」方向相反。"}, {"text": "逐步", "is_correct": false, "explanation": "不构成反义：逐步指按步骤进行，与方向无关。"}, {"text": "突然", "is_correct": false, "explanation": "不构成反义：突然指出乎意料地发生，与方向无关。"}, {"text": "一齐", "is_correct": false, "explanation": "不构成反义：一齐指同时进行，与方向无关。"}], "correct_answer": "由上而下", "explanations": {"由上而下": "反义：由上而下表示从高处到低处，与「由下而上」方向相反。", "逐步": "不构成反义：逐步指按步骤进行，与方向无关。", "突然": "不构成反义：突然指出乎意料地发生，与方向无关。", "一齐": "不构成反义：一齐指同时进行，与方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "由上而下", "is_correct": true, "explanation": "反义：由上而下表示从高处到低处，与「由下而上」方向相反。"}, {"text": "忽然", "is_correct": false, "explanation": "不构成反义：忽然指突然发生，与方向无关。"}, {"text": "同时", "is_correct": false, "explanation": "不构成反义：同时指在同一时间，与方向无关。"}, {"text": "渐渐", "is_correct": false, "explanation": "不构成反义：渐渐指逐步变化，与方向无关。"}], "correct_answer": "由上而下", "explanations": {"由上而下": "反义：由上而下表示从高处到低处，与「由下而上」方向相反。", "忽然": "不构成反义：忽然指突然发生，与方向无关。", "同时": "不构成反义：同时指在同一时间，与方向无关。", "渐渐": "不构成反义：渐渐指逐步变化，与方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "表示从低处到高处，或从下层到上层的顺序或方向。", "primary_collocate": null, "pronunciation": "yóu xià ér shàng", "ipa": "iou˧˥ ɕja˥˩ aɻ˧˥ ʂɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种由下而上的生态伦理建构，使得“环境保护”不再是一个空洞的政治话语，而是嵌入日常生活的价值选择。", "target_word": "由下而上", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司的新办法是由下而上提出意见。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们由下而上检查每一层楼。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画这幅画时，他由下而上慢慢地画。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划由下而上，先听员工的想法。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架要由下而上一层一层放书。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她由下而上擦着窗户。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼由下而上都亮着灯。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛名单是由下而上排的。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的改革由下而上进行，老师们都很支持。", "target_word": "由下而上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "由上而下", "label": "反义形式"}], "register": "中性", "sense_fingerprint": "从低处到高处、从下层到上层的顺序或方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '998929c8-6bfe-49c6-be32-027efe40f4d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "由下而上", "is_correct": true, "explanation": "正确：修饰“建构”，指从下层到上层的方式，与“嵌入日常生活”相符。"}, {"text": "由上而下", "is_correct": false, "explanation": "语义：「由上而下」是自上而下的推行方式，与句中“不再是政治话语、而是嵌入日常生活”的草根语境相反。"}, {"text": "由左而右", "is_correct": false, "explanation": "语义：「由左而右」指横向的空间顺序，与“生态伦理建构”的层次方向无关。"}, {"text": "由南而北", "is_correct": false, "explanation": "语义：「由南而北」指地理方位上的推移，与“生态伦理建构”无关。"}], "explanations": {"由下而上": "正确：修饰“建构”，指从下层到上层的方式，与“嵌入日常生活”相符。", "由上而下": "语义：「由上而下」是自上而下的推行方式，与句中“不再是政治话语、而是嵌入日常生活”的草根语境相反。", "由左而右": "语义：「由左而右」指横向的空间顺序，与“生态伦理建构”的层次方向无关。", "由南而北": "语义：「由南而北」指地理方位上的推移，与“生态伦理建构”无关。"}, "sentence_index": 0, "correct_answer": "由下而上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重由下而上增加了三公斤。", "explanation": "这里误用了「由下而上」。它表示方向或顺序，不能用来描述体重的数量增长。"}, {"text": "他由下而上把那本书读完了。", "explanation": "由下而上表示方向或层次顺序，不能说读完一本书的进度。这里应该用〈逐页〉。"}, {"text": "老师由下而上喜欢这个学生。", "explanation": "这里应该用〈渐渐〉。由下而上表示空间方向或顺序，不能修饰「喜欢」这类心理变化；心理的渐变要用〈渐渐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由下而上", "is_correct": true, "explanation": "正确：说明擦窗的方向是从下到上，符合句意。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突发，与「擦着」的持续动作矛盾。"}, {"text": "一下子", "is_correct": false, "explanation": "体貌：「一下子」表示短时间内完成，与「着」表示的进行状态冲突。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：「猛然」表示突然发生，与持续的擦窗动作矛盾。"}], "explanations": {"由下而上": "正确：说明擦窗的方向是从下到上，符合句意。", "忽然": "语义：「忽然」表示突发，与「擦着」的持续动作矛盾。", "一下子": "体貌：「一下子」表示短时间内完成，与「着」表示的进行状态冲突。", "猛然": "语义：「猛然」表示突然发生，与持续的擦窗动作矛盾。"}, "sentence_index": 6, "correct_answer": "由下而上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他由下而上高兴了一整天。", "explanation": "这里应该用〈逐渐〉。由下而上表示空间方向或顺序，不能描述心情的变化过程；心情的渐变要用〈逐渐〉。"}, {"text": "这张桌子由下而上很便宜。", "explanation": "由下而上表示方向或顺序，不能用来描述价格的高低，这里误用成了价钱的意思。"}, {"text": "这个城市的交通由下而上很方便。", "explanation": "这里应该用〈四通八达〉。由下而上表示方向或顺序，不能描述交通便利的程度；描述路网便利要用〈四通八达〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人很由下而上刷墙。", "corrected_sentence": "工人由下而上刷墙。", "error_description": "程度副词误用：「由下而上」表示方向，不能被「很」修饰；应去掉「很」，说「工人由下而上刷墙」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一种由下而上管理方式。", "corrected_sentence": "这是一种由下而上的管理方式。", "error_description": "错误形式：「由下而上」修饰名词「管理方式」时漏掉了「的」。正确形式：「由下而上的管理方式」，名词前的修饰语后要加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
