INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13595, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容里面没有内容或没有实际意义。", "primary_collocate": null, "pronunciation": "kōng dòng", "ipa": "kʰʊŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种由下而上的生态伦理建构，使得“环境保护”不再是一个空洞的政治话语，而是嵌入日常生活的价值选择。", "target_word": "空洞", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的发言很空洞，没有一点内容。", "target_word": "空洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章太空洞了，我不想读。", "target_word": "空洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师不喜欢空洞的口号。", "target_word": "空洞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说了很多空洞的话，没有一点用处。", "target_word": "空洞", "complexity_tier": "T3", "furigana": "tā shuō le hěn duō kōngdòng de huà, méi yǒu yì diǎn yòngchù.", "sentence_source": "generated"}, {"text": "这份计划写得太空洞，没有具体办法。", "target_word": "空洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事很空洞，听完什么也没记住。", "target_word": "空洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空洞的理论帮不了我们解决问题。", "target_word": "空洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起空洞的保证，大家更想看到行动。", "target_word": "空洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广告内容空洞，只有漂亮的话。", "target_word": "空洞", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "空洞的", "label": "定语形式"}, {"form": "空洞地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "话语、文章等内容贫乏，没有实际意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f262552-c10c-4507-925d-833b9d7cd991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空洞", "is_correct": true, "explanation": "空洞：形容话语缺乏实际内容，与后半句“嵌入日常生活的价值选择”形成对比，符合“不再是……而是……”的句式。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音清亮爽利，不能用来修饰“政治话语”这类讲内容的话。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”多用于人的性情或语气，与“政治话语”的说理性质不搭。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或外貌，不能描述言论的性质。"}], "explanations": {"空洞": "空洞：形容话语缺乏实际内容，与后半句“嵌入日常生活的价值选择”形成对比，符合“不再是……而是……”的句式。", "清脆": "语义：“清脆”形容声音清亮爽利，不能用来修饰“政治话语”这类讲内容的话。", "温柔": "搭配：“温柔”多用于人的性情或语气，与“政治话语”的说理性质不搭。", "明亮": "体貌：“明亮”形容光线或外貌，不能描述言论的性质。"}, "sentence_index": 0, "correct_answer": "空洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脸色很空洞，看上去一点精神也没有。", "explanation": "这里应该用〈苍白〉。空洞形容话语、文章等内容缺乏实际意义，不用来形容脸色；脸色不好要说苍白。"}, {"text": "这道菜的味道很空洞，一点也吃不出来。", "explanation": "这里应该用〈寡淡〉。空洞形容话语、文章等内容缺乏实际意义，不用来形容味道；味道淡要说寡淡。"}, {"text": "公司还有一个空洞的职位，正在招人。", "explanation": "这里应该用〈空缺〉。职位还没有人担任要说“空缺”，“空洞”指话语或内容缺乏实际意义，不表示位置或名额空出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空洞", "is_correct": true, "explanation": "空洞：与“听完什么也没记住”相呼应，说明故事没有留下任何印象，所以空洞。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不能用来描述故事的内容。"}, {"text": "湿润", "is_correct": false, "explanation": "体貌：“湿润”形容物体或环境的潮湿质感，与故事无关。"}, {"text": "方正", "is_correct": false, "explanation": "搭配：“方正”形容形状，不能用来形容一个故事。"}], "explanations": {"空洞": "空洞：与“听完什么也没记住”相呼应，说明故事没有留下任何印象，所以空洞。", "响亮": "语义：“响亮”形容声音，不能用来描述故事的内容。", "湿润": "体貌：“湿润”形容物体或环境的潮湿质感，与故事无关。", "方正": "搭配：“方正”形容形状，不能用来形容一个故事。"}, "sentence_index": 6, "correct_answer": "空洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下午很空洞，可以陪你去逛街。", "explanation": "这里应该用〈空闲〉。空洞不用来形容人的时间安排，“下午有空”要说空闲。"}, {"text": "这家店的生意很空洞，一天也没几个客人。", "explanation": "这里应该用〈冷清〉。空洞形容内容缺乏实际意义，不用来说生意或人气的冷淡。"}, {"text": "我肚子很空洞，想吃点东西了。", "explanation": "这里应该用〈饥饿〉。空洞用于内容或空的物体，不用来形容肚子饿的感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的发言空洞的重复着口号。", "corrected_sentence": "他的发言空洞地重复着口号。", "error_description": "错误：“空洞的重复”，应为“空洞地重复”。“空洞”修饰后面的动词时要用状语标记“地”，“的”只用于修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划很空洞地，没有具体办法。", "corrected_sentence": "这个计划很空洞，没有具体办法。", "error_description": "错误：“很空洞地”，多出了“地”。“地”是状语标记，只用在后面有动词的时候；这里“空洞”后面没有动词，应去掉“地”，说“很空洞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
