INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13597, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指平时每天进行的常规活动。", "primary_collocate": null, "pronunciation": "rì cháng shēng huó", "ipa": "ɻɻ̩˥˩ ʈʂʰɑŋ˧˥ ʂɤŋ˥ xuɔ˧˥", "syllable_count": 4, "sentences": [{"text": "这种由下而上的生态伦理建构，使得“环境保护”不再是一个空洞的政治话语，而是嵌入日常生活的价值选择。", "target_word": "日常生活", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在古罗马，孩子们的日常生活和今天的孩子有些不同，但也有相似之处。", "target_word": "日常生活", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古罗马的儿童，他们的日常生活充满了学习、家务和简单的快乐，构成了他们童年的一部分。", "target_word": "日常生活", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "手机已经成了日常生活的一部分。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的日常生活很简单，早上跑步，晚上看书。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新城市以后，我的日常生活变了。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和电都是日常生活里不能少的东西。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是普通人的日常生活。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日常生活中，我们常常需要和邻居说话。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病以后，他的日常生活需要家人帮忙。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "日常生活：平时每天进行的常规活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日常生活", "is_correct": true, "explanation": "正确。前文说“环境保护”要嵌入平时每天进行的常规活动，所以是“日常生活”。"}, {"text": "政治", "is_correct": false, "explanation": "语义：前文说“环境保护”不再是空洞的政治话语，而是嵌入某个领域，不能再落回“政治”。"}, {"text": "政府", "is_correct": false, "explanation": "语义：句中强调“由下而上”的建构，“政府”属自上而下的行政机构，嵌入它与之相反。"}, {"text": "上层", "is_correct": false, "explanation": "语义：前文强调“由下而上”的建构，嵌入“上层”与之相反。"}], "explanations": {"日常生活": "正确。前文说“环境保护”要嵌入平时每天进行的常规活动，所以是“日常生活”。", "政治": "语义：前文说“环境保护”不再是空洞的政治话语，而是嵌入某个领域，不能再落回“政治”。", "政府": "语义：句中强调“由下而上”的建构，“政府”属自上而下的行政机构，嵌入它与之相反。", "上层": "语义：前文强调“由下而上”的建构，嵌入“上层”与之相反。"}, "sentence_index": 0, "correct_answer": "日常生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末社区组织了一次日常生活，大家一起打扫卫生。", "explanation": "这里应该用〈活动〉。〈日常生活〉指平时的生活本身，不是可以组织、举行的一次活动。"}, {"text": "我昨天去银行办了一项日常生活。", "explanation": "这里应该用〈业务〉。〈日常生活〉指平时的生活，不是可以办理的事项。"}, {"text": "我去超市买了很多日常生活。", "explanation": "这里应该用〈用品〉。〈日常生活〉是抽象的生活过程，不能买，应说“日常用品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日常生活", "is_correct": true, "explanation": "正确。水和电是平时生活中不可缺少的东西，所以是“日常生活里”。"}, {"text": "童话", "is_correct": false, "explanation": "语义：水和电是现实生活的必需品，不属于童话世界，与“不能少”的现实语境矛盾。"}, {"text": "诗歌", "is_correct": false, "explanation": "语域：“诗歌”是文学语体，与这句平实的生活叙述不搭。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：水和电是真实的必需品，不会出现在梦境里，与句意矛盾。"}], "explanations": {"日常生活": "正确。水和电是平时生活中不可缺少的东西，所以是“日常生活里”。", "童话": "语义：水和电是现实生活的必需品，不属于童话世界，与“不能少”的现实语境矛盾。", "诗歌": "语域：“诗歌”是文学语体，与这句平实的生活叙述不搭。", "梦境": "语义：水和电是真实的必需品，不会出现在梦境里，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "日常生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们玩了一局日常生活。", "explanation": "这里应该用〈游戏〉。〈日常生活〉不是一局可以玩的游戏，〈局〉只用于棋牌、游戏等。"}, {"text": "电视台播出了一档日常生活。", "explanation": "这里应该用〈节目〉。〈日常生活〉不是可以播出的节目，〈档〉用于节目、栏目。"}, {"text": "他代表学校参加了一场日常生活。", "explanation": "这里应该用〈比赛〉。〈日常生活〉是平时的生活，不是可以参加的比赛，〈场〉不能用来数它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现代人的一个日常生活离不开网络。", "corrected_sentence": "现代人的日常生活离不开网络。", "error_description": "错误形式是“一个日常生活”，正确形式是“日常生活”。“日常生活”是抽象名词，不能用个体量词“一个”修饰，应直接说“现代人的日常生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章介绍了农村人地日常生活。", "corrected_sentence": "这篇文章介绍了农村人的日常生活。", "error_description": "错误形式是“农村人地日常生活”，正确形式是“农村人的日常生活”。修饰名词要用“的”，“地”用于修饰动词或形容词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
