INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "返回家乡；回到故乡。", "primary_collocate": null, "pronunciation": "fǎn xiāng", "ipa": "fan˨˩˦ ɕiɑŋ˥", "syllable_count": 2, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "返乡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "春节快到了，他买了火车票准备返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多在外打工的人都选择在过年时返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家十年，终于决定返乡了。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "返乡的路很长，我们坐了一天的车。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家里等着返乡的儿子。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从大城市返乡后，开了一家小店。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年因为下雪，很多人没能按时返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他返乡以后，每天陪着父母吃饭。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候返乡？我想去车站接你。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "返乡了", "label": "完成体"}, {"form": "返乡过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "返回家乡，回到故乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '998929c8-6bfe-49c6-be32-027efe40f4d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "返乡", "is_correct": true, "explanation": "正确答案。返乡指回到家乡，读作 fǎn xiāng。"}, {"text": "反响", "is_correct": false, "explanation": "fǎn xiǎng（第三声）与 fǎn xiāng（第一声）只有第二音节声调不同，意思是回声或反应。"}, {"text": "反向", "is_correct": false, "explanation": "第二音节声调不同（xiàng，第四声），意思是相反的方向。"}, {"text": "饭香", "is_correct": false, "explanation": "第一音节声调不同（fàn，第四声），意思是饭菜的香味。"}], "explanations": {"返乡": "正确答案。返乡指回到家乡，读作 fǎn xiāng。", "反响": "fǎn xiǎng（第三声）与 fǎn xiāng（第一声）只有第二音节声调不同，意思是回声或反应。", "反向": "第二音节声调不同（xiàng，第四声），意思是相反的方向。", "饭香": "第一音节声调不同（fàn，第四声），意思是饭菜的香味。"}, "sentence_index": null, "correct_answer": "返乡"}, "level_3": {"options": [{"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“青年”矛盾，不能用来修饰青年。"}, {"text": "返乡", "is_correct": true, "explanation": "正确答案。“返乡青年”指从外地回到家乡的年轻人，符合句意。"}, {"text": "躺平", "is_correct": false, "explanation": "语域：“躺平”是口语网络用语，与这段书面化的长句语域不合。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：失踪的人无法在社交媒体上发帖，与“写道”矛盾。"}], "explanations": {"年迈": "语义：“年迈”指年纪很大，与“青年”矛盾，不能用来修饰青年。", "返乡": "正确答案。“返乡青年”指从外地回到家乡的年轻人，符合句意。", "躺平": "语域：“躺平”是口语网络用语，与这段书面化的长句语域不合。", "失踪": "语义：失踪的人无法在社交媒体上发帖，与“写道”矛盾。"}, "sentence_index": 0, "correct_answer": "返乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我第一次来这个城市，就决定在这里返乡。", "explanation": "这里应该用〈定居〉。返乡指回到自己的家乡，第一次来的城市不是家乡，不能用“返乡”。"}, {"text": "他在超市里忘了钥匙，又返乡找了一次。", "explanation": "这里应该用〈回去〉。返乡指回到家乡这样的长距离返回，回超市找东西只能用“回去”。"}, {"text": "他利用假期去陌生的北京返乡，玩得很开心。", "explanation": "这里应该用〈旅游〉。返乡指回到自己的家乡，“陌生的北京”不可能是家乡，应说“去北京旅游”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13598, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "返乡", "is_correct": true, "explanation": "正确答案。返乡指回到家乡，读作 fǎn xiāng。"}, {"text": "芬香", "is_correct": false, "explanation": "fēn xiāng 与 fǎn xiāng 声母相同，韵母 en 与 an 不同，声调也不同，意思是香气浓郁。"}, {"text": "焚香", "is_correct": false, "explanation": "fén xiāng 与 fǎn xiāng 韵母 en 与 an 不同，声调也不同，意思是点燃香料。"}, {"text": "返现", "is_correct": false, "explanation": "fǎn xiàn 与 fǎn xiāng 只有第二音节的韵母不同（an 与 ang），声调也不同，意思是返还现金。"}], "explanations": {"返乡": "正确答案。返乡指回到家乡，读作 fǎn xiāng。", "芬香": "fēn xiāng 与 fǎn xiāng 声母相同，韵母 en 与 an 不同，声调也不同，意思是香气浓郁。", "焚香": "fén xiāng 与 fǎn xiāng 韵母 en 与 an 不同，声调也不同，意思是点燃香料。", "返现": "fǎn xiàn 与 fǎn xiāng 只有第二音节的韵母不同（an 与 ang），声调也不同，意思是返还现金。"}, "sentence_index": null, "correct_answer": "返乡"}, "level_3": {"options": [{"text": "进城", "is_correct": false, "explanation": "语义：“进城”指从乡村进入城市，“从大城市进城”与句意矛盾。"}, {"text": "返乡", "is_correct": true, "explanation": "正确答案。“从大城市返乡”指离开城市回到家乡，与后文开店的语境相符。"}, {"text": "逛街", "is_correct": false, "explanation": "搭配：“逛街”是随意的消遣，不能作为“从大城市……后”离开的动作。"}, {"text": "赶集", "is_correct": false, "explanation": "搭配：“赶集”指到集市买卖，与“从大城市”不搭配，句子说不通。"}], "explanations": {"进城": "语义：“进城”指从乡村进入城市，“从大城市进城”与句意矛盾。", "返乡": "正确答案。“从大城市返乡”指离开城市回到家乡，与后文开店的语境相符。", "逛街": "搭配：“逛街”是随意的消遣，不能作为“从大城市……后”离开的动作。", "赶集": "搭配：“赶集”指到集市买卖，与“从大城市”不搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "返乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上六点就返乡上班，晚上才回来。", "explanation": "这里应该用〈出门〉。返乡指回到家乡，每天去单位上班不是返乡，应说“出门上班”。"}, {"text": "他下班后去图书馆返乡，看了一会儿书。", "explanation": "这里应该用〈学习〉。返乡指回到家乡，去图书馆看书应说“去图书馆学习”，不能用“返乡”。"}, {"text": "他刚到酒店就返乡了。", "explanation": "这里应该用〈入住〉。返乡指回到家乡，住进酒店不是返乡，应说“入住酒店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经返乡了过三次。", "corrected_sentence": "他已经返乡过三次。", "error_description": "“返乡了过”是错误形式：“了”与“过”不能同时用在同一个动词后。表示有过某种经历时只说“返乡过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她提前一周返乡着。", "corrected_sentence": "她提前一周返乡了。", "error_description": "体标错误：“返乡”是一次性的回家动作，表示已经发生要用“了”，不能用“着”。应说“返乡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
