INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13599, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写着说，用来引出所写的内容。", "primary_collocate": null, "pronunciation": "xiě dào", "ipa": "ɕjɛ˨˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "写道", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在信里写道：“我很想家。”", "target_word": "写道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明在日记中写道：“今天很开心。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上写道：“明天会下雨。”", "target_word": "写道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在黑板上写道：“好好学习。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在卡片上写道：“祝你生日快乐！”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作者在书的最后写道：“我们终会再见。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在便条上写道：“饭在桌上，快吃吧。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在信中写道：“这里的冬天很冷。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友在留言里写道：“我晚点到。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "用来引出某人所写下的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f262552-c10c-4507-925d-833b9d7cd991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13599, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写道", "is_correct": true, "explanation": "写道：表示写着说，引出在社交媒体上发布的文字，与后面的引文相符。"}, {"text": "吟道", "is_correct": false, "explanation": "语域：“吟道”多指吟诵诗词，与社交媒体上的书面发布不合。"}, {"text": "听到", "is_correct": false, "explanation": "语义：“听到”指接收信息，不是发布者本人引出自己所写的内容。"}, {"text": "唱道", "is_correct": false, "explanation": "语域：“唱道”带有文艺色彩，与社交媒体的日常语境不合。"}], "explanations": {"写道": "写道：表示写着说，引出在社交媒体上发布的文字，与后面的引文相符。", "吟道": "语域：“吟道”多指吟诵诗词，与社交媒体上的书面发布不合。", "听到": "语义：“听到”指接收信息，不是发布者本人引出自己所写的内容。", "唱道": "语域：“唱道”带有文艺色彩，与社交媒体的日常语境不合。"}, "sentence_index": 0, "correct_answer": "写道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在电话里写道：“我马上到。”", "explanation": "这里应该用〈说道〉。电话里传达的是口头话语，不是书面写下的内容，“写道”不能用于此处。"}, {"text": "他站在山顶上写道：“我们赢了！”", "explanation": "这里应该用〈喊道〉。在山顶上是大声喊出来的，不是写下来的，“写道”指书面写着说。"}, {"text": "他低声写道：“你来了吗？”", "explanation": "这里应该用〈问道〉。低声说话是口头的，且引出的是提问，“写道”只用于书面内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写道", "is_correct": true, "explanation": "写道：“作者在书的最后”指书面写下，与后面的引文相符。"}, {"text": "哭喊", "is_correct": false, "explanation": "语义：“哭喊”是哭着大声叫出来，与书中写下的文字不符。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：“朗读”是出声地读，不是书写行为，与“作者在书的最后”不符。"}, {"text": "耳语", "is_correct": false, "explanation": "搭配：“耳语”指悄悄地说话，不与“书的最后”搭配。"}], "explanations": {"写道": "写道：“作者在书的最后”指书面写下，与后面的引文相符。", "哭喊": "语义：“哭喊”是哭着大声叫出来，与书中写下的文字不符。", "朗读": "语义：“朗读”是出声地读，不是书写行为，与“作者在书的最后”不符。", "耳语": "搭配：“耳语”指悄悄地说话，不与“书的最后”搭配。"}, "sentence_index": 6, "correct_answer": "写道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他轻声写道：“好的，我明天去。”", "explanation": "这里应该用〈答道〉。轻声回应是口头说出的，“写道”指书面写下，不能用于此处。"}, {"text": "妈妈在厨房里写道：“菜快凉了。”", "explanation": "这里应该用〈嘀咕〉。在厨房里小声说的话是口头的，“写道”不能表示口头的嘀咕。"}, {"text": "校长在操场上写道：“放假三天。”", "explanation": "这里应该用〈宣布〉。当众宣布是口头的，“写道”引出的必须是书面内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在信里写道了：“我很快就回来。”", "corrected_sentence": "他在信里写道：“我很快就回来。”", "error_description": "错误：“写道了”，应为“写道”。“写道”本身已是完整的动词，表示写着说，后面不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作者在书的结尾写道了：“愿我们都能平安。”", "corrected_sentence": "作者在书的结尾写道：“愿我们都能平安。”", "error_description": "错误：“写道了”，应为“写道”。“写道”本身已是完整的动词，表示写着说，后面不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "答应别人的事情，表示一定会完成。", "primary_collocate": null, "pronunciation": "chéng nuò", "ipa": "ʈʂʰɤŋ˧˥ nuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "老板承诺下个月给大家加工资。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承诺过会每天给妈妈打电话。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经承诺了朋友，周末去帮他搬家。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她承诺不再迟到。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸承诺考试后带我去海边。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店承诺七天内可以免费退货。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承诺的事，从来都会做到。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你既然承诺了，就要认真完成。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司承诺三天内把东西送到家。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师承诺帮我们修改作文。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承诺了", "label": "完成体"}, {"form": "承诺过", "label": "经历体"}, {"form": "承诺书", "label": "复合词"}], "register": "中性", "sense_fingerprint": "答应别人并表示一定做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '998929c8-6bfe-49c6-be32-027efe40f4d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」带有讥讽的意味，与老板许诺加薪的语境相矛盾。"}, {"text": "承诺", "is_correct": true, "explanation": "正确答案。「老板承诺下个月加工资」表示老板答应将来一定做到。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：「赞美」的宾语多为人或作品，不能直接带「下个月给大家加工资」这样的事件小句。"}, {"text": "责怪", "is_correct": false, "explanation": "配价：「责怪」的对象是有过失的人，不能直接带这类加薪事件作宾语。"}], "explanations": {"嘲笑": "语义：「嘲笑」带有讥讽的意味，与老板许诺加薪的语境相矛盾。", "承诺": "正确答案。「老板承诺下个月加工资」表示老板答应将来一定做到。", "赞美": "配价：「赞美」的宾语多为人或作品，不能直接带「下个月给大家加工资」这样的事件小句。", "责怪": "配价：「责怪」的对象是有过失的人，不能直接带这类加薪事件作宾语。"}, "sentence_index": 0, "correct_answer": "承诺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常常承诺童年的往事。", "explanation": "这里应该用〈回忆〉。承诺是答应将来要做到的事，不能用于回想过去的事情。"}, {"text": "他终于承诺了自己的错误。", "explanation": "这里应该用〈承认〉。承诺指答应做到某事，不能用于承认已经犯下的错误。"}, {"text": "老师认真承诺了我的问题。", "explanation": "这里应该用〈回答〉。承诺是答应去做某事，不能用于回应别人提出的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：「忘记的事」不可能「从来都会做到」，与句意矛盾。"}, {"text": "承诺", "is_correct": true, "explanation": "正确答案。「他承诺的事」指答应过的事，与「从来都会做到」相呼应。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝的事」是不答应去做的事，与「从来都会做到」相抵触。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：「赞美」的宾语多为人或作品，「赞美的事」搭配不常见，且与「做到」不合。"}], "explanations": {"忘记": "语义：「忘记的事」不可能「从来都会做到」，与句意矛盾。", "承诺": "正确答案。「他承诺的事」指答应过的事，与「从来都会做到」相呼应。", "拒绝": "语义：「拒绝的事」是不答应去做的事，与「从来都会做到」相抵触。", "赞美": "配价：「赞美」的宾语多为人或作品，「赞美的事」搭配不常见，且与「做到」不合。"}, "sentence_index": 6, "correct_answer": "承诺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天承诺了运动会。", "explanation": "这里应该用〈参加〉。承诺指答应将来要完成的事，参加已经举行的活动不能说承诺。"}, {"text": "全家人承诺了妈妈的生日。", "explanation": "这里应该用〈庆祝〉。承诺是答应去做某事，庆祝生日不能用承诺。"}, {"text": "我们在河边承诺了一条鱼。", "explanation": "这里应该用〈钓到〉。承诺是答应去做某事，捕获到的鱼不能用承诺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把朋友承诺，下周六帮他搬家。", "corrected_sentence": "我向朋友承诺，下周六帮他搬家。", "error_description": "「把」字句不能这样引出承诺的对象，应改用「向」：「向朋友承诺」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他承诺着周末去帮我搬家。", "corrected_sentence": "他承诺了周末去帮我搬家。", "error_description": "体标错误：「承诺」是一次性完成的动作，表示动作已发生要用「了」，不能用「着」。应说「承诺了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5f9b08d-107e-41ce-aa93-ca9bee4811fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
