INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13602, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13602, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容说话、做事等正好符合分寸或实际情况，没有过度或不足。", "primary_collocate": null, "pronunciation": "qià rú qí fèn", "ipa": "tɕʰia˥˩ ɻu˧˥ tɕʰi˧˥ fən˥˩", "syllable_count": 4, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "恰如其分", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的回答恰如其分，老师很满意。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比喻用得恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的批评恰如其分，没有过重。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿得恰如其分，既大方又得体。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的称赞恰如其分，让我很高兴。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话恰如其分，大家都点头。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师恰如其分地表扬了每个学生。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个题目的难度恰如其分，大家都能做。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的感谢表达得恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰如其分地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "言行正合分寸、不过不及", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb5dee-9d44-4bb3-8c39-0659efa57b2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恰如其分", "is_correct": true, "explanation": "正确。“恰如其分地诠释”表示分寸得当地说明，与后文的“希望”相符。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”与后文“具象而坚韧的希望”相矛盾。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与“凝聚起……的希望”的积极语境不符。"}, {"text": "荒唐", "is_correct": false, "explanation": "语义：“荒唐”与“凝聚起……的希望”的积极语境不符。"}], "explanations": {"恰如其分": "正确。“恰如其分地诠释”表示分寸得当地说明，与后文的“希望”相符。", "模糊": "语义：“模糊”与后文“具象而坚韧的希望”相矛盾。", "冷漠": "语义：“冷漠”与“凝聚起……的希望”的积极语境不符。", "荒唐": "语义：“荒唐”与“凝聚起……的希望”的积极语境不符。"}, "sentence_index": 0, "correct_answer": "恰如其分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他恰如其分地忘了带钥匙。", "explanation": "这里应该用〈不巧〉。恰如其分说的是言行分寸得当，不用来描述偶然发生的事，忘带钥匙这类事应说“不巧”。"}, {"text": "我们俩恰如其分地在车站相遇。", "explanation": "这里应该用〈恰巧〉。恰如其分说分寸得当，不表示偶然相遇。"}, {"text": "这份合同恰如其分地被撕掉了。", "explanation": "这里应该用〈彻底〉。恰如其分说的是分寸得当，不表示程度彻底或造成损坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恰如其分", "is_correct": true, "explanation": "正确。“他说的话恰如其分”表示说话分寸得当，与“大家都点头”相符。"}, {"text": "荒谬", "is_correct": false, "explanation": "语义：“荒谬”与“大家都点头”的认可相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写人的体形，不能用来形容说话的内容。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：“粗鲁”与“大家都点头”的认可相矛盾。"}], "explanations": {"恰如其分": "正确。“他说的话恰如其分”表示说话分寸得当，与“大家都点头”相符。", "荒谬": "语义：“荒谬”与“大家都点头”的认可相矛盾。", "高大": "体貌：“高大”描写人的体形，不能用来形容说话的内容。", "粗鲁": "语义：“粗鲁”与“大家都点头”的认可相矛盾。"}, "sentence_index": 6, "correct_answer": "恰如其分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他恰如其分地跑丢了那只猫。", "explanation": "这里应该用〈居然〉。恰如其分说的是分寸得当，不表示出乎意料。"}, {"text": "他在街上恰如其分地撞见了老师。", "explanation": "这里应该用〈恰巧〉。恰如其分表示分寸得当，不表示偶然遇见。"}, {"text": "他恰如其分地赶上了末班车。", "explanation": "这里应该用〈幸好〉。恰如其分说的是分寸得当，不表示凑巧或侥幸赶上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的回答恰如其分地，让人很满意。", "corrected_sentence": "他的回答恰如其分，让人很满意。", "error_description": "多余的“地”：“恰如其分”在这里作谓语，描写“回答”的分寸，不加“地”。“恰如其分地”只用于修饰后面的动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说地恰如其分，大家都点头。", "corrected_sentence": "他说得恰如其分，大家都点头。", "error_description": "得/地用错：补语前应用“得”，应说“说得恰如其分”，不能用“地”说成“说地恰如其分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人类活动导致自然环境严重破坏，威胁生物生存的状态。", "primary_collocate": null, "pronunciation": "shēng tài wēi jī", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ weɪ˥ tɕi˥", "syllable_count": 4, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "生态危机", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "全球生态危机越来越严重了。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林不断减少，会带来生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，我们正面对一场生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了解决生态危机，各国开始合作。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态危机让很多动物失去了家。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度开发是生态危机的原因之一。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是海洋生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家一直在研究怎么应对生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能忽视眼前的生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场生态危机", "label": "量词"}], "register": "书面语", "sense_fingerprint": "人类破坏环境、威胁生物生存的严重局面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f262552-c10c-4507-925d-833b9d7cd991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态危机", "is_correct": true, "explanation": "正确。“生态危机”指人类活动破坏环境、威胁生物生存的状况，与句中“种树”“承诺”的环保语境相符。"}, {"text": "篮球比赛", "is_correct": false, "explanation": "语义：“全球……背景下”需要社会或环境状况作背景，“篮球比赛”与句中种树、希望的环保语境无关。"}, {"text": "生日派对", "is_correct": false, "explanation": "语义：生日派对不能充当句中的背景，与“种下的不只是树”的环保意涵不合。"}, {"text": "午饭时间", "is_correct": false, "explanation": "语义：“午饭时间”是日常作息，不能用作“全球……背景”，与环保语境不符。"}], "explanations": {"生态危机": "正确。“生态危机”指人类活动破坏环境、威胁生物生存的状况，与句中“种树”“承诺”的环保语境相符。", "篮球比赛": "语义：“全球……背景下”需要社会或环境状况作背景，“篮球比赛”与句中种树、希望的环保语境无关。", "生日派对": "语义：生日派对不能充当句中的背景，与“种下的不只是树”的环保意涵不合。", "午饭时间": "语义：“午饭时间”是日常作息，不能用作“全球……背景”，与环保语境不符。"}, "sentence_index": 0, "correct_answer": "生态危机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要保护生态危机。", "explanation": "这里应该用〈生态环境〉。“生态危机”指环境遭破坏的状况，不能被保护，保护的对象应是生态环境。"}, {"text": "我们正面对一群生态危机。", "explanation": "这里量词应用〈场〉。“群”用于人或动物的集合，“生态危机”是一场局面，不能说“一群”。"}, {"text": "我们要加强生态危机。", "explanation": "这里应该用〈生态保护〉。“加强”的对象是保护工作或力度，“生态危机”是一种状况，不能加强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态危机", "is_correct": true, "explanation": "正确。“过度开发”造成环境破坏，是“生态危机”的原因之一，与句意相符。"}, {"text": "生日派对", "is_correct": false, "explanation": "语义：过度开发与生日派对之间没有因果关系，不能作为其原因。"}, {"text": "长寿", "is_correct": false, "explanation": "语义：“长寿”是人们追求的积极状态，过度开发并不是它的原因。"}, {"text": "快乐", "is_correct": false, "explanation": "搭配：“……的原因之一”多用于导致负面结果的事物，说过度开发是“快乐”的原因，搭配不当，句意矛盾。"}], "explanations": {"生态危机": "正确。“过度开发”造成环境破坏，是“生态危机”的原因之一，与句意相符。", "生日派对": "语义：过度开发与生日派对之间没有因果关系，不能作为其原因。", "长寿": "语义：“长寿”是人们追求的积极状态，过度开发并不是它的原因。", "快乐": "搭配：“……的原因之一”多用于导致负面结果的事物，说过度开发是“快乐”的原因，搭配不当，句意矛盾。"}, "sentence_index": 6, "correct_answer": "生态危机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人类应该维护生态危机。", "explanation": "这里应该用〈生态平衡〉。“维护”的对象是平衡、秩序，“生态危机”是需要解决的状况，不能维护。"}, {"text": "我们要提高生态危机。", "explanation": "这里应该用〈环境质量〉。“提高”用于质量、水平，“生态危机”是一种状况，不能提高。"}, {"text": "游客们在山里欣赏生态危机。", "explanation": "这里应该用〈自然风光〉。“欣赏”的对象是美景，“生态危机”是令人担忧的状况，不能欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只严重的生态危机。", "corrected_sentence": "这是一场严重的生态危机。", "error_description": "量词错误：“生态危机”的量词应为“场”。“只”用于动物等有形个体，不能用来修饰“危机”。正确为“一场严重的生态危机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海洋正面临严重的生态危机们。", "corrected_sentence": "海洋正面临严重的生态危机。", "error_description": "语法错误：“危机”是抽象名词，不能加复数后缀“们”。“生态危机们”应改为“生态危机”，正确为“海洋正面临严重的生态危机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抽象", "is_correct": true, "explanation": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。"}, {"text": "温和", "is_correct": false, "explanation": "与“具象”无反义关系，“温和”形容性情或气候，与具象、抽象之分无关。"}, {"text": "巨大", "is_correct": false, "explanation": "与“具象”无反义关系，“巨大”形容体积或规模，不与“具象”相对。"}, {"text": "流畅", "is_correct": false, "explanation": "与“具象”无反义关系，“流畅”形容文字或动作，不属于具象与抽象的对立。"}], "correct_answer": "抽象", "explanations": {"抽象": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。", "温和": "与“具象”无反义关系，“温和”形容性情或气候，与具象、抽象之分无关。", "巨大": "与“具象”无反义关系，“巨大”形容体积或规模，不与“具象”相对。", "流畅": "与“具象”无反义关系，“流畅”形容文字或动作，不属于具象与抽象的对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抽象", "is_correct": true, "explanation": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "与“具象”无反义关系，“迟钝”形容反应慢，与具象、抽象的对立无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“具象”无反义关系，“粗糙”形容质地不光滑，不属于具象与抽象的对立。"}, {"text": "轻浮", "is_correct": false, "explanation": "与“具象”无反义关系，“轻浮”形容态度不庄重，与此义项无关。"}], "correct_answer": "抽象", "explanations": {"抽象": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。", "迟钝": "与“具象”无反义关系，“迟钝”形容反应慢，与具象、抽象的对立无关。", "粗糙": "与“具象”无反义关系，“粗糙”形容质地不光滑，不属于具象与抽象的对立。", "轻浮": "与“具象”无反义关系，“轻浮”形容态度不庄重，与此义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指具体、实在、可以感知的形象或事物，与抽象相对。", "primary_collocate": null, "pronunciation": "jù xiàng", "ipa": "tɕy˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "具象", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这幅画很具象，一眼就能看懂。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽象的想法要用具象的例子来说明。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用具象的图片解释这个词。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的诗里有很多具象的画面。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雕塑比那个更具象。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢具象的东西，不爱抽象的理论。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把爱写得很具象，像一杯热茶。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设计太具象了，没有想象的空间。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "具象的描写让读者好像看到了那座山。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "具象化", "label": "复合"}], "register": "书面语", "sense_fingerprint": "具体可感、与抽象相对的形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f262552-c10c-4507-925d-833b9d7cd991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "具象", "is_correct": true, "explanation": "正确。具象（jù xiàng）：具体可感的形象或事物，与抽象相对。"}, {"text": "巨响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，“巨响”意思是很大的响声。"}, {"text": "去向", "is_correct": false, "explanation": "qù 与 jù 声母不同，“去向”意思是去往的方向。"}, {"text": "巨匠", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同，“巨匠”意思是技艺高超的大师。"}, {"text": "巨量", "is_correct": false, "explanation": "liàng 与 xiàng 声母不同，“巨量”意思是极大的数量。"}], "explanations": {"具象": "正确。具象（jù xiàng）：具体可感的形象或事物，与抽象相对。", "巨响": "xiǎng（第三声）与 xiàng（第四声）声调不同，“巨响”意思是很大的响声。", "去向": "qù 与 jù 声母不同，“去向”意思是去往的方向。", "巨匠": "jiàng 与 xiàng 声母不同，“巨匠”意思是技艺高超的大师。", "巨量": "liàng 与 xiàng 声母不同，“巨量”意思是极大的数量。"}, "sentence_index": null, "correct_answer": "具象"}, "level_3": {"options": [{"text": "具象", "is_correct": true, "explanation": "正确。“具象而坚韧的希望”指具体可感、有形象的希望，与句中具体的种树行动相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指含水分多的状态，不能修饰“希望”，与句意不合。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”是价格或价值的说法，不能修饰抽象的“希望”。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”描写声音，无法用来形容“坚韧的希望”。"}], "explanations": {"具象": "正确。“具象而坚韧的希望”指具体可感、有形象的希望，与句中具体的种树行动相符。", "潮湿": "语义：“潮湿”指含水分多的状态，不能修饰“希望”，与句意不合。", "便宜": "搭配：“便宜”是价格或价值的说法，不能修饰抽象的“希望”。", "吵闹": "语义：“吵闹”描写声音，无法用来形容“坚韧的希望”。"}, "sentence_index": 0, "correct_answer": "具象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该制定具象的计划。", "explanation": "这里应该用〈具体〉。“具象”指可感知的形象或事物，“计划”不是形象，应说“具体的计划”。"}, {"text": "学生们在课堂上讨论具象的理论。", "explanation": "这里应该用〈抽象〉。“具象”与“抽象”相对，指可感知的事物；理论是抽象的，不能说“具象的理论”。"}, {"text": "这套规则非常具象，我们一看就懂。", "explanation": "这里应该用〈直观〉。“具象”指具体可感的形象，规则不是形象；表示一看就明白要用“直观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具象", "is_correct": true, "explanation": "正确。“具象的东西”与后半句“抽象的理论”相对，指可感知的事物。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：若填“抽象”，“孩子喜欢抽象的东西，不爱抽象的理论”前后矛盾，句意不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“孩子喜欢潮湿的东西”不合常理，与句中指可感事物的语境不符。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”是温度描写，与“喜欢……的东西”的搭配不当。"}], "explanations": {"具象": "正确。“具象的东西”与后半句“抽象的理论”相对，指可感知的事物。", "抽象": "语义：若填“抽象”，“孩子喜欢抽象的东西，不爱抽象的理论”前后矛盾，句意不通。", "潮湿": "语义：“孩子喜欢潮湿的东西”不合常理，与句中指可感事物的语境不符。", "寒冷": "搭配：“寒冷”是温度描写，与“喜欢……的东西”的搭配不当。"}, "sentence_index": 6, "correct_answer": "具象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的诗里有很多具象的情感。", "explanation": "这里应该用〈抽象〉。“具象”指可感知的形象或事物，情感是抽象的，不能说“具象的情感”。"}, {"text": "这篇论文的逻辑很具象。", "explanation": "这里应该用〈清晰〉。“具象”指可感知的形象，逻辑是抽象的，不能说“逻辑很具象”。"}, {"text": "她的内心很具象，大家都看得到。", "explanation": "这里应该用〈抽象〉。“具象”指可以看见、摸到的事物，内心活动是抽象的，不能说“内心很具象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那座山描写很具象。", "corrected_sentence": "他把那座山描写得很具象。", "error_description": "补语标记遗漏：“描写”与“很具象”之间需要用“得”连接，应为“描写得很具象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把这个想法具象。", "corrected_sentence": "我们要把这个想法具象化。", "error_description": "词形错误：使想法变得具体可感要用“具象化”。“具象”单独作谓语不能带“把”字宾语，应为“具象化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13605, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软弱", "is_correct": true, "explanation": "软弱与坚韧意义相反，指意志薄弱，遇到困难容易屈服。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮与“坚韧”没有反义关系，指光线或颜色明亮。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松与“坚韧”没有反义关系，指心情或负担不沉重。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈与“坚韧”没有反义关系，指情绪高涨或场面兴奋。"}], "correct_answer": "软弱", "explanations": {"软弱": "软弱与坚韧意义相反，指意志薄弱，遇到困难容易屈服。", "明亮": "明亮与“坚韧”没有反义关系，指光线或颜色明亮。", "轻松": "轻松与“坚韧”没有反义关系，指心情或负担不沉重。", "热烈": "热烈与“坚韧”没有反义关系，指情绪高涨或场面兴奋。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
