INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13605, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指在困难或压力面前不屈服、不退缩，意志坚定。", "primary_collocate": null, "pronunciation": "jiān rèn", "ipa": "tɕiɛn˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "这次本地行动，给人们带来了一种具象而坚韧的希望。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个坚韧的人，从不轻易放弃。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有坚韧的意志，从不退缩。", "target_word": "坚韧", "complexity_tier": "T3", "furigana": "tā yǒu jiān rèn de yì zhì cóng bù tuì suō", "sentence_source": "generated"}, {"text": "面对困难，他表现得很坚韧。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚韧的意志帮他走过了最难的时期。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位母亲坚韧地撑起了整个家。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期训练让运动员变得更加坚韧。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用坚韧的精神完成了比赛。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坚韧地生活着。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有坚韧的性格，很难做成大事。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚韧不拔", "label": "复合"}], "register": "书面语", "sense_fingerprint": "面对困难不屈服、意志坚定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f262552-c10c-4507-925d-833b9d7cd991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚韧", "is_correct": true, "explanation": "正确。“具象而坚韧的希望”中，坚韧修饰希望，说希望在困境中依然不屈。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：与同句的“具象”相反，前后矛盾。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“希望”带有温度，与“冰冷”冲突。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不修饰“希望”这类抽象的心理状态。"}], "explanations": {"坚韧": "正确。“具象而坚韧的希望”中，坚韧修饰希望，说希望在困境中依然不屈。", "抽象": "语义：与同句的“具象”相反，前后矛盾。", "冰冷": "语义：“希望”带有温度，与“冰冷”冲突。", "热闹": "搭配：“热闹”形容场面或气氛，不修饰“希望”这类抽象的心理状态。"}, "sentence_index": 0, "correct_answer": "坚韧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这个决定很坚韧，从不动摇。", "explanation": "这里应该用〈坚定〉。坚韧指在困难、压力面前忍耐不屈，对决定、立场的不变用坚定。"}, {"text": "这种股票的价格很坚韧，一直没有下降。", "explanation": "这里应该用〈坚挺〉。坚韧形容面对困难时的忍耐，形容价格稳定、不下跌要用坚挺。"}, {"text": "这块石头很坚韧，一碰就碎。", "explanation": "这里应该用〈易碎〉。坚韧指不易折断，一碰就碎要用易碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚韧", "is_correct": true, "explanation": "正确。“长期训练让运动员变得更加坚韧”：训练的结果是意志和体能变强。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：长期训练的结果不会是“懒散”，与句意相反。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”多形容感官或反应，不用于描写运动员的意志。"}, {"text": "轻浮", "is_correct": false, "explanation": "语义：“轻浮”与训练应带来的稳重相悖。"}], "explanations": {"坚韧": "正确。“长期训练让运动员变得更加坚韧”：训练的结果是意志和体能变强。", "懒散": "语义：长期训练的结果不会是“懒散”，与句意相反。", "迟钝": "搭配：“迟钝”多形容感官或反应，不用于描写运动员的意志。", "轻浮": "语义：“轻浮”与训练应带来的稳重相悖。"}, "sentence_index": 6, "correct_answer": "坚韧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他遇到困难就打退堂鼓，态度却很坚韧。", "explanation": "这里应该用〈消极〉。坚韧指面对困难不退缩，遇困难就打退堂鼓要用消极。"}, {"text": "他的脾气很坚韧，一点就着。", "explanation": "这里应该用〈暴躁〉。坚韧形容面对困难时的忍耐，形容脾气急、易发火要用暴躁。"}, {"text": "这位老师讲话很坚韧。", "explanation": "这里应该用〈温和〉。坚韧形容面对困难时的忍耐，说话的语气要用温和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个孩子的性格很坚韧地，从来不哭。", "corrected_sentence": "那个孩子的性格很坚韧，从来不哭。", "error_description": "错误：“很坚韧地”。“坚韧”作谓语时直接说“很坚韧”，“地”只用于修饰动词，这里多加了“地”，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用坚韧地意志完成了长跑。", "corrected_sentence": "他用坚韧的意志完成了长跑。", "error_description": "错误：“坚韧地意志”。修饰名词“意志”要用“的”，“地”修饰动词，应改为“坚韧的意志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd25e2e-0d83-4cd1-ade2-7f0532131aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
